window.CBT_DATA=window.CBT_DATA||{};window.CBT_DATA["written/2022-3"]={"track":"written","round":"2022-3","questions":[{"id":"written-2022-3-1","no":1,"unit":"소프트웨어 설계","q":"UML 모델에서 어떤 사물의 명세가 바뀌면 다른 사물에 영향을 미치며, 일반적으로 한 클래스가 다른 클래스를 오퍼레이션의 매개 변수로 사용할 때 나타나는 관계는?","choices":["Realization","Dependency","Generalization","Association"],"ans":2,"exp":{"concept":"UML 관계 중 의존(Dependency) 관계는 한 클래스가 다른 클래스를 잠깐 빌려 쓰는 관계다. 메서드의 매개변수나 지역 변수로 다른 클래스를 사용할 때 생기며, 빌려 쓰는 대상의 명세가 바뀌면 사용하는 쪽도 영향을 받는다. 점선 화살표로 그린다.","choices":[{"verdict":"오답","why":"실체화(Realization)는 인터페이스에 정의된 기능을 클래스가 실제로 구현하는 관계로, 속이 빈 삼각형 화살표와 점선으로 표현한다."},{"verdict":"정답","why":"의존(Dependency)은 한 클래스가 다른 클래스를 오퍼레이션의 매개변수 등으로 짧게 사용하는 관계이며, 사용 대상이 바뀌면 영향을 받는다."},{"verdict":"오답","why":"일반화(Generalization)는 상위 클래스와 하위 클래스 사이의 상속(is-a) 관계를 나타낸다."},{"verdict":"오답","why":"연관(Association)은 두 클래스가 서로 의미 있게 연결되어 지속적으로 참조하는 관계로, 실선으로 표현한다."}],"keywords":[{"term":"의존(Dependency)","desc":"매개변수 등으로 잠깐 사용하는 관계, 점선 화살표"},{"term":"연관(Association)","desc":"지속적으로 연결된 관계, 실선"},{"term":"일반화(Generalization)","desc":"상속 관계, 속이 빈 삼각형 실선 화살표"},{"term":"실체화(Realization)","desc":"인터페이스를 구현하는 관계, 속이 빈 삼각형 점선 화살표"}],"memo":"매개변수로 잠깐 쓰면 의존, 필드로 계속 들고 있으면 연관이다."}},{"id":"written-2022-3-2","no":2,"unit":"소프트웨어 설계","q":"모바일 기기에서 쓰이는 NUI 인터페이스에 해당하지 않는 것은?","choices":["Press","Flow","Flick","Pinch"],"ans":2,"exp":{"concept":"NUI(Natural User Interface)는 사용자의 말이나 손동작처럼 자연스러운 행동으로 기기를 조작하는 인터페이스다. 스마트폰 화면에서 쓰는 대표 제스처로 탭(Tap), 더블 탭(Double Tap), 드래그(Drag), 팬(Pan), 프레스(Press), 플릭(Flick), 핀치(Pinch)가 있다.","choices":[{"verdict":"오답","why":"프레스(Press)는 화면을 길게 누르는 동작으로 모바일 제스처에 해당한다."},{"verdict":"정답","why":"플로우(Flow)는 모바일 터치 제스처의 이름이 아니다."},{"verdict":"오답","why":"플릭(Flick)은 화면을 손가락으로 빠르게 튕기듯 넘기는 동작으로 모바일 제스처에 해당한다."},{"verdict":"오답","why":"핀치(Pinch)는 두 손가락을 오므리거나 벌려 화면을 축소·확대하는 동작으로 모바일 제스처에 해당한다."}],"keywords":[{"term":"NUI(Natural User Interface)","desc":"말이나 몸짓 등 자연스러운 행동으로 조작하는 인터페이스"},{"term":"플릭(Flick)","desc":"빠르게 튕겨 넘기는 동작"},{"term":"핀치(Pinch)","desc":"두 손가락으로 확대·축소하는 동작"},{"term":"프레스(Press)","desc":"길게 누르는 동작"}],"memo":"손가락이 실제로 하는 동작(누르기, 튕기기, 오므리기)만 제스처다. 흐름(Flow)은 손동작이 아니다."}},{"id":"written-2022-3-3","no":3,"unit":"소프트웨어 설계","q":"다음은 어떤 프로그램의 구조를 나타낸 것이다. 모듈 F의 fan-in과 fan-out 수는 각각 얼마인가?<img class=\"q-img\" src=\"data/img/d7bda0b4c9bd8804558e42ff6ef1f49f.png\" width=\"498\" alt=\"문항 원본 자료\">","choices":["fan-in : 2, fan-out : 3","fan-in : 3, fan-out : 2","fan-in : 1, fan-out : 2","fan-in : 2, fan-out : 1"],"ans":2,"exp":{"concept":"팬인(fan-in)은 어떤 모듈을 호출하는 상위 모듈의 수, 팬아웃(fan-out)은 그 모듈이 호출하는 하위 모듈의 수다. 구조도에서 모듈 위쪽으로 연결된 선의 수가 팬인, 아래쪽으로 연결된 선의 수가 팬아웃이다. 그림에서 F의 위로는 B, C, D가 연결되고 아래로는 G, H가 연결된다.","choices":[{"verdict":"오답","why":"F를 호출하는 상위 모듈은 B, C, D의 3개이므로 팬인이 2가 아니다."},{"verdict":"정답","why":"F 위쪽으로 B, C, D가 연결되어 팬인은 3, 아래쪽으로 G, H가 연결되어 팬아웃은 2다."},{"verdict":"오답","why":"팬인을 1로 보면 B, C, D 중 두 연결을 빠뜨린 것이다."},{"verdict":"오답","why":"팬인과 팬아웃 모두 틀렸다. F가 호출하는 모듈은 G, H 두 개이므로 팬아웃은 2다."}],"keywords":[{"term":"팬인(fan-in)","desc":"나를 호출하는 상위 모듈의 수, 위쪽 선의 개수"},{"term":"팬아웃(fan-out)","desc":"내가 호출하는 하위 모듈의 수, 아래쪽 선의 개수"},{"term":"구조도(Structure Chart)","desc":"모듈 사이의 호출 관계를 계층으로 나타낸 그림"}],"memo":"팬인은 들어오는(in) 선, 즉 위에서 내려오는 선을 센다. 위로 세면 팬인, 아래로 세면 팬아웃이다."}},{"id":"written-2022-3-4","no":4,"unit":"소프트웨어 설계","q":"소프트웨어 공학에서 워크스루(Walkthrough)에 관한 설명 중 틀린 것은?","choices":["단순한 테스트 케이스를 활용하여 프로덕트를 수작업으로 수행해 보는 것이다.","인스펙션(Inspection)과 같은 의미를 지닌다.","사용사례를 확장해 명세하거나 설계 다이어그램, 원시코드, 테스트 케이스 등에 적용할 수 있다.","복잡한 알고리즘이나 반복, 실시간 동작, 병행 처리 같은 기능이나 동작을 이해하고자 할 때 유용하다."],"ans":2,"exp":{"concept":"워크스루(Walkthrough)는 검토 자료를 회의 전에 미리 나눠 주고, 짧은 회의에서 단순한 테스트 케이스로 제품을 손으로 따라가 보며 오류를 찾는 비공식 검토 방법이다. 인스펙션(Inspection)은 훈련된 전문가가 정해진 절차와 체크리스트에 따라 수행하는 공식적인 검토로, 워크스루와는 다르다.","choices":[{"verdict":"오답","why":"워크스루는 단순한 테스트 케이스로 제품을 수작업으로 수행해 보는 검토이므로 옳은 설명이다."},{"verdict":"정답","why":"워크스루는 비공식적 검토이고 인스펙션은 절차가 정해진 공식적 검토이므로 같은 의미가 아니다."},{"verdict":"오답","why":"워크스루는 사용 사례 명세, 설계 다이어그램, 원시 코드, 테스트 케이스 등 다양한 산출물에 적용할 수 있으므로 옳은 설명이다."},{"verdict":"오답","why":"복잡한 알고리즘, 반복, 실시간 동작, 병행 처리처럼 머릿속으로 따라가기 어려운 기능을 이해하는 데 유용하므로 옳은 설명이다."}],"keywords":[{"term":"워크스루(Walkthrough)","desc":"자료를 미리 배포하고 짧은 회의로 오류를 찾는 비공식 검토"},{"term":"인스펙션(Inspection)","desc":"전문가가 정해진 절차에 따라 수행하는 공식 검토"},{"term":"동료 검토(Peer Review)","desc":"작성자가 설명하고 동료들이 결함을 찾는 검토"}],"memo":"워크스루는 걸어가며 훑어보기(비공식), 인스펙션은 검사(공식)라고 구분하면 헷갈리지 않는다."}},{"id":"written-2022-3-5","no":5,"unit":"소프트웨어 설계","q":"그래픽 표기법을 활용해 소프트웨어 구성 요소를 모델링하는 럼바우 분석 기법에 해당하지 않는 것은?","choices":["객체 모델링","동적 모델링","기능 모델링","블랙박스 분석 모델링"],"ans":4,"exp":{"concept":"럼바우(Rumbaugh)의 객체 모델링 기법(OMT)은 그래픽 표기법으로 시스템을 세 가지 관점에서 모델링한다. 객체 모델링은 객체와 관계를, 동적 모델링은 시간에 따른 상태 변화를, 기능 모델링은 자료 흐름을 표현한다. 분석 순서는 객체, 동적, 기능 모델링 순이다.","choices":[{"verdict":"오답","why":"객체 모델링은 객체 다이어그램으로 객체들과 그 관계를 표현하는 럼바우 기법의 첫 단계다."},{"verdict":"오답","why":"동적 모델링은 상태 다이어그램으로 시간 흐름에 따른 객체의 상태 변화를 표현하는 럼바우 기법의 단계다."},{"verdict":"오답","why":"기능 모델링은 자료 흐름도(DFD)로 입력이 출력으로 바뀌는 과정을 표현하는 럼바우 기법의 단계다."},{"verdict":"정답","why":"블랙박스 분석 모델링은 럼바우 분석 기법에 포함되지 않는다."}],"keywords":[{"term":"럼바우(Rumbaugh) OMT","desc":"객체·동적·기능 모델링으로 이루어진 객체지향 분석 기법"},{"term":"객체 모델링","desc":"객체 다이어그램, 객체와 관계 표현"},{"term":"동적 모델링","desc":"상태 다이어그램, 상태 변화 표현"},{"term":"기능 모델링","desc":"자료 흐름도(DFD), 데이터 흐름 표현"}],"memo":"럼바우는 '객동기'(객체-동적-기능) 순서로 외운다."}},{"id":"written-2022-3-6","no":6,"unit":"소프트웨어 설계","q":"객체지향 설계 원칙 가운데 SOLID 원칙이라 불리는 것에 해당하지 않는 것은 다음 중 무엇인가?","choices":["LSP(Liskov Substitution Principle)","ISP(Interface Segregation Principle)","SSO(Single Sign On)","DIP(Dependency Inversion Principle)"],"ans":3,"exp":{"concept":"SOLID는 객체지향 설계에서 지켜야 할 다섯 원칙의 첫 글자를 모은 것이다. SRP(단일 책임), OCP(개방-폐쇄), LSP(리스코프 치환), ISP(인터페이스 분리), DIP(의존 역전)가 해당한다.","choices":[{"verdict":"오답","why":"LSP(리스코프 치환 원칙)는 하위 클래스가 상위 클래스를 대신해도 프로그램이 올바르게 동작해야 한다는 SOLID 원칙이다."},{"verdict":"오답","why":"ISP(인터페이스 분리 원칙)는 클라이언트가 쓰지 않는 메서드에 의존하지 않도록 인터페이스를 작게 나누라는 SOLID 원칙이다."},{"verdict":"정답","why":"SSO(Single Sign On)는 한 번의 로그인으로 여러 시스템을 이용하게 하는 인증 방식으로, 설계 원칙이 아니다."},{"verdict":"오답","why":"DIP(의존 역전 원칙)는 구체적인 클래스가 아니라 추상화(인터페이스)에 의존하라는 SOLID 원칙이다."}],"keywords":[{"term":"SRP(Single Responsibility Principle)","desc":"클래스는 하나의 책임만 가진다"},{"term":"OCP(Open-Closed Principle)","desc":"확장에는 열려 있고 변경에는 닫혀 있다"},{"term":"LSP(Liskov Substitution Principle)","desc":"하위 클래스는 상위 클래스를 대체할 수 있어야 한다"},{"term":"ISP(Interface Segregation Principle)","desc":"인터페이스를 사용처별로 작게 나눈다"},{"term":"DIP(Dependency Inversion Principle)","desc":"추상화에 의존한다"}],"memo":"S-O-L-I-D 다섯 글자에 각각 원칙이 하나씩 대응한다. SSO처럼 글자만 비슷한 보안 용어에 속지 말자."}},{"id":"written-2022-3-7","no":7,"unit":"소프트웨어 설계","q":"객체지향 개념에서 서로 연관된 데이터와 함수를 하나로 묶어 외부와의 경계를 두고, 필요한 인터페이스만 밖으로 드러내는 과정을 무엇이라 하는가?","choices":["캡슐화(Encapsulation)","메시지(Message)","다형성(Polymorphism)","상속(Inheritance)"],"ans":1,"exp":{"concept":"캡슐화(Encapsulation)는 관련된 데이터와 그 데이터를 다루는 함수를 하나의 캡슐(클래스)로 묶고, 내부는 숨긴 채 필요한 인터페이스만 밖으로 보여 주는 것이다. 알약 캡슐 속 성분을 몰라도 삼키기만 하면 되는 것처럼, 사용자는 내부 구현을 몰라도 공개된 기능만 쓰면 된다.","choices":[{"verdict":"정답","why":"데이터와 함수를 하나로 묶고 필요한 인터페이스만 공개하는 것이 캡슐화의 정의다."},{"verdict":"오답","why":"메시지(Message)는 객체에게 어떤 동작을 하라고 보내는 요청(명령)이다."},{"verdict":"오답","why":"다형성(Polymorphism)은 같은 이름의 메시지에 객체마다 다르게 반응하는 성질이다."},{"verdict":"오답","why":"상속(Inheritance)은 상위 클래스의 속성과 메서드를 하위 클래스가 물려받는 것이다."}],"keywords":[{"term":"캡슐화(Encapsulation)","desc":"데이터와 함수를 묶고 내부를 숨기는 것"},{"term":"정보 은닉(Information Hiding)","desc":"내부 구현을 외부에 감추는 것"},{"term":"다형성(Polymorphism)","desc":"같은 메시지에 객체마다 다르게 반응"},{"term":"상속(Inheritance)","desc":"상위 클래스의 기능을 물려받음"}],"memo":"묶고(캡슐) 숨긴다(은닉)를 함께 기억하자."}},{"id":"written-2022-3-8","no":8,"unit":"소프트웨어 설계","q":"파이프 필터 형태의 소프트웨어 아키텍처에 관한 설명으로 옳은 것은?","choices":["3개의 서브시스템(모델, 뷰, 제어)으로 이루어져 있다.","서브시스템이 입력 데이터를 받아 처리한 뒤 그 결과를 다음 서브시스템으로 넘겨주는 과정이 반복된다.","계층 모델이라고 부르기도 한다.","노드와 간선으로 이루어진다."],"ans":2,"exp":{"concept":"파이프-필터(Pipe-Filter) 구조는 데이터가 파이프를 따라 흐르면서 각 필터(서브시스템)가 입력을 받아 처리한 뒤 결과를 다음 필터로 넘기는 구조다. 공장의 컨베이어 벨트처럼 단계마다 가공이 이어지며, 유닉스의 파이프(|) 명령이 대표적인 예다.","choices":[{"verdict":"오답","why":"모델, 뷰, 컨트롤러 세 서브시스템으로 이루어진 구조는 MVC(Model-View-Controller) 패턴이다."},{"verdict":"정답","why":"입력을 받아 처리하고 결과를 다음 서브시스템으로 넘기는 과정을 반복하는 것이 파이프-필터 구조의 특징이다."},{"verdict":"오답","why":"계층 모델(Layered)이라고 부르는 것은 시스템을 여러 층으로 나누어 위아래 층끼리만 통신하는 레이어 패턴이다."},{"verdict":"오답","why":"노드와 간선으로 이루어진다는 것은 그래프 구조에 대한 설명으로, 파이프-필터 구조를 설명하는 특징이 아니다."}],"keywords":[{"term":"파이프-필터(Pipe-Filter)","desc":"데이터가 필터를 차례로 거치며 처리되는 구조"},{"term":"MVC(Model-View-Controller)","desc":"모델, 뷰, 컨트롤러로 나눈 구조"},{"term":"레이어 패턴(Layered)","desc":"시스템을 계층으로 나눈 구조"},{"term":"클라이언트-서버","desc":"서버가 서비스를 제공하고 클라이언트가 요청하는 구조"}],"memo":"파이프는 데이터가 지나는 관, 필터는 데이터를 거르는 처리 단계라고 그려 보면 쉽다."}},{"id":"written-2022-3-9","no":9,"unit":"소프트웨어 설계","q":"DOS나 Unix 등의 운영체제에서 조작을 위해 대표적으로 사용하던 것으로, 정해진 명령 문자열을 입력해 시스템을 조작하는 사용자 인터페이스(User Interface)는?","choices":["MUI(Mobile User Interface)","CLI(Command Line Interface)","CUI(Cell User Interface)","GUI(Graphical User Interface)"],"ans":2,"exp":{"concept":"CLI(Command Line Interface)는 키보드로 정해진 명령 문자열을 입력해 컴퓨터를 조작하는 방식이다. DOS나 유닉스의 명령 프롬프트가 대표적이다. 반대로 아이콘과 마우스로 조작하는 방식은 GUI다.","choices":[{"verdict":"오답","why":"MUI(Mobile User Interface)는 모바일 기기용 인터페이스를 가리키는 말로, 명령어 입력 방식이 아니다."},{"verdict":"정답","why":"CLI는 정해진 명령 문자열을 입력해 시스템을 조작하는 인터페이스로, DOS와 유닉스에서 대표적으로 사용했다."},{"verdict":"오답","why":"Cell User Interface라는 이름은 출제 범위의 표준 용어가 아니다."},{"verdict":"오답","why":"GUI(Graphical User Interface)는 아이콘, 창, 마우스 등 그래픽 요소로 조작하는 방식이다."}],"keywords":[{"term":"CLI(Command Line Interface)","desc":"명령어를 입력해 조작하는 인터페이스"},{"term":"GUI(Graphical User Interface)","desc":"그래픽 요소와 마우스로 조작"},{"term":"NUI(Natural User Interface)","desc":"말, 손동작 등 자연스러운 행동으로 조작"},{"term":"OUI(Organic User Interface)","desc":"모든 사물이 입출력 장치가 되는 인터페이스"}],"memo":"Command(명령) + Line(한 줄) = 한 줄씩 명령을 친다."}},{"id":"written-2022-3-10","no":10,"unit":"소프트웨어 설계","q":"객체에게 어떤 행위를 수행하도록 지시하는 명령을 무엇이라 하는가?","choices":["Package","Object","Message","Class"],"ans":3,"exp":{"concept":"객체지향에서 객체끼리는 메시지(Message)를 주고받으며 일을 시킨다. 메시지는 '이 동작을 수행하라'는 요청으로, 메시지를 받은 객체는 자기 메서드를 실행해 응답한다.","choices":[{"verdict":"오답","why":"패키지(Package)는 관련된 클래스나 요소를 묶어 놓은 그룹이다."},{"verdict":"오답","why":"객체(Object)는 데이터와 메서드를 가진 실체로, 메시지를 받는 쪽이지 명령 자체가 아니다."},{"verdict":"정답","why":"메시지(Message)는 객체에게 어떤 행위를 수행하도록 지시하는 요청이다."},{"verdict":"오답","why":"클래스(Class)는 같은 속성과 메서드를 가진 객체들을 만들기 위한 틀이다."}],"keywords":[{"term":"메시지(Message)","desc":"객체에게 동작을 요청하는 명령"},{"term":"메서드(Method)","desc":"메시지를 받았을 때 실행되는 객체의 함수"},{"term":"클래스(Class)","desc":"객체를 만들기 위한 틀"},{"term":"객체(Object)","desc":"클래스로부터 만들어진 실체"}],"memo":"메시지는 부탁하는 말, 메서드는 그 부탁을 처리하는 방법이다."}},{"id":"written-2022-3-11","no":11,"unit":"소프트웨어 설계","q":"UML 확장 모델에서 스테레오 타입 객체를 나타낼 때 쓰는 기호로 옳은 것은?","choices":["&lt;&lt; &gt;&gt;","(( ))","[[ ]]","{{ }}"],"ans":1,"exp":{"concept":"스테레오타입(Stereotype)은 UML의 기본 요소에 새로운 의미를 덧붙여 확장할 때 쓰는 표기다. 겹화살괄호(길러멧) << >> 안에 이름을 적는다. 예를 들어 <<interface>>, <<include>>, <<extend>>가 있다.","choices":[{"verdict":"정답","why":"스테레오타입은 << >> 기호 안에 이름을 적어 표현한다."},{"verdict":"오답","why":"(( ))는 UML 스테레오타입 표기가 아니다."},{"verdict":"오답","why":"[[ ]]는 UML 스테레오타입 표기가 아니다."},{"verdict":"오답","why":"{{ }}는 UML 스테레오타입 표기가 아니다. 참고로 UML에서 중괄호 { } 한 쌍은 제약 조건 표기에 쓴다."}],"keywords":[{"term":"스테레오타입(Stereotype)","desc":"UML 요소에 의미를 추가하는 확장 표기, << >>"},{"term":"길러멧(Guillemet)","desc":"<< >> 모양의 겹화살괄호"},{"term":"<<include>>","desc":"유스케이스가 다른 유스케이스를 반드시 포함"},{"term":"<<extend>>","desc":"특정 조건에서만 다른 유스케이스로 확장"}],"memo":"<<include>>, <<extend>>처럼 유스케이스에서 이미 본 꺾쇠 두 개가 바로 스테레오타입이다."}},{"id":"written-2022-3-12","no":12,"unit":"소프트웨어 설계","q":"분산 컴퓨팅 환경에서 기종이 서로 다른 하드웨어나 프로토콜, 통신환경 등을 연결해 응용 프로그램과 운영환경 사이에 원활한 통신이 이루어지도록 서비스를 제공하는 소프트웨어는?","choices":["그레이웨어","오픈허브웨어","하드웨어","미들웨어"],"ans":4,"exp":{"concept":"미들웨어(Middleware)는 서로 다른 하드웨어, 프로토콜, 운영체제 사이에서 중간 다리 역할을 하는 소프트웨어다. 분산 환경에서 응용 프로그램과 운영 환경이 원활히 통신하도록 도와준다. 통역사처럼 말이 다른 두 쪽을 이어 준다고 생각하면 된다.","choices":[{"verdict":"오답","why":"그레이웨어(Grayware)는 악성코드는 아니지만 사용자에게 불편이나 위험을 줄 수 있는 애매한 프로그램(광고 프로그램 등)이다."},{"verdict":"오답","why":"오픈허브웨어는 출제 범위의 표준 용어가 아니다."},{"verdict":"오답","why":"하드웨어(Hardware)는 컴퓨터를 이루는 물리적 장치로, 통신을 중재하는 소프트웨어가 아니다."},{"verdict":"정답","why":"미들웨어는 이기종 환경 사이에서 응용 프로그램과 운영 환경 간 통신을 중재하는 소프트웨어다."}],"keywords":[{"term":"미들웨어(Middleware)","desc":"이기종 시스템 사이에서 통신을 중재하는 소프트웨어"},{"term":"WAS(Web Application Server)","desc":"동적 웹 콘텐츠를 처리하는 미들웨어"},{"term":"MOM(Message Oriented Middleware)","desc":"메시지 기반으로 비동기 통신하는 미들웨어"},{"term":"TP-Monitor","desc":"트랜잭션 처리를 감시·제어하는 미들웨어"}],"memo":"Middle(가운데) + ware(소프트웨어) = 가운데서 이어 주는 소프트웨어."}},{"id":"written-2022-3-13","no":13,"unit":"소프트웨어 설계","q":"익스트림 프로그래밍(eXtreme Programming)의 5가지 가치에 해당하지 않는 것은?","choices":["의사소통","단순성","고객 배제","피드백"],"ans":3,"exp":{"concept":"익스트림 프로그래밍(XP, eXtreme Programming)은 고객의 요구 변화에 빠르게 대응하는 애자일 방법론이다. 다섯 가지 핵심 가치는 의사소통(Communication), 단순성(Simplicity), 피드백(Feedback), 용기(Courage), 존중(Respect)이다. XP는 고객을 개발에 적극 참여시킨다.","choices":[{"verdict":"오답","why":"의사소통은 XP의 5가지 가치에 포함된다."},{"verdict":"오답","why":"단순성은 XP의 5가지 가치에 포함된다."},{"verdict":"정답","why":"XP는 고객을 개발 과정에 참여시키는 방법론이므로 고객 배제는 가치가 아니다."},{"verdict":"오답","why":"피드백은 XP의 5가지 가치에 포함된다."}],"keywords":[{"term":"XP(eXtreme Programming)","desc":"짧은 반복과 고객 참여를 중시하는 애자일 방법론"},{"term":"XP 5가지 가치","desc":"의사소통, 단순성, 피드백, 용기, 존중"},{"term":"짝 프로그래밍(Pair Programming)","desc":"두 사람이 한 컴퓨터로 함께 코딩하는 XP 실천법"},{"term":"테스트 주도 개발(TDD)","desc":"테스트를 먼저 작성하고 코드를 작성하는 XP 실천법"}],"memo":"애자일은 고객과 함께한다. '고객 배제'처럼 애자일 정신과 반대되는 말은 바로 정답 후보다."}},{"id":"written-2022-3-14","no":14,"unit":"소프트웨어 설계","q":"다음 중 결합도의 종류에 대한 설명으로 틀린 것은?","choices":["스탬프 결합도 : 모듈 간 인터페이스로 배열의 자료 구조가 전달될 때의 결합도","내용 결합도 : 한 모듈이 다른 모듈과 제어 신호를 이용해 통신하며, 공유되는 공통 데이터 영역을 사용할 때의 결합도","외부 결합도 : 어떤 모듈에서 선언한 데이터를 다른 모듈이 참조할 때의 결합도","자료 결합도 : 모듈 간 인터페이스가 자료 요소로만 이루어질 때의 결합도"],"ans":2,"exp":{"concept":"결합도(Coupling)는 모듈끼리 얼마나 서로 의존하는지를 나타내며 낮을수록 좋다. 강한 순서는 내용 > 공통 > 외부 > 제어 > 스탬프 > 자료 결합도다. 내용 결합도는 한 모듈이 다른 모듈의 내부 기능이나 자료를 직접 참조하거나 수정하는 가장 강한 결합이다.","choices":[{"verdict":"오답","why":"스탬프 결합도는 모듈 사이에 배열이나 레코드 같은 자료 구조가 전달될 때의 결합도이므로 옳은 설명이다."},{"verdict":"정답","why":"제어 신호로 통신하는 것은 제어 결합도, 공통 데이터 영역을 쓰는 것은 공통 결합도의 설명이다. 내용 결합도는 다른 모듈의 내부를 직접 참조하거나 수정하는 경우다."},{"verdict":"오답","why":"외부 결합도는 어떤 모듈에서 선언한 데이터를 외부의 다른 모듈이 참조할 때의 결합도이므로 옳은 설명이다."},{"verdict":"오답","why":"자료 결합도는 모듈 간 인터페이스가 자료 요소로만 이루어질 때의 결합도로 가장 바람직하므로 옳은 설명이다."}],"keywords":[{"term":"내용 결합도(Content Coupling)","desc":"다른 모듈의 내부를 직접 참조·수정, 가장 강함"},{"term":"공통 결합도(Common Coupling)","desc":"전역 변수 같은 공통 데이터 영역을 공유"},{"term":"제어 결합도(Control Coupling)","desc":"제어 신호(플래그)를 넘겨 다른 모듈의 흐름을 조절"},{"term":"스탬프 결합도(Stamp Coupling)","desc":"배열, 레코드 같은 자료 구조를 전달"},{"term":"자료 결합도(Data Coupling)","desc":"필요한 자료 요소만 전달, 가장 약함"}],"memo":"강한 순서 '내공외제스자'(내용-공통-외부-제어-스탬프-자료)로 외운다."}},{"id":"written-2022-3-15","no":15,"unit":"소프트웨어 설계","q":"보헴이 제안한 모형으로, 위험 분석 기능을 갖추고 있으며 여러 차례의 개발 과정을 거치면서 점진적으로 개발해 나가는 모형은?","choices":["애자일 모형","폭포수 모형","나선형 모형","프로토타입 모형"],"ans":3,"exp":{"concept":"나선형 모형(Spiral Model)은 보헴(Boehm)이 제안한 모형으로, 계획 수립, 위험 분석, 개발, 고객 평가의 네 단계를 나선처럼 여러 번 반복하며 점진적으로 완성한다. 매 반복마다 위험 분석을 하므로 위험을 줄이는 데 강하다.","choices":[{"verdict":"오답","why":"애자일 모형은 짧은 반복과 고객과의 소통을 중시하는 방법론의 총칭으로, 보헴이 제안한 위험 분석 중심 모형이 아니다."},{"verdict":"오답","why":"폭포수 모형은 각 단계를 순서대로 한 번씩 진행하는 선형 순차 모형으로, 반복과 위험 분석이 특징이 아니다."},{"verdict":"정답","why":"나선형 모형은 보헴이 제안했으며 위험 분석을 포함한 과정을 반복하며 점진적으로 개발한다."},{"verdict":"오답","why":"프로토타입 모형은 시제품을 먼저 만들어 사용자 요구를 확인하는 모형이다."}],"keywords":[{"term":"나선형 모형(Spiral Model)","desc":"보헴 제안, 위험 분석을 반복하는 점진적 모형"},{"term":"나선형 4단계","desc":"계획 수립, 위험 분석, 개발 및 검증, 고객 평가"},{"term":"폭포수 모형(Waterfall)","desc":"단계를 순서대로 진행하는 고전적 모형"},{"term":"프로토타입 모형(Prototype)","desc":"시제품으로 요구사항을 확인"}],"memo":"보헴 + 위험 분석 = 나선형. 보헴은 COCOMO도 제안했다."}},{"id":"written-2022-3-16","no":16,"unit":"소프트웨어 설계","q":"다음 설명에 해당하는 디자인 패턴은 무엇인가?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>하나의 인스턴스를 생성하고 그 인스턴스를 어디서든 참조할 수 있는 접근점을 제공한다.</li><li>클래스 내에서 인스턴스가 하나뿐임을 보장하여, 불필요한 메모리 낭비를 최소화할 수 있다.</li></ul></div>","choices":["Decorator","Prototype","Adapter","Singleton"],"ans":4,"exp":{"concept":"싱글톤(Singleton) 패턴은 어떤 클래스의 인스턴스가 오직 하나만 만들어지도록 보장하고, 그 하나를 어디서든 꺼내 쓸 수 있게 하는 생성 패턴이다. 학교에 교장 선생님이 한 명뿐인 것처럼, 여러 곳에서 요청해도 같은 객체를 돌려준다.","choices":[{"verdict":"오답","why":"데코레이터(Decorator)는 객체에 기능을 동적으로 덧붙이는 구조 패턴이다."},{"verdict":"오답","why":"프로토타입(Prototype)은 원본 객체를 복제해 새 객체를 만드는 생성 패턴이다."},{"verdict":"오답","why":"어댑터(Adapter)는 호환되지 않는 인터페이스를 맞춰 함께 쓸 수 있게 하는 구조 패턴이다."},{"verdict":"정답","why":"싱글톤(Singleton)은 인스턴스가 하나뿐임을 보장하고 전역 접근점을 제공하는 생성 패턴이다."}],"keywords":[{"term":"싱글톤(Singleton)","desc":"인스턴스를 하나만 생성하는 생성 패턴"},{"term":"생성 패턴","desc":"객체 생성 방식에 관한 패턴: 추상 팩토리, 빌더, 팩토리 메서드, 프로토타입, 싱글톤"},{"term":"데코레이터(Decorator)","desc":"객체에 기능을 동적으로 추가"},{"term":"어댑터(Adapter)","desc":"인터페이스를 변환해 연결"}],"memo":"Single(하나)이라는 이름 그대로 인스턴스가 하나뿐이다."}},{"id":"written-2022-3-17","no":17,"unit":"소프트웨어 설계","q":"UI 설계 원칙 가운데 누구나 쉽게 이해하여 사용할 수 있어야 한다는 원칙은 무엇인가?","choices":["멀티운용성","희소성","유연성","직관성"],"ans":4,"exp":{"concept":"UI 설계 원칙은 직관성, 유효성, 학습성, 유연성 네 가지다. 직관성은 누구나 쉽게 이해하고 쓸 수 있어야 한다는 원칙이고, 유효성은 사용자의 목적을 정확히 달성해야 한다는 원칙, 학습성은 쉽게 배우고 익힐 수 있어야 한다는 원칙, 유연성은 사용자의 요구를 최대한 수용하고 실수를 줄여야 한다는 원칙이다.","choices":[{"verdict":"오답","why":"멀티운용성은 UI 설계 원칙에 해당하지 않는다."},{"verdict":"오답","why":"희소성은 UI 설계 원칙에 해당하지 않는다."},{"verdict":"오답","why":"유연성은 사용자의 요구를 최대한 수용하고 실수를 최소화해야 한다는 원칙이다."},{"verdict":"정답","why":"직관성은 누구나 쉽게 이해하고 사용할 수 있어야 한다는 원칙이다."}],"keywords":[{"term":"직관성","desc":"누구나 쉽게 이해하고 사용"},{"term":"유효성","desc":"사용자의 목적을 정확하고 완벽하게 달성"},{"term":"학습성","desc":"누구나 쉽게 배우고 익힘"},{"term":"유연성","desc":"요구를 최대한 수용하고 오류를 최소화"}],"memo":"UI 4원칙 '직유학유'(직관성-유효성-학습성-유연성)."}},{"id":"written-2022-3-18","no":18,"unit":"소프트웨어 설계","q":"UML의 시퀀스 다이어그램을 이루는 구성 항목이 아닌 것은?","choices":["실행","메시지","생명선","확장"],"ans":4,"exp":{"concept":"시퀀스 다이어그램은 객체들이 시간 순서에 따라 메시지를 주고받는 모습을 나타내는 UML 동적 다이어그램이다. 구성 항목은 액터, 객체, 생명선, 실행(활성화 상자), 메시지, 제어 블록(상호작용 프레임)이다.","choices":[{"verdict":"오답","why":"실행(Activation)은 객체가 메시지를 받아 작업을 수행하는 기간을 생명선 위의 직사각형으로 나타내는 구성 항목이다."},{"verdict":"오답","why":"메시지는 객체 사이에 주고받는 요청과 응답으로 화살표로 나타내는 구성 항목이다."},{"verdict":"오답","why":"생명선(Lifeline)은 객체가 존재하는 기간을 세로 점선으로 나타내는 구성 항목이다."},{"verdict":"정답","why":"확장은 시퀀스 다이어그램의 구성 항목이 아니다. 확장(extend)은 유스케이스 다이어그램의 관계다."}],"keywords":[{"term":"시퀀스 다이어그램","desc":"시간 순서에 따른 객체 간 메시지 흐름을 표현"},{"term":"생명선(Lifeline)","desc":"객체가 존재하는 기간, 세로 점선"},{"term":"실행 사양(Activation)","desc":"객체가 동작 중인 구간, 생명선 위 직사각형"},{"term":"확장(extend)","desc":"유스케이스 다이어그램의 관계"}],"memo":"시퀀스 다이어그램은 '액객생실메제'(액터-객체-생명선-실행-메시지-제어 블록)."}},{"id":"written-2022-3-19","no":19,"unit":"소프트웨어 설계","q":"HIPO(Hierarchy Input Process Output)에 관한 설명 중 거리가 먼 것은?","choices":["보기 쉽고 이해하기가 쉽다.","HIPO 차트의 종류로는 가시적 도표, 총체적 도표, 세부적 도표가 있다.","상향식 소프트웨어 개발을 위해 사용하는 문서화 도구이다.","기능과 자료의 의존 관계를 함께 표현할 수 있다."],"ans":3,"exp":{"concept":"HIPO(Hierarchy Input Process Output)는 시스템의 기능을 입력, 처리, 출력 관점에서 계층적으로 표현하는 문서화 도구다. 위에서 아래로 기능을 쪼개 나가는 하향식(Top-Down) 개발에 사용한다. 도표 종류에는 가시적 도표, 총체적 도표, 세부적 도표가 있다.","choices":[{"verdict":"오답","why":"HIPO는 계층 구조로 정리되어 보기 쉽고 이해하기 쉽다는 장점이 있으므로 옳은 설명이다."},{"verdict":"오답","why":"HIPO 차트는 가시적 도표(전체 기능 구조), 총체적 도표(입력·처리·출력 개요), 세부적 도표(상세 기술)로 구성되므로 옳은 설명이다."},{"verdict":"정답","why":"HIPO는 상위 기능에서 하위 기능으로 분해해 가는 하향식 소프트웨어 개발을 위한 문서화 도구다."},{"verdict":"오답","why":"입력, 처리, 출력을 함께 표현하므로 기능과 자료의 의존 관계를 동시에 나타낼 수 있어 옳은 설명이다."}],"keywords":[{"term":"HIPO(Hierarchy Input Process Output)","desc":"입력·처리·출력을 계층적으로 표현하는 하향식 문서화 도구"},{"term":"가시적 도표(Visual Table of Contents)","desc":"시스템의 전체 기능과 흐름을 보여 주는 계층 도표"},{"term":"총체적 도표(Overview Diagram)","desc":"기능별 입력·처리·출력을 개략적으로 표현"},{"term":"세부적 도표(Detail Diagram)","desc":"총체적 도표의 기능을 상세히 기술"}],"memo":"Hierarchy(계층)는 위에서 아래로 내려가는 구조이므로 HIPO는 하향식이다."}},{"id":"written-2022-3-20","no":20,"unit":"소프트웨어 설계","q":"다음 중 자료 흐름도(Data Flow Diagram)를 구성하는 요소로 옳은 것은?","choices":["process, data store, terminator, mini-spec","process, data flow, data store, comment","data flow, data store, terminator, data dictionary","process, data flow, data store, terminator"],"ans":4,"exp":{"concept":"자료 흐름도(DFD, Data Flow Diagram)는 데이터가 시스템 안에서 어떻게 흐르고 변환되는지를 그림으로 나타낸 것이다. 구성 요소는 프로세스(Process, 원), 자료 흐름(Data Flow, 화살표), 자료 저장소(Data Store, 평행선), 단말(Terminator, 사각형) 네 가지다.","choices":[{"verdict":"오답","why":"미니 명세(mini-spec)는 프로세스의 처리 절차를 서술한 별도 문서로, DFD의 그림 구성 요소가 아니며 자료 흐름(data flow)이 빠져 있다."},{"verdict":"오답","why":"주석(comment)은 DFD 구성 요소가 아니며 단말(terminator)이 빠져 있다."},{"verdict":"오답","why":"자료 사전(data dictionary)은 자료 항목을 정의한 별도 문서로 DFD 구성 요소가 아니며 프로세스(process)가 빠져 있다."},{"verdict":"정답","why":"프로세스, 자료 흐름, 자료 저장소, 단말이 DFD의 네 구성 요소다."}],"keywords":[{"term":"프로세스(Process)","desc":"자료를 변환하는 처리, 원으로 표시"},{"term":"자료 흐름(Data Flow)","desc":"자료의 이동, 화살표로 표시"},{"term":"자료 저장소(Data Store)","desc":"자료가 저장된 곳, 평행선으로 표시"},{"term":"단말(Terminator)","desc":"시스템 밖의 외부 개체, 사각형으로 표시"}],"memo":"DFD는 '처리-흐름-저장소-단말' 네 가지만 그린다. 자료 사전과 소단위 명세는 DFD를 보충하는 별도 문서다."}},{"id":"written-2022-3-21","no":21,"unit":"소프트웨어 개발","q":"디지털 저작권 관리(DRM)의 기술 요소에 해당하지 않는 것은?","choices":["크랙 방지 기술","정책 관리 기술","방화벽 기술","암호화 기술"],"ans":3,"exp":{"concept":"디지털 저작권 관리(DRM, Digital Rights Management)는 디지털 콘텐츠가 허가된 사용자에게만 허가된 방식으로 쓰이도록 보호하는 기술이다. 기술 요소로 암호화, 키 관리, 암호화 파일 생성(패키저), 식별 기술, 저작권 표현, 정책 관리, 크랙 방지, 인증이 있다.","choices":[{"verdict":"오답","why":"크랙 방지 기술은 크랙에 의한 콘텐츠 불법 사용을 막는 DRM 기술 요소다."},{"verdict":"오답","why":"정책 관리 기술은 라이선스 발급, 사용 정책 등을 관리하는 DRM 기술 요소다."},{"verdict":"정답","why":"방화벽 기술은 네트워크의 내부와 외부 사이 트래픽을 통제하는 보안 장치로 DRM 기술 요소가 아니다."},{"verdict":"오답","why":"암호화 기술은 콘텐츠와 라이선스를 암호화하고 전자 서명을 적용하는 DRM의 핵심 기술 요소다."}],"keywords":[{"term":"DRM(Digital Rights Management)","desc":"디지털 콘텐츠의 저작권을 보호하는 기술"},{"term":"패키저(Packager)","desc":"콘텐츠를 메타데이터와 함께 암호화해 배포 단위로 묶는 도구"},{"term":"클리어링 하우스(Clearing House)","desc":"라이선스 발급과 사용 권한을 관리하는 곳"},{"term":"DRM 컨트롤러","desc":"배포된 콘텐츠의 이용 권한을 통제"}],"memo":"DRM 기술 요소는 콘텐츠 자체를 지키는 기술이다. 방화벽처럼 네트워크를 지키는 장비는 섞여 나오는 오답이다."}},{"id":"written-2022-3-22","no":22,"unit":"소프트웨어 개발","q":"소프트웨어 테스트에서 오류의 80%는 전체 모듈의 20% 내에서 발견된다는 법칙은 무엇인가?","choices":["Pareto의 법칙","Jackson의 법칙","Brooks의 법칙","Boehm의 법칙"],"ans":1,"exp":{"concept":"파레토 법칙(Pareto Principle)은 전체 결과의 80%가 원인의 20%에서 나온다는 법칙이다. 소프트웨어 테스트에서는 오류의 80%가 전체 모듈의 20%에 몰려 있다는 원리로 적용되어, 결함이 많은 모듈에 테스트를 집중하라는 뜻이 된다.","choices":[{"verdict":"정답","why":"파레토 법칙은 오류의 80%가 전체 모듈의 20% 안에서 발견된다는 결함 집중 원리다."},{"verdict":"오답","why":"잭슨(Jackson)의 법칙은 오류 분포를 설명하는 테스트 원리가 아니며, 출제 범위의 표준 법칙도 아니다."},{"verdict":"오답","why":"브룩스(Brooks)의 법칙은 일정이 늦어진 프로젝트에 인력을 추가하면 오히려 더 늦어진다는 법칙이다."},{"verdict":"오답","why":"보헴(Boehm)은 나선형 모형과 COCOMO를 제안한 학자로, 80:20 결함 집중을 말하는 법칙이 아니다."}],"keywords":[{"term":"파레토 법칙(Pareto Principle)","desc":"오류의 80%는 20%의 모듈에 집중"},{"term":"결함 집중(Defect Clustering)","desc":"소수 모듈에 결함이 몰리는 테스트 원리"},{"term":"브룩스의 법칙(Brooks' Law)","desc":"지연된 프로젝트에 인력을 더하면 더 늦어진다"},{"term":"살충제 패러독스(Pesticide Paradox)","desc":"같은 테스트를 반복하면 새 결함을 찾지 못한다"}],"memo":"80:20이 나오면 파레토, 인력 추가가 나오면 브룩스."}},{"id":"written-2022-3-23","no":23,"unit":"소프트웨어 개발","q":"소프트웨어 패키징에 관한 설명 중 옳지 않은 것은?","choices":["신규 및 변경 개발소스를 식별한 후, 이를 모듈화하여 상용제품으로 패키징한다.","고객의 편의성을 위하여 매뉴얼 및 버전관리를 지속적으로 수행한다.","범용 환경에서 사용할 수 있도록 일반적인 배포 형태로 패키징을 진행한다.","패키징은 개발자 중심으로 이루어진다."],"ans":4,"exp":{"concept":"소프트웨어 패키징은 개발이 끝난 소프트웨어를 고객이 쉽게 설치하고 쓸 수 있도록 실행 파일, 매뉴얼 등을 묶어 배포 형태로 만드는 작업이다. 따라서 개발자가 아니라 사용자(고객) 중심으로 진행한다.","choices":[{"verdict":"오답","why":"신규·변경 소스를 식별하고 모듈화하여 상용 제품으로 패키징하는 것은 올바른 패키징 활동이다."},{"verdict":"오답","why":"고객 편의를 위해 매뉴얼을 작성하고 버전 관리를 지속하는 것은 올바른 패키징 활동이다."},{"verdict":"오답","why":"다양한 환경에서 쓸 수 있도록 일반적인 배포 형태로 패키징하는 것은 올바른 활동이다."},{"verdict":"정답","why":"패키징은 개발자가 아니라 사용자 중심으로 진행해야 하므로 옳지 않은 설명이다."}],"keywords":[{"term":"소프트웨어 패키징","desc":"소프트웨어를 사용자가 설치·사용할 수 있는 배포 형태로 묶는 작업"},{"term":"릴리즈 노트(Release Notes)","desc":"배포 버전의 변경 사항과 정보를 정리한 문서"},{"term":"형상 관리(SCM)","desc":"소프트웨어 변경을 추적·통제하는 활동"}],"memo":"패키징은 받는 사람(사용자)을 위한 포장이다. '개발자 중심'이 보이면 틀린 문장이다."}},{"id":"written-2022-3-24","no":24,"unit":"소프트웨어 개발","q":"다음 중 해싱 함수(Hashing Function)의 종류에 해당하지 않는 것은?","choices":["개방 주소법(Open Addressing)","제곱법(Mid-Square)","숫자 분석법(Digit Analysis)","제산법(Division)"],"ans":1,"exp":{"concept":"해싱 함수는 키 값을 계산해 데이터가 저장될 주소(버킷 위치)를 정하는 함수다. 종류로 제산법, 제곱법, 폴딩법, 기수 변환법, 대수적 코딩법, 숫자 분석법, 무작위법이 있다. 서로 다른 키가 같은 주소로 가는 충돌이 생겼을 때 해결하는 방법(개방 주소법, 체이닝 등)은 해싱 함수와 구분해야 한다.","choices":[{"verdict":"정답","why":"개방 주소법(Open Addressing)은 충돌이 났을 때 다른 빈 주소를 찾아 저장하는 충돌 해결 기법으로, 해싱 함수의 종류가 아니다."},{"verdict":"오답","why":"제곱법(Mid-Square)은 키를 제곱한 값의 중간 자리를 주소로 쓰는 해싱 함수다."},{"verdict":"오답","why":"숫자 분석법(Digit Analysis)은 키의 각 자리 중 고르게 분포된 자리를 골라 주소로 쓰는 해싱 함수다."},{"verdict":"오답","why":"제산법(Division)은 키를 해시표 크기보다 큰 수 중 가장 작은 소수로 나눈 나머지를 주소로 쓰는 해싱 함수다."}],"keywords":[{"term":"제산법(Division)","desc":"키를 소수로 나눈 나머지를 주소로 사용"},{"term":"제곱법(Mid-Square)","desc":"키를 제곱한 값의 중간 부분을 주소로 사용"},{"term":"폴딩법(Folding)","desc":"키를 여러 부분으로 나눠 더하거나 XOR한 값을 사용"},{"term":"개방 주소법(Open Addressing)","desc":"충돌 시 빈 자리를 찾아 저장하는 충돌 해결 기법"},{"term":"체이닝(Chaining)","desc":"충돌한 데이터를 연결 리스트로 이어 저장"}],"memo":"주소를 '계산하는 법'은 해싱 함수, 충돌 후 '자리를 찾는 법'은 충돌 해결 기법이다."}},{"id":"written-2022-3-25","no":25,"unit":"소프트웨어 개발","q":"다음 중 인터페이스 구현 검증 도구에 해당하지 않는 것은?","choices":["ESB","STAF","xUnit","NTAF"],"ans":1,"exp":{"concept":"인터페이스 구현 검증 도구는 모듈 사이의 인터페이스가 제대로 동작하는지 테스트하는 도구다. 대표적으로 xUnit, STAF, FitNesse, NTAF, Selenium, watir가 있다.","choices":[{"verdict":"정답","why":"ESB(Enterprise Service Bus)는 서비스들을 버스 형태로 연결해 통합하는 인터페이스 구축 방식(미들웨어)으로, 검증 도구가 아니다."},{"verdict":"오답","why":"STAF는 서비스 호출 및 컴포넌트 재사용 등 다양한 환경을 지원하는 테스트 프레임워크로, 인터페이스 검증 도구다."},{"verdict":"오답","why":"xUnit은 JUnit, CppUnit 등 다양한 언어를 지원하는 단위 테스트 프레임워크로, 인터페이스 검증 도구다."},{"verdict":"오답","why":"NTAF는 네이버(NHN)가 개발한 테스트 자동화 프레임워크로 STAF와 FitNesse를 통합한 인터페이스 검증 도구다."}],"keywords":[{"term":"xUnit","desc":"JUnit, CppUnit 등 언어별 단위 테스트 프레임워크"},{"term":"STAF","desc":"분산 환경의 테스트를 지원하는 테스트 프레임워크"},{"term":"FitNesse","desc":"웹 기반 테스트 케이스 설계·실행·결과 확인 도구"},{"term":"NTAF","desc":"STAF와 FitNesse를 통합한 테스트 자동화 프레임워크"},{"term":"ESB(Enterprise Service Bus)","desc":"서비스 중심으로 시스템을 연계하는 통합 구조"}],"memo":"검증 도구는 'x스피엔셀와'(xUnit, STAF, FitNesse, NTAF, Selenium, watir). ESB는 연계(구축) 쪽이다."}},{"id":"written-2022-3-26","no":26,"unit":"소프트웨어 개발","q":"다음 중 스택(STACK)의 응용 분야와 거리가 먼 것은?","choices":["서브루틴 복귀 번지의 저장","인터럽트 처리","수식 계산","운영체제 작업 스케줄링"],"ans":4,"exp":{"concept":"스택(Stack)은 나중에 넣은 것을 먼저 꺼내는 후입선출(LIFO) 구조다. 함수 호출 후 돌아갈 주소 저장, 인터럽트 처리, 수식 계산(후위 표기법), 깊이 우선 탐색(DFS), 되돌리기(Undo) 등에 쓰인다. 먼저 온 작업을 먼저 처리하는 작업 스케줄링에는 선입선출(FIFO)인 큐를 쓴다.","choices":[{"verdict":"오답","why":"서브루틴을 호출할 때 복귀 번지를 스택에 저장했다가 끝나면 꺼내 돌아가므로 스택의 응용이다."},{"verdict":"오답","why":"인터럽트가 발생하면 현재 상태를 스택에 저장하고 처리 후 복원하므로 스택의 응용이다."},{"verdict":"오답","why":"후위 표기식 계산 등 수식 계산에 스택을 사용하므로 스택의 응용이다."},{"verdict":"정답","why":"운영체제의 작업 스케줄링은 들어온 순서대로 처리하는 큐(Queue)를 응용한다."}],"keywords":[{"term":"스택(Stack)","desc":"후입선출(LIFO) 구조, 한쪽 끝에서만 삽입·삭제"},{"term":"큐(Queue)","desc":"선입선출(FIFO) 구조, 작업 스케줄링에 사용"},{"term":"PUSH/POP","desc":"스택에 넣기/꺼내기"},{"term":"후위 표기법(Postfix)","desc":"연산자를 피연산자 뒤에 쓰는 표기, 스택으로 계산"}],"memo":"줄 서기(스케줄링)는 큐, 접시 쌓기(복귀 주소, 수식 계산)는 스택."}},{"id":"written-2022-3-27","no":27,"unit":"소프트웨어 개발","q":"소프트웨어 테스트에 관한 설명 중 틀린 것은?","choices":["테스트 케이스에는 일반적으로 시험 조건, 테스트 데이터, 예상 결과가 포함되어야 한다.","화이트박스 테스트에서 기본 경로(Basis Path)란 흐름 그래프의 시작 노드부터 종료 노드까지의 서로 독립된 경로로서 싸이클을 허용하지 않는 경로를 의미한다.","화이트박스 테스트는 모듈의 논리적인 구조를 체계적으로 점검하는 것이 가능하다.","블랙박스 테스트는 프로그램의 구조를 고려하지 않고 수행한다."],"ans":2,"exp":{"concept":"기본 경로(Basis Path)는 흐름 그래프에서 시작 노드부터 종료 노드까지 가는 서로 독립적인 경로다. 독립적이라는 것은 이전 경로에 없던 새로운 간선을 적어도 하나 포함한다는 뜻이며, 반복문이 있으면 사이클이 포함된 경로도 기본 경로가 될 수 있다. 기본 경로의 수는 맥케이브의 순환 복잡도로 구한다.","choices":[{"verdict":"오답","why":"테스트 케이스에는 테스트 조건, 테스트 데이터, 예상 결과가 포함되어야 하므로 옳은 설명이다."},{"verdict":"정답","why":"기본 경로는 사이클을 허용하지 않는 경로가 아니다. 반복 구조를 지나는 사이클이 포함된 경로도 독립 경로로 셀 수 있다."},{"verdict":"오답","why":"화이트박스 테스트는 소스 코드의 논리 구조를 보며 경로, 조건 등을 체계적으로 점검할 수 있으므로 옳은 설명이다."},{"verdict":"오답","why":"블랙박스 테스트는 내부 구조를 보지 않고 명세(입력과 출력)만으로 테스트하므로 옳은 설명이다."}],"keywords":[{"term":"기본 경로 테스트(Basis Path Testing)","desc":"독립 경로를 모두 한 번 이상 실행하는 화이트박스 테스트"},{"term":"순환 복잡도(Cyclomatic Complexity)","desc":"V(G) = E - N + 2, 독립 경로의 수"},{"term":"화이트박스 테스트","desc":"내부 논리 구조를 보고 하는 테스트"},{"term":"블랙박스 테스트","desc":"명세(기능)만 보고 하는 테스트"}],"memo":"반복문이 있는 프로그램도 기본 경로 테스트를 하므로, 기본 경로가 사이클을 금지한다는 말은 틀렸다."}},{"id":"written-2022-3-28","no":28,"unit":"소프트웨어 개발","q":"알파 테스트 및 베타 테스트와 가장 밀접하게 관련된 테스트 단계는?","choices":["시스템 테스트","통합 테스트","단위 테스트","인수 테스트"],"ans":4,"exp":{"concept":"인수 테스트(Acceptance Test)는 개발된 소프트웨어를 사용자가 직접 써 보며 요구사항을 만족하는지 확인하는 마지막 테스트 단계다. 알파 테스트는 개발자 장소에서 사용자가 개발자와 함께 하는 테스트이고, 베타 테스트는 실제 사용자 환경에서 개발자 없이 하는 테스트로 둘 다 인수 테스트에 속한다.","choices":[{"verdict":"오답","why":"시스템 테스트는 통합된 시스템이 기능·비기능 요구사항을 만족하는지 개발 측에서 확인하는 단계다."},{"verdict":"오답","why":"통합 테스트는 모듈을 결합하면서 모듈 간 인터페이스를 확인하는 단계다."},{"verdict":"오답","why":"단위 테스트는 개별 모듈(함수, 클래스)을 따로 확인하는 단계다."},{"verdict":"정답","why":"알파 테스트와 베타 테스트는 사용자가 수행하는 인수 테스트의 종류다."}],"keywords":[{"term":"인수 테스트(Acceptance Test)","desc":"사용자가 요구 충족 여부를 확인하는 마지막 테스트"},{"term":"알파 테스트(Alpha Test)","desc":"개발자 장소에서 개발자와 함께 하는 테스트"},{"term":"베타 테스트(Beta Test)","desc":"실제 사용자 환경에서 개발자 없이 하는 테스트"},{"term":"V 모델 테스트 순서","desc":"단위 → 통합 → 시스템 → 인수"}],"memo":"알파는 개발자 앞에서, 베타는 사용자 집에서. 둘 다 사용자가 받아들이는(인수) 테스트다."}},{"id":"written-2022-3-29","no":29,"unit":"소프트웨어 개발","q":"다음 중 테스트 오라클에 관한 설명으로 옳지 않은 것은?","choices":["샘플링 오라클 : 특정한 몇몇 테스트 케이스의 입력 값에 대해서만 기대하는 결과를 제공하는 오라클이다.","휴리스틱 오라클 : 특정 테스트 케이스의 입력 값에 대해서는 기대하는 결과를 제공하고, 나머지 입력 값들은 추정으로 처리하는 오라클이다.","토탈 오라클 : 모든 테스트 케이스의 입력 값에 대하여 기대하는 결과를 제공하는 오라클이다.","일관성 검사 오라클 : 애플리케이션에 변경이 있을 경우 테스트 케이스 수행 전과 후의 결과 값이 동일한지 확인하는 오라클이다."],"ans":3,"exp":{"concept":"테스트 오라클(Test Oracle)은 테스트 결과가 맞는지 판단하기 위해 기준이 되는 기대 결과를 제공하는 장치다. 종류는 참 오라클, 샘플링 오라클, 휴리스틱(추정) 오라클, 일관성 검사 오라클 네 가지다. 모든 입력에 대해 기대 결과를 제공하는 것은 참(True) 오라클이다.","choices":[{"verdict":"오답","why":"샘플링 오라클은 특정한 몇몇 입력 값에 대해서만 기대 결과를 제공하므로 옳은 설명이다."},{"verdict":"오답","why":"휴리스틱 오라클은 특정 입력 값에는 기대 결과를 제공하고 나머지는 추정으로 처리하므로 옳은 설명이다."},{"verdict":"정답","why":"모든 입력 값에 대해 기대 결과를 제공하는 오라클의 이름은 참(True) 오라클이며, 토탈 오라클은 오라클 종류에 없는 이름이다."},{"verdict":"오답","why":"일관성 검사 오라클은 애플리케이션 변경 전후의 결과가 같은지 확인하므로 옳은 설명이다."}],"keywords":[{"term":"테스트 오라클(Test Oracle)","desc":"테스트 결과의 참·거짓을 판단하는 기준"},{"term":"참 오라클(True Oracle)","desc":"모든 입력에 대해 기대 결과 제공, 모든 오류 검출 가능"},{"term":"샘플링 오라클(Sampling Oracle)","desc":"일부 입력에 대해서만 기대 결과 제공"},{"term":"휴리스틱 오라클(Heuristic Oracle)","desc":"일부는 기대 결과, 나머지는 추정"},{"term":"일관성 검사 오라클(Consistent Oracle)","desc":"변경 전후 결과가 같은지 확인"}],"memo":"오라클 4종 '참샘휴일'(참-샘플링-휴리스틱-일관성). '토탈'은 없다."}},{"id":"written-2022-3-30","no":30,"unit":"소프트웨어 개발","q":"다음 중 EAI(Enterprise Application Integration)의 구축 유형에 해당하지 않는 것은?","choices":["Point-to-Point","Hub &amp; Spoke","Message Bus","Tree"],"ans":4,"exp":{"concept":"EAI(Enterprise Application Integration)는 기업 안의 여러 애플리케이션을 연계해 정보를 주고받게 하는 통합 솔루션이다. 구축 유형은 Point-to-Point, Hub & Spoke, Message Bus, Hybrid 네 가지다.","choices":[{"verdict":"오답","why":"Point-to-Point는 애플리케이션끼리 1:1로 직접 연결하는 EAI 구축 유형이다."},{"verdict":"오답","why":"Hub & Spoke는 가운데 허브를 두고 모든 애플리케이션이 허브를 거쳐 통신하는 EAI 구축 유형이다."},{"verdict":"오답","why":"Message Bus는 애플리케이션 사이에 미들웨어(버스)를 두어 처리하는 EAI 구축 유형이다."},{"verdict":"정답","why":"Tree는 EAI 구축 유형에 해당하지 않는다."}],"keywords":[{"term":"EAI(Enterprise Application Integration)","desc":"기업 내 애플리케이션을 연계·통합하는 솔루션"},{"term":"Point-to-Point","desc":"1:1 직접 연결, 변경과 재사용이 어려움"},{"term":"Hub & Spoke","desc":"허브를 통한 중앙 집중 방식, 허브 장애 시 전체 영향"},{"term":"Message Bus(ESB 방식)","desc":"미들웨어 버스를 두는 방식, 확장성이 좋음"},{"term":"Hybrid","desc":"그룹 내는 Hub & Spoke, 그룹 간은 Message Bus"}],"memo":"EAI 유형 '포허메하'(Point-to-Point, Hub & Spoke, Message Bus, Hybrid)."}},{"id":"written-2022-3-31","no":31,"unit":"소프트웨어 개발","q":"아래 트리를 후위 순회(Post Traversal)하면 그 결과는?<img class=\"q-img\" src=\"data/img/afe6fc7c39cb327d91bc2909dc836ba0.png\" width=\"494\" alt=\"문항 원본 자료\">","choices":["D B E F C A","A B D C E F","A B C D E F","D B A E C F"],"ans":1,"exp":{"concept":"후위 순회(Postorder)는 왼쪽 서브트리, 오른쪽 서브트리를 먼저 방문하고 마지막에 루트를 방문한다(Left → Right → Root). 그림의 트리는 A의 왼쪽 자식이 B, 오른쪽 자식이 C이고, B의 왼쪽 자식이 D, C의 자식이 E(왼쪽), F(오른쪽)다.","choices":[{"verdict":"정답","why":"B 서브트리에서 D, B를 방문하고 C 서브트리에서 E, F, C를 방문한 뒤 루트 A를 방문하므로 D B E F C A다."},{"verdict":"오답","why":"A B D C E F는 루트를 먼저 방문하는 전위 순회(Root → Left → Right) 결과다."},{"verdict":"오답","why":"A B C D E F는 위에서 아래로 층별로 방문한 레벨 순서 결과다."},{"verdict":"오답","why":"D B A E C F는 왼쪽 → 루트 → 오른쪽 순서인 중위 순회 결과다."}],"keywords":[{"term":"전위 순회(Preorder)","desc":"Root → Left → Right"},{"term":"중위 순회(Inorder)","desc":"Left → Root → Right"},{"term":"후위 순회(Postorder)","desc":"Left → Right → Root"},{"term":"서브트리(Subtree)","desc":"어떤 노드와 그 자손들로 이루어진 작은 트리"}],"memo":"전·중·후는 루트를 언제 방문하느냐(앞·가운데·뒤)다. 후위 순회 결과의 맨 끝은 항상 루트다."}},{"id":"written-2022-3-32","no":32,"unit":"소프트웨어 개발","q":"소프트웨어 형상관리(Configuration management)에 대한 설명으로 틀린 것은?","choices":["형상관리를 위해 구성된 팀을 “chief programmer team”이라고 부른다.","형상관리의 기능 중 하나로 버전 제어 기술이 있다.","소프트웨어 개발의 전체 비용을 줄이고, 개발 과정의 여러 방해 요인을 최소화하도록 보증하는 것을 목적으로 한다.","소프트웨어에서 발생하는 수정이나 변경을 알아내어 제어하는 것을 의미한다."],"ans":1,"exp":{"concept":"형상 관리(SCM, Software Configuration Management)는 소프트웨어 개발 과정에서 생기는 변경 사항을 식별하고 관리하고 추적하는 활동이다. 주요 기능은 형상 식별, 버전 제어, 형상 통제, 형상 감사, 형상 기록이며, 변경 요청의 승인 여부는 형상 통제 위원회(CCB)가 결정한다.","choices":[{"verdict":"정답","why":"책임 프로그래머 팀(Chief Programmer Team)은 한 명의 책임 프로그래머가 중심이 되는 개발 팀 구성 방식으로, 형상 관리 팀의 이름이 아니다."},{"verdict":"오답","why":"버전 제어는 형상 관리의 핵심 기능이므로 옳은 설명이다."},{"verdict":"오답","why":"형상 관리는 변경을 체계적으로 통제해 개발 비용을 줄이고 방해 요인을 최소화하는 것을 목적으로 하므로 옳은 설명이다."},{"verdict":"오답","why":"형상 관리는 소프트웨어의 수정과 변경을 알아내고 제어하는 활동이므로 옳은 설명이다."}],"keywords":[{"term":"형상 관리(SCM)","desc":"소프트웨어 변경을 식별·통제·추적하는 활동"},{"term":"형상 통제 위원회(CCB, Configuration Control Board)","desc":"변경 요청의 승인 여부를 결정하는 조직"},{"term":"형상 관리 절차","desc":"식별 → 통제 → 감사 → 기록"},{"term":"책임 프로그래머 팀(Chief Programmer Team)","desc":"책임 프로그래머 중심의 계층적 팀 구성"}],"memo":"형상 관리 조직은 CCB, 책임 프로그래머 팀은 개발 팀 구성 방식이다."}},{"id":"written-2022-3-33","no":33,"unit":"소프트웨어 개발","q":"소스 코드 품질 분석 도구 가운데 정적 분석 도구에 해당하지 않는 것은?","choices":["Valgrind","pmd","checkstyle","cppcheck"],"ans":1,"exp":{"concept":"정적 분석은 프로그램을 실행하지 않고 소스 코드만 보고 결함, 코딩 규칙 위반 등을 찾는 것이고, 동적 분석은 프로그램을 실행하면서 메모리 누수나 스레드 결함 등을 찾는 것이다. pmd, checkstyle, cppcheck, SonarQube는 정적 분석 도구, Valgrind와 Avalanche는 동적 분석 도구다.","choices":[{"verdict":"정답","why":"Valgrind는 프로그램을 실행하며 메모리 누수와 스레드 결함 등을 찾는 동적 분석 도구다."},{"verdict":"오답","why":"pmd는 자바 등의 소스 코드에서 미사용 변수, 중복 코드 등을 찾는 정적 분석 도구다."},{"verdict":"오답","why":"checkstyle은 자바 코드가 코딩 표준을 지키는지 검사하는 정적 분석 도구다."},{"verdict":"오답","why":"cppcheck는 C/C++ 코드의 메모리 누수, 오버플로 등을 분석하는 정적 분석 도구다."}],"keywords":[{"term":"정적 분석(Static Analysis)","desc":"실행하지 않고 소스 코드를 분석"},{"term":"동적 분석(Dynamic Analysis)","desc":"실행하면서 결함을 분석"},{"term":"Valgrind","desc":"메모리 누수 등을 찾는 동적 분석 도구"},{"term":"pmd / checkstyle / cppcheck","desc":"대표적인 정적 분석 도구"}],"memo":"Valgrind와 Avalanche는 실행해 봐야 아는 동적 분석 도구로 따로 외워 두면 나머지는 정적이다."}},{"id":"written-2022-3-34","no":34,"unit":"소프트웨어 개발","q":"입력 순서가 A, B, C, D로 정해진 자료를 스택에 넣었다가 꺼낼 때, 가능한 출력 순서의 결과가 아닌 것은?","choices":["B, C, D, A","A, B, D, C","A, B, C, D","D, A, B, C"],"ans":4,"exp":{"concept":"스택은 나중에 들어간 것이 먼저 나오는(LIFO) 구조다. 입력 순서가 정해져 있어도 중간중간 꺼낼 수 있으므로 여러 출력 순서가 가능하다. 다만 어떤 원소가 나온 뒤에는 그보다 먼저 들어가 아직 스택에 남아 있는 원소들은 들어간 순서의 역순으로만 나올 수 있다.","choices":[{"verdict":"오답","why":"A, B를 넣고 B를 꺼낸 뒤 C 넣고 꺼내기, D 넣고 꺼내기, 마지막에 A를 꺼내면 B, C, D, A가 가능하다."},{"verdict":"오답","why":"A 넣고 꺼내기, B 넣고 꺼내기, C, D를 넣고 D, C 순으로 꺼내면 A, B, D, C가 가능하다."},{"verdict":"오답","why":"하나 넣고 바로 꺼내기를 네 번 반복하면 A, B, C, D가 가능하다."},{"verdict":"정답","why":"D가 먼저 나오려면 A, B, C가 모두 스택에 쌓여 있어야 하고, 그다음에는 C가 맨 위이므로 A가 나올 수 없다. 따라서 D, A, B, C는 불가능하다."}],"keywords":[{"term":"스택(Stack)","desc":"후입선출(LIFO) 구조"},{"term":"PUSH","desc":"스택의 맨 위(Top)에 자료를 넣는 연산"},{"term":"POP","desc":"스택의 맨 위(Top)에서 자료를 꺼내는 연산"},{"term":"Top","desc":"스택에서 가장 최근에 들어간 자료의 위치"}],"memo":"마지막 원소(D)가 먼저 나오면 나머지는 반드시 역순(C, B, A)으로만 나온다."}},{"id":"written-2022-3-35","no":35,"unit":"소프트웨어 개발","q":"연결 리스트(Linked List)에 관한 설명 중 거리가 먼 것은?","choices":["연결을 위한 포인터(Pointer)용 추가 공간이 필요하다.","노드를 삽입하거나 삭제하기가 쉽다.","연결 리스트에서 중간 노드의 연결이 끊어지면 그 다음 노드를 찾기 어렵다.","노드들이 포인터로 연결되어 있어 검색이 빠르다."],"ans":4,"exp":{"concept":"연결 리스트(Linked List)는 각 노드가 데이터와 다음 노드를 가리키는 포인터를 함께 가진 자료 구조다. 포인터만 바꾸면 되므로 삽입과 삭제는 쉽지만, 원하는 노드를 찾으려면 처음부터 포인터를 따라 차례로 가야 하므로 검색은 느리다.","choices":[{"verdict":"오답","why":"각 노드가 다음 노드를 가리키는 포인터를 저장해야 하므로 추가 공간이 필요하다는 것은 옳은 설명이다."},{"verdict":"오답","why":"포인터만 바꾸면 노드를 끼우거나 뺄 수 있으므로 삽입·삭제가 쉽다는 것은 옳은 설명이다."},{"verdict":"오답","why":"다음 노드의 위치는 포인터로만 알 수 있으므로 중간 연결이 끊기면 그 다음 노드를 찾기 어렵다는 것은 옳은 설명이다."},{"verdict":"정답","why":"연결 리스트는 처음부터 순차적으로 따라가야 하므로 검색이 느리다. 인덱스로 바로 접근하는 배열보다 접근 속도가 느리다."}],"keywords":[{"term":"연결 리스트(Linked List)","desc":"노드를 포인터로 연결한 자료 구조"},{"term":"노드(Node)","desc":"데이터와 링크(포인터)로 이루어진 단위"},{"term":"배열(Array)","desc":"연속된 공간에 저장, 인덱스로 빠르게 접근하지만 삽입·삭제가 불편"},{"term":"순차 접근","desc":"처음부터 차례로 따라가는 접근 방식"}],"memo":"연결 리스트는 '삽입·삭제 빠름, 검색 느림', 배열은 그 반대."}},{"id":"written-2022-3-36","no":36,"unit":"소프트웨어 개발","q":"아래 자료를 선택(Selection) 정렬을 이용해 오름차순으로 정렬하려고 한다. 1회전을 수행한 결과는?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>8, 3, 4, 9, 7</p></div>","choices":["3, 4, 7, 8, 9","3, 4, 7, 9, 8","3, 4, 8, 9, 7","3, 8, 4, 9, 7"],"ans":4,"exp":{"concept":"선택 정렬(Selection Sort)은 남은 자료 중 가장 작은 값을 골라(선택) 맨 앞자리와 교환하는 과정을 반복한다. 1회전에서는 전체에서 가장 작은 값을 찾아 첫 번째 자리와 바꾼다.","choices":[{"verdict":"오답","why":"3, 4, 7, 8, 9는 정렬이 모두 끝난 최종 결과다."},{"verdict":"오답","why":"3, 4, 7, 9, 8은 3회전까지 수행한 결과다."},{"verdict":"오답","why":"3, 4, 8, 9, 7은 2회전까지 수행한 결과다."},{"verdict":"정답","why":"8, 3, 4, 9, 7에서 최솟값 3을 찾아 첫 자리 8과 교환하면 3, 8, 4, 9, 7이 된다."}],"keywords":[{"term":"선택 정렬(Selection Sort)","desc":"최솟값을 골라 앞자리와 교환하는 정렬"},{"term":"버블 정렬(Bubble Sort)","desc":"인접한 두 값을 비교·교환하는 정렬"},{"term":"삽입 정렬(Insertion Sort)","desc":"앞쪽 정렬된 부분에 새 값을 알맞은 자리에 끼우는 정렬"}],"memo":"선택 정렬 1회전은 최솟값과 첫 자리만 바뀐다. 나머지 원소 순서는 그대로다."}},{"id":"written-2022-3-37","no":37,"unit":"소프트웨어 개발","q":"IPSec(IP Security)에 관한 설명 중 틀린 것은?","choices":["AH는 발신지 호스트를 인증하며 IP 패킷의 무결성을 보장한다.","암호화를 수행할 때 일방향 암호화만을 지원한다.","운영 모드는 Tunnel 모드와 Transport 모드로 나뉜다.","ESP는 발신지 인증과 데이터 무결성, 기밀성을 모두 보장한다."],"ans":2,"exp":{"concept":"IPSec(IP Security)은 네트워크 계층(IP)에서 패킷을 암호화하고 인증하는 보안 프로토콜이다. 인증과 무결성을 제공하는 AH와, 여기에 기밀성(암호화)까지 제공하는 ESP를 쓰며, 터널 모드와 전송 모드로 동작한다. 송신 측이 암호화하고 수신 측이 같은 키로 복호화하는 양방향 암호화를 지원한다.","choices":[{"verdict":"오답","why":"AH(Authentication Header)는 발신지 인증과 IP 패킷의 무결성을 보장하므로 옳은 설명이다."},{"verdict":"정답","why":"IPSec은 일방향 암호화만 지원하는 것이 아니라 암호화와 복호화가 모두 가능한 양방향 암호화를 지원한다."},{"verdict":"오답","why":"IPSec의 운영 모드는 IP 헤더까지 보호하는 터널(Tunnel) 모드와 데이터 부분만 보호하는 전송(Transport) 모드로 나뉘므로 옳은 설명이다."},{"verdict":"오답","why":"ESP(Encapsulating Security Payload)는 발신지 인증, 무결성에 더해 암호화로 기밀성까지 보장하므로 옳은 설명이다."}],"keywords":[{"term":"IPSec(IP Security)","desc":"네트워크 계층에서 동작하는 보안 프로토콜"},{"term":"AH(Authentication Header)","desc":"인증과 무결성 제공, 암호화는 하지 않음"},{"term":"ESP(Encapsulating Security Payload)","desc":"인증, 무결성, 기밀성 제공"},{"term":"IKE(Internet Key Exchange)","desc":"IPSec에서 보안 연결과 키를 교환하는 프로토콜"},{"term":"터널 모드 / 전송 모드","desc":"IP 패킷 전체 보호 / 데이터 부분만 보호"}],"memo":"AH는 인증만, ESP는 인증+암호화. 암호화가 필요하면 ESP다."}},{"id":"written-2022-3-38","no":38,"unit":"소프트웨어 개발","q":"알고리즘의 시간 복잡도 O(1)이 뜻하는 것은 무엇인가?","choices":["알고리즘의 입력 데이터 수가 한 개임","컴퓨터로 처리가 불가능함","알고리즘의 길이가 입력 데이터보다 작음","입력 데이터 수와 관계없이 알고리즘 수행시간이 일정함"],"ans":4,"exp":{"concept":"시간 복잡도는 입력 데이터 수(n)가 늘어날 때 수행 시간이 어떻게 늘어나는지를 나타낸다. O(1)은 입력이 아무리 많아도 수행 시간이 늘지 않고 일정하다는 뜻이다. 배열에서 인덱스로 원소 하나를 꺼내는 것이 대표적인 예다.","choices":[{"verdict":"오답","why":"O(1)은 입력 데이터가 한 개라는 뜻이 아니라, 입력 크기와 관계없이 수행 시간이 일정하다는 뜻이다."},{"verdict":"오답","why":"O(1)은 가장 빠른 복잡도이므로 처리가 불가능하다는 것과 반대다."},{"verdict":"오답","why":"알고리즘 코드의 길이와 입력 데이터 크기를 비교하는 개념이 아니다."},{"verdict":"정답","why":"O(1)은 상수 시간으로, 입력 데이터 수와 관계없이 수행 시간이 일정함을 뜻한다."}],"keywords":[{"term":"O(1)","desc":"상수 시간, 입력 크기와 무관"},{"term":"O(log n)","desc":"로그 시간, 이진 탐색"},{"term":"O(n)","desc":"선형 시간, 순차 탐색"},{"term":"O(n²)","desc":"제곱 시간, 버블·선택·삽입 정렬"}],"memo":"괄호 안에 n이 없으면 n과 상관없다는 뜻이다."}},{"id":"written-2022-3-39","no":39,"unit":"소프트웨어 개발","q":"테스트 드라이버(Test Driver)에 관한 설명 중 틀린 것은?","choices":["시험 대상 모듈을 호출하는 간이 소프트웨어에 해당한다.","테스트 대상 모듈이 호출하는 하위 모듈의 역할을 담당한다.","상향식 통합 테스트에서 사용한다.","필요에 따라 매개 변수를 전달하며, 모듈을 수행한 뒤의 결과를 보여줄 수 있다."],"ans":2,"exp":{"concept":"테스트 드라이버(Driver)와 스텁(Stub)은 아직 완성되지 않은 모듈을 대신하는 임시 프로그램이다. 드라이버는 테스트 대상의 상위 모듈 역할로 대상을 호출하고 결과를 받으며, 상향식 통합 테스트에서 쓴다. 스텁은 테스트 대상이 호출하는 하위 모듈 역할로, 하향식 통합 테스트에서 쓴다.","choices":[{"verdict":"오답","why":"드라이버는 시험 대상 모듈을 호출하는 간이 소프트웨어이므로 옳은 설명이다."},{"verdict":"정답","why":"테스트 대상 모듈이 호출하는 하위 모듈의 역할을 하는 것은 스텁(Stub)이다."},{"verdict":"오답","why":"드라이버는 하위 모듈부터 테스트하는 상향식 통합 테스트에서 상위 모듈을 대신하므로 옳은 설명이다."},{"verdict":"오답","why":"드라이버는 필요한 매개변수를 넘겨 대상 모듈을 실행하고 그 결과를 보여 줄 수 있으므로 옳은 설명이다."}],"keywords":[{"term":"테스트 드라이버(Test Driver)","desc":"상위 모듈 대역, 상향식 통합 테스트에서 사용"},{"term":"테스트 스텁(Test Stub)","desc":"하위 모듈 대역, 하향식 통합 테스트에서 사용"},{"term":"상향식 통합 테스트","desc":"하위 모듈부터 결합하며 테스트"},{"term":"하향식 통합 테스트","desc":"상위 모듈부터 결합하며 테스트"}],"memo":"상향식은 위가 비어 있으니 드라이버로 위를 채우고, 하향식은 아래가 비어 있으니 스텁으로 아래를 채운다."}},{"id":"written-2022-3-40","no":40,"unit":"소프트웨어 개발","q":"다음 중 클린 코드 작성원칙과 거리가 먼 것은?","choices":["단순하고 명료한 코드 작성","누구나 쉽게 이해할 수 있는 코드 작성","중복을 최대화한 코드 작성","다른 모듈에 주는 영향 최소화"],"ans":3,"exp":{"concept":"클린 코드(Clean Code)는 누구나 쉽게 읽고 고칠 수 있게 잘 정리된 코드다. 작성 원칙은 가독성, 단순성, 의존성 배제, 중복성 최소화, 추상화다. 같은 코드가 여러 곳에 반복되면 고칠 때 모두 찾아 고쳐야 하므로 중복은 줄여야 한다.","choices":[{"verdict":"오답","why":"단순하고 명료하게 작성하는 것은 단순성 원칙에 해당한다."},{"verdict":"오답","why":"누구나 쉽게 이해할 수 있게 작성하는 것은 가독성 원칙에 해당한다."},{"verdict":"정답","why":"클린 코드는 중복을 최소화해야 하므로 중복을 최대화하는 것은 원칙과 반대다."},{"verdict":"오답","why":"다른 모듈에 주는 영향을 최소화하는 것은 의존성 배제 원칙에 해당한다."}],"keywords":[{"term":"가독성","desc":"누구나 읽기 쉽게 작성"},{"term":"단순성","desc":"한 번에 한 가지 일만 하도록 간단하게 작성"},{"term":"의존성 배제","desc":"다른 모듈에 미치는 영향 최소화"},{"term":"중복성 최소화","desc":"중복된 코드를 제거"},{"term":"추상화","desc":"상위에서는 간략히, 세부는 하위에서 구현"}],"memo":"클린 코드 원칙 '가단의중추'(가독성-단순성-의존성 배제-중복성 최소화-추상화)."}},{"id":"written-2022-3-41","no":41,"unit":"데이터베이스 구축","q":"파티셔닝 방식 가운데 ‘월별, 분기별’처럼 지정된 열의 값을 기준으로 범위를 정해 분할하는 방식은 무엇인가?","choices":["Composite Partitioning","Range Partitioning","List Partitioning","Hash Partitioning"],"ans":2,"exp":{"concept":"파티셔닝(Partitioning)은 큰 테이블을 여러 조각으로 나누어 저장하는 기법이다. 범위(Range) 분할은 날짜나 숫자처럼 값의 범위를 기준으로 나누는 방식으로, 월별·분기별 분할이 대표적이다.","choices":[{"verdict":"오답","why":"조합 분할(Composite Partitioning)은 범위 분할 후 다시 해시 분할하는 등 두 가지 이상의 분할 방식을 조합하는 방식이다."},{"verdict":"정답","why":"범위 분할(Range Partitioning)은 지정된 열 값의 범위(월별, 분기별 등)를 기준으로 나누는 방식이다."},{"verdict":"오답","why":"목록 분할(List Partitioning)은 지역처럼 특정 값의 목록을 지정해 나누는 방식이다."},{"verdict":"오답","why":"해시 분할(Hash Partitioning)은 해시 함수 결과에 따라 데이터를 고르게 나누는 방식이다."}],"keywords":[{"term":"범위 분할(Range Partitioning)","desc":"값의 범위로 분할, 날짜·월별"},{"term":"해시 분할(Hash Partitioning)","desc":"해시 함수로 고르게 분할"},{"term":"목록 분할(List Partitioning)","desc":"지정한 값 목록으로 분할, 지역별"},{"term":"조합 분할(Composite Partitioning)","desc":"두 가지 이상 분할 방식을 조합"}],"memo":"월별·분기별·연도별처럼 연속된 구간이면 범위(Range) 분할이다."}},{"id":"written-2022-3-42","no":42,"unit":"데이터베이스 구축","q":"물리적 데이터베이스 설계의 바로 앞 단계로서, 데이터 모델링이라고도 불리는 데이터베이스 설계 단계는 무엇인가?","choices":["데이터베이스 구현","정보 모델링","개념적 데이터베이스 설계","논리적 데이터베이스 설계"],"ans":4,"exp":{"concept":"데이터베이스 설계는 요구 조건 분석 → 개념적 설계 → 논리적 설계 → 물리적 설계 → 구현 순서로 진행한다. 논리적 설계는 개념적 설계에서 만든 E-R 모델을 특정 DBMS가 처리할 수 있는 논리적 구조(관계 스키마 등)로 바꾸는 단계로, 데이터 모델링이라고도 한다. 물리적 설계 바로 앞 단계다.","choices":[{"verdict":"오답","why":"데이터베이스 구현은 물리적 설계 다음 단계로, 실제 DBMS에 스키마를 만들고 데이터를 넣는 단계다."},{"verdict":"오답","why":"정보 모델링은 개념적 설계(E-R 모델 작성)를 달리 부르는 말로, 물리적 설계 바로 앞 단계가 아니다."},{"verdict":"오답","why":"개념적 설계는 요구사항을 바탕으로 E-R 다이어그램 같은 개념 스키마를 만드는 단계로, 논리적 설계의 앞 단계다."},{"verdict":"정답","why":"논리적 설계는 물리적 설계 바로 앞 단계이며, 데이터 모델링이라고도 부른다."}],"keywords":[{"term":"개념적 설계","desc":"E-R 다이어그램 작성, DBMS에 독립적"},{"term":"논리적 설계","desc":"관계 스키마 변환과 정규화, 데이터 모델링"},{"term":"물리적 설계","desc":"저장 구조, 인덱스, 접근 경로 설계"},{"term":"DB 설계 순서","desc":"요구 분석 → 개념 → 논리 → 물리 → 구현"}],"memo":"DB 설계 순서 '요개논물구'."}},{"id":"written-2022-3-43","no":43,"unit":"데이터베이스 구축","q":"트리거(Trigger)에 관한 설명으로 옳은 것은?","choices":["특정 기능을 수행하는 일종의 트랜잭션 언어로서, 호출을 통해 실행되어 미리 저장해 둔 SQL 작업을 수행한다.","시스템에서 어떤 일이 발생한 것을 뜻한다.","이벤트가 발생할 때마다 관련 작업이 자동으로 수행되는 절차형 SQL을 말한다.","DBMS에 내장되어 있으며 작성된 SQL이 효율적으로 수행되도록 최적의 경로를 찾아 주는 모듈이다."],"ans":3,"exp":{"concept":"트리거(Trigger)는 데이터의 삽입, 갱신, 삭제 같은 이벤트가 일어나면 자동으로 실행되는 절차형 SQL이다. 사람이 직접 호출하지 않아도 정해진 조건이 되면 저절로 동작한다는 점이 프로시저와 다르다.","choices":[{"verdict":"오답","why":"호출을 통해 실행되어 미리 저장해 둔 SQL 작업을 수행하는 것은 저장 프로시저(Stored Procedure)에 대한 설명이다."},{"verdict":"오답","why":"시스템에서 어떤 일이 발생한 것은 이벤트(Event)에 대한 설명이다."},{"verdict":"정답","why":"트리거는 이벤트가 발생할 때마다 관련 작업이 자동으로 수행되는 절차형 SQL이다."},{"verdict":"오답","why":"SQL이 효율적으로 수행되도록 최적의 경로를 찾아 주는 모듈은 옵티마이저(Optimizer)다."}],"keywords":[{"term":"트리거(Trigger)","desc":"이벤트 발생 시 자동 실행되는 절차형 SQL"},{"term":"저장 프로시저(Stored Procedure)","desc":"호출해서 실행하는 절차형 SQL"},{"term":"사용자 정의 함수(User Defined Function)","desc":"실행 후 값을 반환하는 절차형 SQL"},{"term":"옵티마이저(Optimizer)","desc":"SQL의 최적 실행 경로를 결정하는 DBMS 모듈"}],"memo":"트리거는 방아쇠다. 이벤트가 당기면 저절로 발사된다."}},{"id":"written-2022-3-44","no":44,"unit":"데이터베이스 구축","q":"키는 개체 집합 내에서 개체를 고유하게 식별할 수 있는 속성이다. 데이터베이스에서 쓰이는 키의 종류에 관한 설명으로 옳지 않은 것은?","choices":["슈퍼키는 한 개 이상의 속성들의 집합으로 이루어진 키이다.","외래키는 참조 대상 테이블의 기본키나 유일키를 참조하는 속성 또는 속성 집합이다.","후보키는 개체들을 고유하게 식별할 수 있는 속성을 말한다.","대체키는 슈퍼키 중에서 기본키를 제외한 나머지 키를 말한다."],"ans":4,"exp":{"concept":"키(Key)는 튜플을 구별하는 기준이 되는 속성이다. 슈퍼키는 유일성만 만족하는 속성 집합, 후보키는 유일성과 최소성을 모두 만족하는 속성 집합이다. 후보키 중 하나를 골라 기본키로 정하고, 나머지 후보키를 대체키라고 한다.","choices":[{"verdict":"오답","why":"슈퍼키는 한 개 이상의 속성 집합으로 유일성을 만족하는 키이므로 옳은 설명이다."},{"verdict":"오답","why":"외래키는 다른 테이블의 기본키(또는 유일키)를 참조하는 속성이나 속성 집합이므로 옳은 설명이다."},{"verdict":"오답","why":"후보키는 튜플을 유일하게 식별할 수 있는 최소한의 속성 집합이므로 옳은 설명이다."},{"verdict":"정답","why":"대체키는 슈퍼키가 아니라 후보키 중에서 기본키를 제외한 나머지 키다."}],"keywords":[{"term":"슈퍼키(Super Key)","desc":"유일성만 만족"},{"term":"후보키(Candidate Key)","desc":"유일성과 최소성을 모두 만족"},{"term":"기본키(Primary Key)","desc":"후보키 중 선택한 대표 키, NULL 불가"},{"term":"대체키(Alternate Key)","desc":"기본키를 제외한 나머지 후보키"},{"term":"외래키(Foreign Key)","desc":"다른 릴레이션의 기본키를 참조"}],"memo":"대체키는 기본키 선발에서 떨어진 '후보'키다. 슈퍼키라는 말이 나오면 틀린 문장이다."}},{"id":"written-2022-3-45","no":45,"unit":"데이터베이스 구축","q":"데이터베이스에 영향을 주는 생성, 읽기, 갱신, 삭제 연산을 기준으로 프로세스와 테이블 간의 매트릭스를 작성하여 트랜잭션을 분석하는 것은?","choices":["CRUD 분석","일치 분석","CASE 분석","연관성 분석"],"ans":1,"exp":{"concept":"CRUD 분석은 데이터베이스에 대한 생성(Create), 읽기(Read), 갱신(Update), 삭제(Delete) 연산을 기준으로 프로세스와 테이블 사이의 관계를 매트릭스(표)로 그려 트랜잭션을 분석하는 방법이다. 이 표를 CRUD 매트릭스라고 한다.","choices":[{"verdict":"정답","why":"CRUD 분석은 생성, 읽기, 갱신, 삭제 연산을 기준으로 프로세스와 테이블 간 매트릭스를 작성해 트랜잭션을 분석한다."},{"verdict":"오답","why":"일치 분석은 이 매트릭스 분석 방법의 이름이 아니다."},{"verdict":"오답","why":"CASE(Computer Aided Software Engineering)는 소프트웨어 개발을 자동화해 돕는 도구를 말하며 트랜잭션 매트릭스 분석이 아니다."},{"verdict":"오답","why":"연관성 분석은 데이터 사이의 연관 규칙을 찾는 데이터 마이닝 기법이다."}],"keywords":[{"term":"CRUD","desc":"Create, Read, Update, Delete"},{"term":"CRUD 매트릭스","desc":"프로세스와 테이블 사이의 CRUD 연산을 표로 정리"},{"term":"트랜잭션 분석","desc":"트랜잭션이 다루는 데이터 양과 연산을 분석"}],"memo":"생성·읽기·갱신·삭제 네 단어의 영문 첫 글자가 바로 CRUD다."}},{"id":"written-2022-3-46","no":46,"unit":"데이터베이스 구축","q":"Oracle Database의 TRUNCATE 명령어에 관한 설명으로 옳지 않은 것은?","choices":["DELETE와 마찬가지로 테이블의 모든 데이터를 삭제한다.","DELETE와 마찬가지로 ROLLBACK 명령어로 삭제된 데이터를 되살릴 수 있다.","DELETE보다 빠르게 데이터를 제거할 수 있다.","DROP과는 달리 테이블 스키마가 제거되지 않고 유지된다."],"ans":2,"exp":{"concept":"TRUNCATE는 테이블의 모든 행을 한 번에 삭제하는 명령으로, DDL에 속해 실행 즉시 자동 커밋된다. 그래서 오라클에서는 ROLLBACK으로 되살릴 수 없다. DELETE는 DML이라 ROLLBACK이 가능하고, DROP은 테이블 구조까지 없앤다.","choices":[{"verdict":"오답","why":"TRUNCATE도 DELETE처럼 테이블의 모든 데이터를 삭제하므로 옳은 설명이다."},{"verdict":"정답","why":"TRUNCATE는 DDL로 자동 커밋되어 ROLLBACK으로 되살릴 수 없으므로 옳지 않은 설명이다."},{"verdict":"오답","why":"TRUNCATE는 행 단위 로그를 남기지 않아 DELETE보다 빠르므로 옳은 설명이다."},{"verdict":"오답","why":"TRUNCATE는 데이터만 지우고 테이블 구조(스키마)는 남기므로 옳은 설명이다."}],"keywords":[{"term":"DELETE","desc":"DML, 조건에 맞는 행 삭제, ROLLBACK 가능"},{"term":"TRUNCATE","desc":"DDL, 모든 행 삭제, 구조 유지, ROLLBACK 불가"},{"term":"DROP","desc":"DDL, 테이블 구조까지 삭제"},{"term":"자동 커밋(Auto Commit)","desc":"DDL 실행 시 자동으로 확정되는 것"}],"memo":"삭제 강도는 DELETE < TRUNCATE < DROP. DDL인 TRUNCATE와 DROP은 되돌릴 수 없다."}},{"id":"written-2022-3-47","no":47,"unit":"데이터베이스 구축","q":"데이터베이스 무결성에 대한 설명 중 옳은 것은?","choices":["참조 무결성 규정은 속성 값들이 사용자가 정의한 제약 조건을 만족해야 한다는 규정이다.","개체 무결성 규정은 한 릴레이션의 기본키를 구성하는 어떤 속성값도 널(NULL) 값이나 중복값을 가질 수 없다고 규정하는 것이다.","도메인 무결성 규정은 외래키 값이 Null이거나 참조 릴레이션의 기본키 값과 동일해야 한다는 규정이다.","사용자 정의 무결성 규정은 주어진 튜플의 값이 그 튜플이 정의된 도메인에 속하는 값이어야 한다고 규정하는 것이다."],"ans":2,"exp":{"concept":"무결성 제약 조건은 데이터의 정확성을 지키기 위한 규칙이다. 개체 무결성은 기본키가 NULL이나 중복 값을 가질 수 없다는 규칙, 참조 무결성은 외래키 값이 NULL이거나 참조하는 테이블의 기본키 값과 같아야 한다는 규칙, 도메인 무결성은 속성 값이 정해진 도메인에 속해야 한다는 규칙이다.","choices":[{"verdict":"오답","why":"속성 값들이 사용자가 정의한 제약 조건을 만족해야 한다는 것은 사용자 정의 무결성이다."},{"verdict":"정답","why":"개체 무결성은 기본키를 구성하는 속성이 NULL 값이나 중복 값을 가질 수 없다는 규정이다."},{"verdict":"오답","why":"외래키 값이 NULL이거나 참조 릴레이션의 기본키 값과 같아야 한다는 것은 참조 무결성이다."},{"verdict":"오답","why":"튜플의 값이 정의된 도메인에 속해야 한다는 것은 도메인 무결성이다."}],"keywords":[{"term":"개체 무결성(Entity Integrity)","desc":"기본키는 NULL과 중복 불가"},{"term":"참조 무결성(Referential Integrity)","desc":"외래키는 NULL이거나 참조 기본키 값과 같아야 함"},{"term":"도메인 무결성(Domain Integrity)","desc":"속성 값은 정의된 도메인에 속해야 함"},{"term":"사용자 정의 무결성","desc":"사용자가 정한 업무 규칙을 만족해야 함"}],"memo":"이 문제는 보기마다 설명과 이름을 서로 바꿔 놓았다. 기본키-개체, 외래키-참조, 도메인-도메인으로 짝지어 보자."}},{"id":"written-2022-3-48","no":48,"unit":"데이터베이스 구축","q":"다음은 트랜잭션의 상태를 나타낸 그림이다. 각 상태에 대한 설명으로 옳지 않은 것은?<img class=\"q-img\" src=\"data/img/77bf22a3b9a0e9ff8c1db9fc23790aac.png\" width=\"494\" alt=\"문항 원본 자료\">","choices":["철회는 트랜잭션 수행에 실패하여 Rollback 연산까지 수행된 상태를 말한다.","부분 완료는 트랜잭션의 일부 연산만 완료되어 Commit된 상태를 말한다.","완료는 트랜잭션이 성공적으로 종료되어 Commit 연산까지 수행된 상태를 말한다.","활동 상태는 트랜잭션이 수행을 시작하여 현재 실행되고 있는 상태를 말한다."],"ans":2,"exp":{"concept":"트랜잭션은 활동, 부분 완료, 완료, 실패, 철회 다섯 상태를 거친다. 실행 중이면 활동, 마지막 연산까지 실행했지만 아직 Commit하기 전이면 부분 완료, Commit까지 끝나면 완료다. 오류로 중단되면 실패, 실패 후 Rollback까지 마치면 철회 상태가 된다.","choices":[{"verdict":"오답","why":"철회(Aborted)는 트랜잭션이 실패하여 Rollback 연산까지 수행한 상태이므로 옳은 설명이다."},{"verdict":"정답","why":"부분 완료(Partially Committed)는 트랜잭션의 마지막 연산까지 실행했지만 아직 Commit 연산은 실행하기 전의 상태다. 일부 연산만 끝나 Commit된 상태가 아니다."},{"verdict":"오답","why":"완료(Committed)는 트랜잭션이 성공적으로 끝나 Commit 연산까지 수행한 상태이므로 옳은 설명이다."},{"verdict":"오답","why":"활동(Active)은 트랜잭션이 실행을 시작해 현재 실행 중인 상태이므로 옳은 설명이다."}],"keywords":[{"term":"활동(Active)","desc":"트랜잭션이 실행 중인 상태"},{"term":"부분 완료(Partially Committed)","desc":"마지막 연산까지 실행, Commit 직전"},{"term":"완료(Committed)","desc":"Commit까지 수행한 상태"},{"term":"실패(Failed)","desc":"오류로 실행이 중단된 상태"},{"term":"철회(Aborted)","desc":"Rollback까지 수행한 상태"}],"memo":"부분 완료는 '연산은 다 했지만 Commit은 아직'이다. 이름의 '부분'에 속지 말자."}},{"id":"written-2022-3-49","no":49,"unit":"데이터베이스 구축","q":"데이터베이스는 관계형, 계층형, 네트워크형 등 여러 종류로 나뉘는데, 이를 구분하는 기준은 무엇인가?","choices":["속성(Attribute)","관계(Relationship)","제약 조건(Constraint)","개체(Object)"],"ans":2,"exp":{"concept":"데이터베이스를 관계형, 계층형, 네트워크형으로 나누는 기준은 데이터 사이의 관계(Relationship)를 어떤 구조로 표현하느냐다. 관계형은 표(테이블), 계층형은 트리(부모-자식), 네트워크형은 그래프(오너-멤버) 형태로 관계를 표현한다.","choices":[{"verdict":"오답","why":"속성(Attribute)은 개체가 가진 특성으로, 데이터베이스 모델을 구분하는 기준이 아니다."},{"verdict":"정답","why":"관계를 표, 트리, 그래프 중 어떤 구조로 표현하느냐에 따라 관계형, 계층형, 네트워크형으로 나뉜다."},{"verdict":"오답","why":"제약 조건(Constraint)은 데이터의 무결성을 지키기 위한 규칙으로, 모델 구분 기준이 아니다."},{"verdict":"오답","why":"개체(Object)는 표현하려는 대상 자체로, 모든 모델에 공통으로 있으므로 구분 기준이 아니다."}],"keywords":[{"term":"관계형 데이터 모델","desc":"관계를 테이블(릴레이션)로 표현"},{"term":"계층형 데이터 모델","desc":"관계를 트리(부모-자식, 1:N)로 표현"},{"term":"네트워크형 데이터 모델","desc":"관계를 그래프(오너-멤버, N:M)로 표현"},{"term":"관계(Relationship)","desc":"개체 사이의 연관성"}],"memo":"모델 이름 자체가 관계 표현 방식이다. 표-관계형, 트리-계층형, 그래프-네트워크형."}},{"id":"written-2022-3-50","no":50,"unit":"데이터베이스 구축","q":"개체-관계(E-R) 모델에 관한 설명 중 옳지 않은 것은?","choices":["특정 DBMS를 고려해 제작하지는 않는다.","개체는 마름모로, 속성은 사각형으로 표현한다.","E-R 모델의 기본적인 아이디어를 시각적으로 가장 잘 나타낸 것이 E-R 다이어그램이다.","개념적 데이터베이스 단계에서 만들어진다."],"ans":2,"exp":{"concept":"E-R(개체-관계) 모델은 피터 첸(Peter Chen)이 제안한 개념적 데이터 모델로, 현실 세계를 개체, 속성, 관계로 표현한다. E-R 다이어그램에서 개체는 사각형, 관계는 마름모, 속성은 타원으로 그린다. 특정 DBMS와 무관하게 개념적 설계 단계에서 만든다.","choices":[{"verdict":"오답","why":"E-R 모델은 특정 DBMS를 고려하지 않는 개념적 모델이므로 옳은 설명이다."},{"verdict":"정답","why":"E-R 다이어그램에서 개체는 사각형, 관계는 마름모, 속성은 타원으로 표현한다. 개체를 마름모, 속성을 사각형이라고 한 것은 틀렸다."},{"verdict":"오답","why":"E-R 다이어그램은 E-R 모델의 아이디어를 시각적으로 나타낸 그림이므로 옳은 설명이다."},{"verdict":"오답","why":"E-R 모델은 개념적 데이터베이스 설계 단계에서 만들어지므로 옳은 설명이다."}],"keywords":[{"term":"개체(Entity)","desc":"사각형으로 표현"},{"term":"관계(Relationship)","desc":"마름모로 표현"},{"term":"속성(Attribute)","desc":"타원으로 표현"},{"term":"기본키 속성","desc":"밑줄 친 타원으로 표현"},{"term":"피터 첸(Peter Chen)","desc":"E-R 모델을 제안한 사람"}],"memo":"개체는 네모, 관계는 마름모, 속성은 동그라미(타원). '사마타'로 외운다."}},{"id":"written-2022-3-51","no":51,"unit":"데이터베이스 구축","q":"분산 데이터베이스의 특징에 관한 설명 중 틀린 것은?","choices":["새로운 지역 서버나 장비를 추가하는 등의 작업이 용이하다.","위치 투명성, 중복 투명성, 병행 투명성, 장애 투명성을 목표로 삼는다.","지역 서버의 고유 데이터에 대한 작업은 중앙 서버의 통제를 받지 않고 자유롭게 수행할 수 있다.","데이터베이스 설계와 소프트웨어 개발이 쉬우며, 시스템 전반의 성능이 향상된다."],"ans":4,"exp":{"concept":"분산 데이터베이스는 논리적으로는 하나의 데이터베이스지만 물리적으로는 네트워크로 연결된 여러 지역(사이트)에 나뉘어 저장된 데이터베이스다. 지역 자치성이 높고 확장이 쉬우며 신뢰성과 가용성이 좋아지지만, 구조가 복잡해 설계와 개발이 어렵고 비용이 많이 든다.","choices":[{"verdict":"오답","why":"새 지역 서버나 장비를 추가해 쉽게 확장할 수 있는 것은 분산 데이터베이스의 장점이므로 옳은 설명이다."},{"verdict":"오답","why":"위치, 중복, 병행, 장애 투명성은 분산 데이터베이스의 목표이므로 옳은 설명이다."},{"verdict":"오답","why":"지역 서버의 고유 데이터는 중앙의 통제 없이 각 지역에서 처리할 수 있는 지역 자치성이 있으므로 옳은 설명이다."},{"verdict":"정답","why":"분산 데이터베이스는 구조가 복잡해 설계와 소프트웨어 개발이 어렵고 비용이 많이 들므로 옳지 않은 설명이다."}],"keywords":[{"term":"위치 투명성(Location Transparency)","desc":"데이터의 실제 위치를 몰라도 접근 가능"},{"term":"중복 투명성(Replication Transparency)","desc":"데이터가 여러 곳에 복제되어 있어도 하나처럼 사용"},{"term":"병행 투명성(Concurrency Transparency)","desc":"여러 사용자가 동시에 써도 결과가 일관됨"},{"term":"장애 투명성(Failure Transparency)","desc":"장애가 생겨도 트랜잭션을 정확히 처리"}],"memo":"분산은 확장·신뢰성에는 유리하지만 설계·개발·관리는 복잡해진다. '설계가 쉽다'는 틀린 말이다."}},{"id":"written-2022-3-52","no":52,"unit":"데이터베이스 구축","q":"데이터베이스의 병행 제어(Concurrency Control)에 관한 설명 중 옳지 않은 것은?","choices":["로킹 단위가 크면 병행성 수준은 낮아진다.","로킹 단위가 크면 병행 제어 기법은 복잡해진다.","여러 사용자가 데이터베이스에 동시에 접근하여 데이터를 처리하기 위한 것이다.","처리 결과의 정확성을 유지하기 위해 데이터를 잠그거나 여는 등의 제어가 필요하다."],"ans":2,"exp":{"concept":"병행 제어는 여러 트랜잭션이 동시에 실행되어도 데이터베이스의 일관성이 깨지지 않도록 조정하는 것이다. 로킹(Locking) 단위는 잠그는 데이터의 크기로, 단위가 크면 잠금 수가 적어 제어가 간단하지만 동시에 쓸 수 있는 부분이 줄어 병행성이 낮아진다. 단위가 작으면 그 반대다.","choices":[{"verdict":"오답","why":"로킹 단위가 크면 한 번에 넓은 영역을 잠그므로 병행성 수준이 낮아진다. 옳은 설명이다."},{"verdict":"정답","why":"로킹 단위가 크면 관리할 잠금의 수가 적어 병행 제어 기법이 간단해진다. 복잡해지는 것은 단위가 작을 때다."},{"verdict":"오답","why":"병행 제어는 여러 사용자가 데이터베이스에 동시에 접근해 처리하기 위한 것이므로 옳은 설명이다."},{"verdict":"오답","why":"결과의 정확성을 지키기 위해 데이터를 잠그고(Lock) 여는(Unlock) 제어가 필요하므로 옳은 설명이다."}],"keywords":[{"term":"로킹(Locking)","desc":"데이터를 잠가 다른 트랜잭션의 접근을 막는 병행 제어 기법"},{"term":"로킹 단위 큼","desc":"잠금 수 적음, 오버헤드 감소, 병행성 낮음, 제어 간단"},{"term":"로킹 단위 작음","desc":"잠금 수 많음, 오버헤드 증가, 병행성 높음, 제어 복잡"},{"term":"2단계 로킹(2PL)","desc":"확장 단계와 축소 단계로 나누어 잠금을 관리"}],"memo":"건물 전체를 잠그면(큰 단위) 관리는 쉽지만 아무도 못 들어간다. 방마다 잠그면(작은 단위) 여럿이 쓰지만 관리가 복잡하다."}},{"id":"written-2022-3-53","no":53,"unit":"데이터베이스 구축","q":"무결성 보장을 위해 트랜잭션이 갖추어야 할 특성에 관한 설명 중 옳지 않은 것은?","choices":["트랜잭션의 수행 여부와 관계 없이 데이터베이스가 가진 고정 요소는 일관되어야 한다.","Commit과 Rollback 명령어로 보장받는 트랜잭션의 특성은 일관성이다.","트랜잭션 안의 모든 명령은 반드시 완벽하게 수행되어야 하고, 모두 완벽히 수행되지 못하여 어느 하나라도 오류가 생기면 트랜잭션 전체가 취소되어야 한다.","둘 이상의 트랜잭션이 동시에 병행 실행될 때 어느 하나의 트랜잭션이 실행되는 중에 다른 트랜잭션의 연산이 끼어들 수 없다."],"ans":2,"exp":{"concept":"트랜잭션은 원자성(Atomicity), 일관성(Consistency), 독립성(Isolation), 지속성(Durability)의 ACID 특성을 가져야 한다. 원자성은 트랜잭션이 전부 실행되거나 전혀 실행되지 않아야 한다는 성질로, Commit과 Rollback 연산이 이를 보장한다.","choices":[{"verdict":"오답","why":"트랜잭션 수행 전후에 데이터베이스의 고정 요소(제약 조건)가 일관되어야 한다는 것은 일관성에 대한 옳은 설명이다."},{"verdict":"정답","why":"Commit과 Rollback으로 보장하는 특성은 일관성이 아니라 원자성이다."},{"verdict":"오답","why":"모든 연산이 완벽히 수행되거나 하나라도 실패하면 전체를 취소해야 한다는 것은 원자성에 대한 옳은 설명이다."},{"verdict":"오답","why":"병행 실행 중인 트랜잭션에 다른 트랜잭션의 연산이 끼어들 수 없다는 것은 독립성(격리성)에 대한 옳은 설명이다."}],"keywords":[{"term":"원자성(Atomicity)","desc":"모두 실행 또는 전혀 실행 안 함, Commit/Rollback으로 보장"},{"term":"일관성(Consistency)","desc":"실행 후에도 데이터베이스가 일관된 상태"},{"term":"독립성(Isolation)","desc":"실행 중인 트랜잭션에 다른 트랜잭션이 끼어들 수 없음"},{"term":"지속성(Durability)","desc":"완료된 결과는 영구히 반영"}],"memo":"All or Nothing을 만드는 도구가 Commit과 Rollback이다. 그래서 원자성이다."}},{"id":"written-2022-3-54","no":54,"unit":"데이터베이스 구축","q":"관계 대수와 관계 해석에 관한 설명 중 옳지 않은 것은?","choices":["관계 대수는 본래 수학의 프레디킷 해석에 기반을 두고 있다.","관계 해석은 원하는 정보가 무엇인지만 정의하는 비절차적 특징을 지니고 있다.","관계 해석은 관계 데이터의 연산을 표현하는 방법이다.","관계 대수로 표현된 식은 관계 해석으로도 표현할 수 있다."],"ans":1,"exp":{"concept":"관계 대수와 관계 해석은 관계 데이터베이스에서 원하는 데이터를 얻는 방법을 표현하는 언어다. 관계 대수는 원하는 결과를 얻기 위해 어떤 연산을 어떤 순서로 할지 명시하는 절차적 언어이고, 관계 해석은 원하는 정보가 무엇인지만 정의하는 비절차적 언어다. 관계 해석은 수학의 프레디킷 해석(술어 해석)에 기반을 두며, 두 방법의 표현 능력은 같다.","choices":[{"verdict":"정답","why":"프레디킷 해석(술어 해석)에 기반을 둔 것은 관계 해석이다. 관계 대수는 집합 연산과 관계 연산으로 이루어진 절차적 언어다."},{"verdict":"오답","why":"관계 해석은 무엇을 얻을지만 정의하는 비절차적 특징을 가지므로 옳은 설명이다."},{"verdict":"오답","why":"관계 해석은 관계 데이터의 연산을 표현하는 방법이므로 옳은 설명이다."},{"verdict":"오답","why":"관계 대수와 관계 해석은 표현 능력이 동등하므로 관계 대수 식은 관계 해석으로도 표현할 수 있다. 옳은 설명이다."}],"keywords":[{"term":"관계 대수(Relational Algebra)","desc":"절차적 언어, 어떻게(How) 얻을지 기술"},{"term":"관계 해석(Relational Calculus)","desc":"비절차적 언어, 무엇을(What) 얻을지 기술, 프레디킷 해석 기반"},{"term":"순수 관계 연산자","desc":"Select(σ), Project(π), Join(⋈), Division(÷)"},{"term":"코드(E. F. Codd)","desc":"관계 데이터 모델과 관계 해석을 제안"}],"memo":"해석은 술어(Predicate), 대수는 절차. '해석-술어-비절차'를 한 묶음으로 외운다."}},{"id":"written-2022-3-55","no":55,"unit":"데이터베이스 구축","q":"다음 SQL문을 실행했을 때의 결과로 가장 알맞은 설명은?<pre class=\"q-sql\"><code class=\"language-sql\">ALTER TABLE 학생 DROP 학년 CASCADE;</code></pre>","choices":["학년 테이블에서 학생 속성을 제거하며, 학생 속성을 참조하는 다른 테이블의 속성이 있으면 제거를 중단한다.","학생 테이블에서 학년 속성을 제거하며, 학년 속성을 참조하는 다른 테이블의 속성이 있으면 제거를 중단한다.","학생 테이블에서 학년 속성을 제거하며, 학년 속성을 참조하는 다른 테이블의 속성도 같이 제거한다.","학년 테이블에서 학생 속성을 제거하며, 학생 속성을 참조하는 다른 테이블의 속성도 같이 제거한다."],"ans":3,"exp":{"concept":"ALTER TABLE 테이블명 DROP 열이름 형식은 해당 테이블에서 열(속성)을 삭제한다. 뒤에 CASCADE를 붙이면 그 속성을 참조하는 다른 객체(다른 테이블의 속성, 제약 조건 등)까지 연쇄적으로 함께 제거하고, RESTRICT를 붙이면 참조하는 것이 있을 때 삭제를 거부한다.","choices":[{"verdict":"오답","why":"ALTER TABLE 바로 뒤의 학생이 테이블이고 학년이 속성이므로 테이블과 속성이 뒤바뀌었다. 또한 참조 시 중단하는 것은 RESTRICT의 동작이다."},{"verdict":"오답","why":"학생 테이블에서 학년 속성을 제거하는 것은 맞지만, 참조하는 속성이 있을 때 중단하는 것은 RESTRICT의 동작이다."},{"verdict":"정답","why":"학생 테이블에서 학년 속성을 제거하고, CASCADE이므로 학년을 참조하는 다른 테이블의 속성도 함께 제거한다."},{"verdict":"오답","why":"ALTER TABLE 바로 뒤의 학생이 테이블이고 학년이 속성이므로 테이블과 속성이 뒤바뀌었다."}],"keywords":[{"term":"ALTER TABLE","desc":"테이블 구조를 변경하는 DDL 명령"},{"term":"CASCADE","desc":"참조하는 다른 개체까지 연쇄적으로 함께 처리"},{"term":"RESTRICT","desc":"참조하는 개체가 있으면 명령을 거부"},{"term":"DROP","desc":"테이블, 열 등 개체를 제거"}],"memo":"CASCADE는 폭포, 줄줄이 같이 지운다. RESTRICT는 제한, 걸리면 멈춘다."}},{"id":"written-2022-3-56","no":56,"unit":"데이터베이스 구축","q":"관계형 데이터베이스의 구성 요소에 관한 설명 중 틀린 것은?","choices":["속성을 구성하는 값에는 같은 값이 있을 수 있다.","한 릴레이션에는 이름이 동일한 속성이 있을 수 있다.","한 릴레이션에 포함된 튜플은 모두 서로 다르다.","한 릴레이션을 구성하는 속성 사이에 순서는 없다."],"ans":2,"exp":{"concept":"관계형 데이터베이스의 릴레이션(테이블)은 몇 가지 특징을 가진다. 튜플은 모두 서로 달라야 하고, 튜플 사이와 속성 사이에는 순서가 없으며, 속성 값은 더 이상 쪼갤 수 없는 원자값이어야 한다. 속성은 이름으로 구별하므로 한 릴레이션 안에서 속성 이름은 서로 달라야 한다.","choices":[{"verdict":"오답","why":"서로 다른 튜플이 같은 속성 값을 가질 수 있으므로(예: 여러 학생의 학년이 모두 3) 옳은 설명이다."},{"verdict":"정답","why":"한 릴레이션 안에서 속성은 이름으로 구별되므로 이름이 같은 속성이 있을 수 없다."},{"verdict":"오답","why":"한 릴레이션에 포함된 튜플은 모두 서로 달라야 하므로 옳은 설명이다."},{"verdict":"오답","why":"속성들 사이에는 순서가 없으므로 옳은 설명이다."}],"keywords":[{"term":"튜플(Tuple)","desc":"릴레이션의 행, 서로 중복될 수 없음"},{"term":"속성(Attribute)","desc":"릴레이션의 열, 이름이 유일하고 원자값을 가짐"},{"term":"도메인(Domain)","desc":"하나의 속성이 가질 수 있는 값의 범위"},{"term":"릴레이션 특징","desc":"튜플 유일, 튜플·속성 순서 없음, 속성 원자값"}],"memo":"같은 값은 가능, 같은 튜플과 같은 속성 이름은 불가능."}},{"id":"written-2022-3-57","no":57,"unit":"데이터베이스 구축","q":"시스템 카탈로그에 관한 설명 중 옳지 않은 것은?","choices":["시스템을 위한 정보를 담고 있는 시스템 데이터베이스이기 때문에 일반 사용자는 SQL을 이용해 그 내용을 검색해 볼 수 없다.","시스템 자체와 관련된 다양한 객체에 대한 정보를 담고 있는 시스템 데이터베이스이다.","기본 테이블, 뷰, 인덱스, 패키지, 접근 권한 등에 관한 정보를 저장한다.","데이터 사전이라고 부르기도 한다."],"ans":1,"exp":{"concept":"시스템 카탈로그(System Catalog)는 데이터베이스 안의 모든 객체(테이블, 뷰, 인덱스, 사용자, 권한 등)에 대한 정보를 담은 시스템 데이터베이스로, 데이터 사전이라고도 한다. 일반 사용자도 SQL로 내용을 검색할 수 있지만, INSERT, UPDATE, DELETE로 직접 수정할 수는 없고 DBMS가 자동으로 갱신한다.","choices":[{"verdict":"정답","why":"일반 사용자도 SQL로 시스템 카탈로그의 내용을 검색할 수 있다. 직접 갱신만 할 수 없을 뿐이다."},{"verdict":"오답","why":"시스템 자체와 관련된 다양한 객체 정보를 담은 시스템 데이터베이스이므로 옳은 설명이다."},{"verdict":"오답","why":"기본 테이블, 뷰, 인덱스, 패키지, 접근 권한 등에 관한 정보를 저장하므로 옳은 설명이다."},{"verdict":"오답","why":"시스템 카탈로그는 데이터 사전(Data Dictionary)이라고도 부르므로 옳은 설명이다."}],"keywords":[{"term":"시스템 카탈로그(System Catalog)","desc":"DB 객체 정보를 담은 시스템 데이터베이스"},{"term":"데이터 사전(Data Dictionary)","desc":"시스템 카탈로그의 다른 이름"},{"term":"메타데이터(Metadata)","desc":"데이터에 대한 데이터, 카탈로그에 저장되는 정보"},{"term":"데이터 디렉터리(Data Directory)","desc":"데이터 사전에 접근하는 데 필요한 정보를 관리, 시스템만 접근"}],"memo":"카탈로그는 '조회는 누구나, 수정은 DBMS만'."}},{"id":"written-2022-3-58","no":58,"unit":"데이터베이스 구축","q":"정보시스템과 관련하여 다음 설명에 해당하는 것은 무엇인가?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>각 시스템 간에 공유 디스크를 중심으로 클러스터링으로 엮어 다수의 시스템을 동시에 연결하는 것이 가능하다.</li><li>조직이나 기업의 기간 업무 서버 안정성을 높이고자 사용될 수 있다.</li><li>여러 가지 방식으로 구현되는데, 2개의 서버를 연결하여 2개의 시스템이 각각 업무를 수행하도록 구현하는 방식이 널리 사용된다.</li></ul></div>","choices":["루팅(Rooting)","스턱스넷(Stuxnet)","고가용성 솔루션(HACMP)","점대점 연결 방식(Point-to-Point Mode)"],"ans":3,"exp":{"concept":"고가용성(HA, High Availability) 솔루션은 서버에 장애가 나도 서비스가 멈추지 않도록 여러 시스템을 묶어 두는 기술이다. HACMP(High Availability Cluster Multi-Processing)는 공유 디스크를 중심으로 여러 서버를 클러스터로 연결해, 한 서버에 장애가 생기면 다른 서버가 업무를 이어받게 한다.","choices":[{"verdict":"오답","why":"루팅(Rooting)은 안드로이드 기기에서 최고 관리자(root) 권한을 얻는 것이다."},{"verdict":"오답","why":"스턱스넷(Stuxnet)은 산업 제어 시스템(SCADA)을 공격하는 웜 형태의 악성코드다."},{"verdict":"정답","why":"공유 디스크 중심의 클러스터링으로 여러 시스템을 연결해 기간 업무 서버의 안정성을 높이는 것은 고가용성 솔루션(HACMP)이다."},{"verdict":"오답","why":"점대점 연결 방식(Point-to-Point)은 두 지점을 1:1로 직접 연결하는 방식으로, 공유 디스크 클러스터링이 아니다."}],"keywords":[{"term":"HACMP(High Availability Cluster Multi-Processing)","desc":"공유 디스크 기반 클러스터링 고가용성 솔루션"},{"term":"고가용성(High Availability)","desc":"장애가 나도 서비스를 계속 제공하는 성질"},{"term":"클러스터링(Clustering)","desc":"여러 서버를 하나처럼 묶어 운영"},{"term":"페일오버(Failover)","desc":"장애 시 대기 시스템이 업무를 이어받는 것"}],"memo":"공유 디스크 + 클러스터링 + 안정성이 보이면 고가용성(HACMP)."}},{"id":"written-2022-3-59","no":59,"unit":"데이터베이스 구축","q":"정규화에 관한 설명 중 옳지 않은 것은?","choices":["릴레이션에 속한 모든 도메인이 원자값만으로 구성된 정규형은 제1정규형이다.","정규형에는 제1정규형, 제2정규형, 제3정규형, BCNF형, 제4정규형 등이 있다.","제1정규형이 제2정규형이 되려면 기본키가 아닌 모든 속성이 기본키에 대해 완전 함수적 종속을 만족해야 한다.","결정자가 모두 후보키인 정규형은 제3정규형이다."],"ans":4,"exp":{"concept":"정규화는 이상 현상을 없애기 위해 릴레이션을 나누는 과정이다. 1NF는 모든 속성이 원자값, 2NF는 부분 함수 종속 제거(완전 함수 종속), 3NF는 이행 함수 종속 제거, BCNF는 결정자가 모두 후보키인 상태, 4NF는 다치 종속 제거, 5NF는 조인 종속 제거다.","choices":[{"verdict":"오답","why":"모든 도메인이 원자값으로만 이루어진 정규형은 제1정규형이므로 옳은 설명이다."},{"verdict":"오답","why":"정규형에는 1NF, 2NF, 3NF, BCNF, 4NF, 5NF 등이 있으므로 옳은 설명이다."},{"verdict":"오답","why":"1NF에서 부분 함수 종속을 없애 기본키가 아닌 모든 속성이 기본키에 완전 함수 종속이 되면 2NF이므로 옳은 설명이다."},{"verdict":"정답","why":"결정자가 모두 후보키인 정규형은 제3정규형이 아니라 BCNF(보이스-코드 정규형)다."}],"keywords":[{"term":"제1정규형(1NF)","desc":"모든 속성 값이 원자값"},{"term":"제2정규형(2NF)","desc":"부분 함수 종속 제거"},{"term":"제3정규형(3NF)","desc":"이행 함수 종속 제거"},{"term":"BCNF","desc":"결정자이면서 후보키가 아닌 것 제거"},{"term":"제4·5정규형","desc":"다치 종속 제거 / 조인 종속 제거"}],"memo":"'도부이결다조'(도메인 원자값-부분 종속-이행 종속-결정자-다치 종속-조인 종속) 순서로 외운다."}},{"id":"written-2022-3-60","no":60,"unit":"데이터베이스 구축","q":"SQL 명령어를 DCL, DML, DDL로 나눌 때, 다음 중 성격이 다른 하나는?","choices":["DROP","SELECT","ALTER","CREATE"],"ans":2,"exp":{"concept":"SQL은 기능에 따라 DDL(정의어), DML(조작어), DCL(제어어)로 나뉜다. DDL은 테이블 등 객체 구조를 정의하는 CREATE, ALTER, DROP, TRUNCATE이고, DML은 데이터를 다루는 SELECT, INSERT, UPDATE, DELETE, DCL은 권한과 트랜잭션을 제어하는 GRANT, REVOKE, COMMIT, ROLLBACK이다.","choices":[{"verdict":"오답","why":"DROP은 객체를 제거하는 DDL이다."},{"verdict":"정답","why":"SELECT는 데이터를 검색하는 DML로, 나머지 DDL 명령과 성격이 다르다."},{"verdict":"오답","why":"ALTER는 객체 구조를 변경하는 DDL이다."},{"verdict":"오답","why":"CREATE는 객체를 생성하는 DDL이다."}],"keywords":[{"term":"DDL(Data Definition Language)","desc":"CREATE, ALTER, DROP, TRUNCATE"},{"term":"DML(Data Manipulation Language)","desc":"SELECT, INSERT, UPDATE, DELETE"},{"term":"DCL(Data Control Language)","desc":"GRANT, REVOKE, COMMIT, ROLLBACK"}],"memo":"구조를 건드리면 DDL, 데이터를 건드리면 DML, 권한을 건드리면 DCL."}},{"id":"written-2022-3-61","no":61,"unit":"프로그래밍 언어 활용","q":"TCP/IP에서 논리주소를 물리주소로 변환해 주는 프로토콜은 무엇인가?","choices":["TCP","FTP","IP","ARP"],"ans":4,"exp":{"concept":"인터넷에서 통신하려면 논리 주소(IP 주소)와 물리 주소(MAC 주소)가 모두 필요하다. ARP(Address Resolution Protocol)는 IP 주소를 MAC 주소로 바꿔 주고, 반대로 RARP는 MAC 주소를 IP 주소로 바꿔 준다.","choices":[{"verdict":"오답","why":"TCP는 전송 계층에서 신뢰성 있는 연결형 데이터 전송을 담당하는 프로토콜이다."},{"verdict":"오답","why":"FTP는 파일을 주고받기 위한 응용 계층 프로토콜이다."},{"verdict":"오답","why":"IP는 패킷을 목적지까지 전달(라우팅)하는 네트워크 계층 프로토콜로, 주소 변환을 하지 않는다."},{"verdict":"정답","why":"ARP는 논리 주소(IP)를 물리 주소(MAC)로 변환하는 프로토콜이다."}],"keywords":[{"term":"ARP(Address Resolution Protocol)","desc":"IP 주소 → MAC 주소 변환"},{"term":"RARP(Reverse ARP)","desc":"MAC 주소 → IP 주소 변환"},{"term":"IP 주소","desc":"네트워크 계층의 논리 주소"},{"term":"MAC 주소","desc":"데이터 링크 계층의 물리 주소"}],"memo":"ARP는 IP로 MAC을 찾고, 앞에 R(Reverse)이 붙으면 반대 방향이다."}},{"id":"written-2022-3-62","no":62,"unit":"프로그래밍 언어 활용","q":"다음 중 HRN에 관한 설명으로 옳지 않은 것은?","choices":["대기 시간이 긴 프로세스는 우선순위가 높아진다.","SJF 기법을 보완하기 위해 고안된 스케쥴링 방법이다.","대기시간과 서비스시간을 이용하는 기법이다.","우선순위 계산식의 값이 낮을수록 우선순위가 높아진다."],"ans":4,"exp":{"concept":"HRN(Highest Response-ratio Next)은 SJF 스케줄링에서 실행 시간이 긴 작업이 계속 밀리는 문제를 보완한 비선점 기법이다. 우선순위 = (대기 시간 + 서비스 시간) / 서비스 시간으로 계산하며, 이 값이 클수록 우선순위가 높다. 오래 기다릴수록 값이 커지므로 긴 작업도 결국 실행된다.","choices":[{"verdict":"오답","why":"대기 시간이 길수록 분자가 커져 계산 값이 커지므로 우선순위가 높아진다. 옳은 설명이다."},{"verdict":"오답","why":"HRN은 SJF에서 긴 작업이 무한정 기다리는 문제를 보완하려고 고안되었으므로 옳은 설명이다."},{"verdict":"오답","why":"우선순위 계산식에 대기 시간과 서비스 시간을 모두 사용하므로 옳은 설명이다."},{"verdict":"정답","why":"HRN은 계산식의 값이 높을수록 우선순위가 높다. 값이 낮을수록 우선순위가 높다는 것은 틀렸다."}],"keywords":[{"term":"HRN(Highest Response-ratio Next)","desc":"응답률이 가장 높은 작업을 먼저 실행하는 비선점 스케줄링"},{"term":"HRN 우선순위","desc":"(대기 시간 + 서비스 시간) / 서비스 시간"},{"term":"SJF(Shortest Job First)","desc":"실행 시간이 가장 짧은 작업을 먼저 실행"},{"term":"기아 현상(Starvation)","desc":"우선순위가 낮아 계속 실행되지 못하는 현상"}],"memo":"이름부터 Highest, 즉 값이 가장 높은 것이 먼저다."}},{"id":"written-2022-3-63","no":63,"unit":"프로그래밍 언어 활용","q":"다음 중 교착상태가 발생할 수 있는 조건에 해당하지 않는 것은?","choices":["Hold and wait","Linear wait","Non-preemption","Mutual exclusion"],"ans":2,"exp":{"concept":"교착 상태(Deadlock)는 둘 이상의 프로세스가 서로가 가진 자원을 기다리며 영원히 멈춰 있는 상태다. 상호 배제, 점유와 대기, 비선점, 환형 대기의 네 조건이 모두 동시에 성립할 때 발생할 수 있다.","choices":[{"verdict":"오답","why":"점유와 대기(Hold and Wait)는 자원을 가진 채 다른 자원을 기다리는 것으로 교착 상태 발생 조건이다."},{"verdict":"정답","why":"교착 상태의 조건은 환형 대기(Circular Wait)이며, 선형 대기(Linear Wait)는 조건이 아니다."},{"verdict":"오답","why":"비선점(Non-preemption)은 다른 프로세스의 자원을 강제로 빼앗을 수 없는 것으로 교착 상태 발생 조건이다."},{"verdict":"오답","why":"상호 배제(Mutual Exclusion)는 한 자원을 한 번에 한 프로세스만 쓸 수 있는 것으로 교착 상태 발생 조건이다."}],"keywords":[{"term":"상호 배제(Mutual Exclusion)","desc":"자원을 한 번에 하나의 프로세스만 사용"},{"term":"점유와 대기(Hold and Wait)","desc":"자원을 가진 채 다른 자원을 기다림"},{"term":"비선점(Non-preemption)","desc":"할당된 자원을 강제로 빼앗을 수 없음"},{"term":"환형 대기(Circular Wait)","desc":"프로세스들이 원형으로 서로의 자원을 기다림"}],"memo":"교착 4조건 '상점비환'. 서로 꼬리를 무는 것은 선(Linear)이 아니라 원(Circular)이다."}},{"id":"written-2022-3-64","no":64,"unit":"프로그래밍 언어 활용","q":"아래 파이썬 코드에 ‘53t44’를 입력하면 출력되는 결과는?<pre class=\"qcode\"><code class=\"language-python\">a, b = map(int, input().split(\"t\"));\nprint(a, b)</code></pre>","choices":["53 t 44","53t44","53 44","53, 44"],"ans":3,"exp":{"concept":"input()은 입력 한 줄을 문자열로 받고, split(\"t\")는 문자 t를 기준으로 문자열을 나눠 리스트로 만든다. map(int, …)은 각 조각을 정수로 바꾸고, a, b에 차례로 대입된다. print(a, b)는 여러 값을 기본적으로 공백 하나로 구분해 출력한다.","choices":[{"verdict":"오답","why":"t는 split의 구분자로 쓰여 사라지므로 출력에 t가 나오지 않는다."},{"verdict":"오답","why":"입력 문자열을 그대로 출력하는 것이 아니라 t로 나눈 두 정수를 출력한다."},{"verdict":"정답","why":"'53t44'.split('t')는 ['53', '44']가 되고, 정수 53과 44가 a, b에 들어가 print(a, b)는 공백으로 구분해 53 44를 출력한다."},{"verdict":"오답","why":"print 함수는 여러 값을 공백으로 구분하므로 쉼표가 출력되지 않는다."}],"keywords":[{"term":"split(구분자)","desc":"문자열을 구분자 기준으로 나눠 리스트로 반환"},{"term":"map(함수, 반복 가능 객체)","desc":"각 요소에 함수를 적용"},{"term":"print(a, b)","desc":"값 사이를 공백(sep=' ')으로 구분해 출력"},{"term":"input()","desc":"한 줄을 문자열로 입력받음"}],"memo":"print의 기본 구분자(sep)는 공백 한 칸이다. 쉼표로 넘겨도 쉼표는 출력되지 않는다."}},{"id":"written-2022-3-65","no":65,"unit":"프로그래밍 언어 활용","q":"OSI 7계층 가운데 네트워크 계층에 관한 설명으로 옳지 않은 것은?","choices":["패킷을 발신지에서 최종 목적지까지 전달할 책임을 진다.","패킷에 발신지 및 목적지의 논리 주소를 추가한다.","한 노드에서 다른 노드로 프레임을 전송할 책임을 진다.","라우터 또는 교환기는 패킷 전달을 위한 경로를 지정하거나 교환 기능을 제공한다."],"ans":3,"exp":{"concept":"OSI 7계층에서 네트워크 계층(3계층)은 패킷이 발신지에서 최종 목적지까지 가는 경로를 정하고(라우팅) 전달한다. IP 주소 같은 논리 주소를 쓰며 라우터가 대표 장비다. 바로 옆 노드까지 프레임을 전달하는 것은 데이터 링크 계층(2계층)의 일이다.","choices":[{"verdict":"오답","why":"패킷을 발신지에서 최종 목적지까지 전달하는 것은 네트워크 계층의 책임이므로 옳은 설명이다."},{"verdict":"오답","why":"패킷에 발신지와 목적지의 논리 주소(IP 주소)를 붙이는 것은 네트워크 계층의 기능이므로 옳은 설명이다."},{"verdict":"정답","why":"한 노드에서 인접한 다른 노드로 프레임을 전송하는 것은 데이터 링크 계층의 책임이다."},{"verdict":"오답","why":"라우터나 교환기가 경로 지정과 교환 기능을 제공하는 것은 네트워크 계층의 특징이므로 옳은 설명이다."}],"keywords":[{"term":"네트워크 계층(3계층)","desc":"패킷, 논리 주소(IP), 라우팅, 라우터"},{"term":"데이터 링크 계층(2계층)","desc":"프레임, 물리 주소(MAC), 인접 노드 간 전송, 스위치·브리지"},{"term":"전송 계층(4계층)","desc":"세그먼트, 종단 간 신뢰성 있는 전송, TCP·UDP"}],"memo":"단위로 구분하자. 프레임은 2계층, 패킷은 3계층, 세그먼트는 4계층."}},{"id":"written-2022-3-66","no":66,"unit":"프로그래밍 언어 활용","q":"다음 중 IP 버전에 관한 설명으로 옳지 않은 것은?","choices":["IPv4는 각 부분이 옥텟으로 구성되며, 총 32비트로 이루어진다.","IPv4는 네트워크 부분의 길이에 따라 A 클래스부터 E 클래스까지 총 5단계로 구성된다.","IPv6는 IPv4에 비해 자료 전송 속도가 느린 편이다.","IPv6는 각 부분을 콜론으로 구분하여 표기한다."],"ans":3,"exp":{"concept":"IPv4는 8비트씩 네 부분(옥텟)으로 이루어진 32비트 주소이고, A~E 다섯 클래스로 나뉜다. IPv6는 주소 부족 문제를 해결하려고 만든 128비트 주소로, 16비트씩 여덟 부분을 콜론(:)으로 구분해 16진수로 표기한다. IPv6는 헤더 구조를 단순화해 처리 효율과 전송 속도가 개선되었다.","choices":[{"verdict":"오답","why":"IPv4는 8비트 옥텟 4개, 총 32비트로 이루어지므로 옳은 설명이다."},{"verdict":"오답","why":"IPv4는 네트워크 부분의 길이에 따라 A, B, C, D, E 클래스 다섯 가지로 나뉘므로 옳은 설명이다."},{"verdict":"정답","why":"IPv6는 헤더가 단순화되어 IPv4보다 처리가 효율적이고 전송 속도가 빠르다. 느리다는 것은 틀렸다."},{"verdict":"오답","why":"IPv6는 16비트씩 8부분을 콜론(:)으로 구분하므로 옳은 설명이다."}],"keywords":[{"term":"IPv4","desc":"32비트, 8비트씩 4부분, 점(.)으로 구분, 10진수"},{"term":"IPv6","desc":"128비트, 16비트씩 8부분, 콜론(:)으로 구분, 16진수"},{"term":"IPv6 주소 체계","desc":"유니캐스트, 멀티캐스트, 애니캐스트"},{"term":"옥텟(Octet)","desc":"8비트 묶음"}],"memo":"IPv6는 IPv4의 단점을 개선한 버전이므로 '느리다', '보안이 약하다'는 틀린 말이다."}},{"id":"written-2022-3-67","no":67,"unit":"프로그래밍 언어 활용","q":"OSI 7계층 가운데 아래 설명에 해당하는 계층은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>두 응용 프로세스 사이의 통신에 대한 제어 구조를 제공한다.</li><li>연결의 생성·관리·종료를 위하여 토큰을 사용한다.</li></ul></div>","choices":["세션 계층","데이터링크 계층","네트워크 계층","표현 계층"],"ans":1,"exp":{"concept":"세션 계층(5계층)은 두 응용 프로세스 사이의 대화(세션)를 만들고 관리하고 끝내는 역할을 한다. 대화 제어와 동기점을 이용한 동기화를 담당하며, 토큰을 이용해 누가 데이터를 보낼 차례인지 관리한다.","choices":[{"verdict":"정답","why":"응용 프로세스 간 통신의 제어 구조를 제공하고 토큰으로 연결의 생성·관리·종료를 다루는 것은 세션 계층이다."},{"verdict":"오답","why":"데이터 링크 계층은 인접 노드 사이의 프레임 전송, 흐름 제어, 오류 제어를 담당한다."},{"verdict":"오답","why":"네트워크 계층은 패킷의 경로 설정(라우팅)과 논리 주소 지정을 담당한다."},{"verdict":"오답","why":"표현 계층은 데이터의 형식 변환, 암호화, 압축을 담당한다."}],"keywords":[{"term":"세션 계층(5계층)","desc":"대화 제어, 동기화(동기점), 토큰 관리"},{"term":"표현 계층(6계층)","desc":"코드 변환, 암호화, 압축"},{"term":"동기점(Synchronization Point)","desc":"오류 시 복구를 위해 대화 중간에 두는 기준점"},{"term":"OSI 7계층","desc":"물리-데이터 링크-네트워크-전송-세션-표현-응용"}],"memo":"세션은 '대화'다. 대화 시작·관리·종료, 말할 차례(토큰)를 정하는 계층."}},{"id":"written-2022-3-68","no":68,"unit":"프로그래밍 언어 활용","q":"다음 중 프로세스 상태의 종류에 해당하지 않는 것은?","choices":["Exit","Running","Ready","Request"],"ans":4,"exp":{"concept":"프로세스는 실행 중인 프로그램으로, 생성부터 종료까지 여러 상태를 거친다. 주요 상태는 생성(New/제출), 준비(Ready), 실행(Running), 대기(Waiting/Blocked), 종료(Exit/Terminated)다.","choices":[{"verdict":"오답","why":"종료(Exit)는 프로세스 실행이 끝나 자원을 반납하는 상태로 프로세스 상태에 해당한다."},{"verdict":"오답","why":"실행(Running)은 CPU를 할당받아 명령을 수행 중인 상태로 프로세스 상태에 해당한다."},{"verdict":"오답","why":"준비(Ready)는 CPU 할당을 기다리는 상태로 프로세스 상태에 해당한다."},{"verdict":"정답","why":"Request는 프로세스 상태의 이름이 아니다. 입출력 등을 기다리는 상태는 대기(Waiting, Blocked)라고 한다."}],"keywords":[{"term":"준비(Ready)","desc":"CPU 할당을 기다리는 상태"},{"term":"실행(Running)","desc":"CPU를 할당받아 실행 중인 상태"},{"term":"대기(Waiting/Blocked)","desc":"입출력 등 사건을 기다리는 상태"},{"term":"디스패치(Dispatch)","desc":"준비 상태의 프로세스에 CPU를 할당해 실행 상태로 바꾸는 것"},{"term":"종료(Exit/Terminated)","desc":"실행을 마친 상태"}],"memo":"프로세스 상태 흐름: 생성 → 준비 → 실행 → (대기 → 준비) → 종료. Request는 없다."}},{"id":"written-2022-3-69","no":69,"unit":"프로그래밍 언어 활용","q":"다음 C언어 프로그램에서 밑줄 친 부분과 같은 의미를 갖는 것은 무엇인가?<pre class=\"qcode\"><code>#include &lt;stdio.h&gt;\nmain() {\n    int a, b;\n    for (a = 0; a &lt; 2; a++)\n        for (b = 0; b &lt; 2; b++)\n            printf(\"%d\", <u>!a &amp;&amp; !b</u>);\n}</code></pre>","choices":["!a || !b","a || b","!(a || b)","a &amp;&amp; b"],"ans":3,"exp":{"concept":"드모르간의 법칙에 따라 !a && !b는 !(a || b)와 같다. 'a도 아니고 b도 아니다'는 'a 또는 b인 경우가 아니다'와 같은 뜻이기 때문이다. C 언어에서 !는 0을 1로, 0이 아닌 값을 0으로 바꾼다. 문제에서 밑줄 친 부분은 printf 안의 !a && !b이며, a와 b가 모두 0일 때만 1이 된다.","choices":[{"verdict":"오답","why":"!a || !b는 a와 b 중 하나라도 0이면 1이므로 (0,1), (1,0)에서도 1이 되어 다르다. 이것은 !(a && b)와 같다."},{"verdict":"오답","why":"a || b는 a, b 중 하나라도 1이면 1이므로 !a && !b와 정반대 값이 된다."},{"verdict":"정답","why":"!(a || b)는 a, b가 모두 0일 때만 1이므로 !a && !b와 모든 경우에 값이 같다. 두 식 모두 (0,0), (0,1), (1,0), (1,1) 순서로 1, 0, 0, 0이 되어 프로그램은 1000을 출력한다."},{"verdict":"오답","why":"a && b는 a, b가 모두 1일 때만 1이므로 (1,1)에서만 1이 되어 다르다."}],"keywords":[{"term":"드모르간의 법칙(De Morgan's Law)","desc":"!(A || B) = !A && !B, !(A && B) = !A || !B"},{"term":"논리 부정 !","desc":"0이면 1, 0이 아니면 0"},{"term":"&&","desc":"둘 다 참일 때 1"},{"term":"||","desc":"하나라도 참이면 1"}],"memo":"괄호 밖으로 !를 꺼내면 &&와 ||가 서로 바뀐다."}},{"id":"written-2022-3-70","no":70,"unit":"프로그래밍 언어 활용","q":"다음 중 프로세스에 관한 설명으로 틀린 것은?","choices":["프로세스는 스레드 내의 작업단위를 뜻하며, 경량 스레드라고도 한다.","프로세서가 할당되는 실체이며, 디스패치가 가능한 단위이다.","PCB를 가지며, PCB에는 프로세스의 현재상태와 고유식별자가 들어 있다.","프로세스는 비동기적 행위를 일으키는 주체가 된다."],"ans":1,"exp":{"concept":"프로세스는 실행 중인 프로그램으로, CPU가 할당되는 단위이며 PCB(프로세스 제어 블록)를 가진다. 스레드(Thread)는 프로세스 안에서 실행되는 더 작은 작업 단위로, 경량 프로세스(LWP, Light Weight Process)라고도 한다. 즉 스레드가 프로세스 안에 있는 것이지 그 반대가 아니다.","choices":[{"verdict":"정답","why":"프로세스 내의 작업 단위이며 경량 프로세스라고 불리는 것은 스레드다. 프로세스가 스레드 안의 작업 단위라는 설명은 틀렸다."},{"verdict":"오답","why":"프로세스는 프로세서(CPU)가 할당되는 실체이며 디스패치가 가능한 단위이므로 옳은 설명이다."},{"verdict":"오답","why":"프로세스는 PCB를 가지며, PCB에는 현재 상태, 고유 식별자(PID), 우선순위 등이 들어 있으므로 옳은 설명이다."},{"verdict":"오답","why":"프로세스는 비동기적 행위를 일으키는 주체이므로 옳은 설명이다."}],"keywords":[{"term":"프로세스(Process)","desc":"실행 중인 프로그램, CPU가 할당되는 단위"},{"term":"스레드(Thread)","desc":"프로세스 내의 작업 단위, 경량 프로세스"},{"term":"PCB(Process Control Block)","desc":"프로세스 상태, PID, 우선순위 등을 저장하는 블록"},{"term":"디스패치(Dispatch)","desc":"준비 상태 프로세스에 CPU를 할당"}],"memo":"프로세스가 집이라면 스레드는 그 집 안에서 일하는 사람들이다."}},{"id":"written-2022-3-71","no":71,"unit":"프로그래밍 언어 활용","q":"다음 설명이 가리키는 것은 무엇인가?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>프로세스를 처리하는 도중 참조할 페이지가 주기억장치에 없어서, 페이지 교체에 걸리는 시간이 프로세스 처리시간보다 더 많아지는 현상</p></div>","choices":["페이지부재(Page Fault)","스레드(Thread)","스래싱(Thrasing)","워킹셋(Working Set)"],"ans":3,"exp":{"concept":"스래싱(Thrashing)은 프로세스 실행 중 필요한 페이지가 주기억장치에 없어 페이지 부재가 너무 자주 일어나, 실제 일보다 페이지 교체에 시간을 더 많이 쓰는 현상이다. 다중 프로그래밍 정도가 너무 높으면 발생하며, 워킹 셋이나 페이지 부재 빈도(PFF) 방식으로 막는다.","choices":[{"verdict":"오답","why":"페이지 부재(Page Fault)는 참조할 페이지가 주기억장치에 없는 사건 하나를 가리키며, 교체 시간이 처리 시간보다 많아지는 현상 자체는 아니다."},{"verdict":"오답","why":"스레드(Thread)는 프로세스 안의 작업 단위로 페이지 교체와 관련이 없다."},{"verdict":"정답","why":"페이지 교체에 걸리는 시간이 프로세스 처리 시간보다 많아지는 현상이 스래싱이다."},{"verdict":"오답","why":"워킹 셋(Working Set)은 프로세스가 일정 시간 동안 자주 참조하는 페이지들의 집합으로, 스래싱을 막는 데 쓰인다."}],"keywords":[{"term":"스래싱(Thrashing)","desc":"페이지 교체 시간이 실행 시간보다 많아지는 현상"},{"term":"페이지 부재(Page Fault)","desc":"참조할 페이지가 주기억장치에 없는 상황"},{"term":"워킹 셋(Working Set)","desc":"일정 시간 자주 참조하는 페이지 집합"},{"term":"PFF(Page Fault Frequency)","desc":"페이지 부재 빈도로 프레임 수를 조절"}],"memo":"페이지 부재가 '사건'이라면 스래싱은 그 사건이 폭주한 '현상'이다."}},{"id":"written-2022-3-72","no":72,"unit":"프로그래밍 언어 활용","q":"C언어 라이브러리 가운데 stdlib.h에 관한 설명으로 옳은 것은?","choices":["표준 입출력을 위한 라이브러리이다.","문자열 처리 함수인 strlen()이 포함되어 있다.","문자열을 수치 데이터로 변환하는 함수와 동적 메모리 할당 및 해제 함수 등을 포함한다.","삼각 함수, 제곱근, 지수 등의 수학 함수를 내장하고 있다."],"ans":3,"exp":{"concept":"C 언어의 표준 헤더 파일은 기능별로 나뉜다. stdlib.h는 문자열을 숫자로 바꾸는 atoi, atof, 동적 메모리를 다루는 malloc, free, 난수 rand, 프로그램 종료 exit 등 여러 유틸리티 함수를 담고 있다.","choices":[{"verdict":"오답","why":"표준 입출력 라이브러리는 printf, scanf 등을 담은 stdio.h다."},{"verdict":"오답","why":"strlen() 같은 문자열 처리 함수는 string.h에 들어 있다."},{"verdict":"정답","why":"stdlib.h에는 문자열을 수치로 바꾸는 atoi 등과 동적 메모리 할당·해제 함수인 malloc, free 등이 포함되어 있다."},{"verdict":"오답","why":"삼각 함수, 제곱근, 지수 등의 수학 함수는 math.h에 들어 있다."}],"keywords":[{"term":"stdio.h","desc":"표준 입출력: printf, scanf, getchar"},{"term":"stdlib.h","desc":"자료형 변환·메모리·난수: atoi, malloc, free, rand, exit"},{"term":"string.h","desc":"문자열 처리: strlen, strcpy, strcmp, strcat"},{"term":"math.h","desc":"수학 함수: sqrt, pow, sin, fabs"}],"memo":"std(표준) + lib(라이브러리) = 잡다한 표준 유틸리티 모음. malloc과 atoi가 대표다."}},{"id":"written-2022-3-73","no":73,"unit":"프로그래밍 언어 활용","q":"아래 C언어 프로그램의 실행 결과로 옳은 것은?<pre class=\"qcode\"><code class=\"language-c\">#include &lt;stdio.h&gt;\nmain() {\n    int a = 3, b = 4, c = 5;\n    int r1, r2, r3;\n    r1 = a &lt; 4 &amp;&amp; b &lt;= 4;\n    r2 = a &gt; 3 || b &lt;= 5;\n    r3 = !c;\n    printf(\"%d\", r1 - r2 + r3);\n}</code></pre>","choices":["0","1","2","3"],"ans":1,"exp":{"concept":"C에서 관계 연산(<, <= 등)과 논리 연산(&&, ||)의 결과는 참이면 1, 거짓이면 0이다. !c는 c가 0이 아니면 0이 된다. r1, r2, r3를 각각 구해 r1 - r2 + r3를 계산하면 된다.","choices":[{"verdict":"정답","why":"r1 = (3<4) && (4<=4) = 1 && 1 = 1, r2 = (3>3) || (4<=5) = 0 || 1 = 1, r3 = !5 = 0 이므로 1 - 1 + 0 = 0을 출력한다."},{"verdict":"오답","why":"1이 나오려면 r2가 0이어야 하지만, b <= 5가 참이므로 r2는 1이다."},{"verdict":"오답","why":"2가 나오려면 r3가 1이어야 하지만, c는 5로 0이 아니므로 !c는 0이다."},{"verdict":"오답","why":"r1, r2, r3는 각각 0 또는 1이므로 r1 - r2 + r3는 3이 될 수 없다."}],"keywords":[{"term":"관계 연산 결과","desc":"참이면 1, 거짓이면 0"},{"term":"&& (논리곱)","desc":"둘 다 참일 때만 1"},{"term":"|| (논리합)","desc":"하나라도 참이면 1"},{"term":"! (논리 부정)","desc":"0이 아닌 값은 0으로, 0은 1로"}],"memo":"a > 3에서 3 > 3은 거짓이다. 같을 때를 포함하는지(>=인지 >인지) 꼭 확인하자."}},{"id":"written-2022-3-74","no":74,"unit":"프로그래밍 언어 활용","q":"JAVA에서 힙(Heap)에는 남아있지만 변수가 가지고 있던 참조값을 잃었거나 변수 자체가 사라져 더 이상 사용되지 않는 객체를 제거하는 역할을 담당하는 모듈은?","choices":["Memory Collector","Garbage Collector","Heap Collector","Variable Collector"],"ans":2,"exp":{"concept":"가비지 컬렉터(Garbage Collector)는 자바 가상 머신(JVM)이 힙(Heap) 메모리에서 더 이상 아무 변수도 참조하지 않는 객체를 찾아 자동으로 지워 주는 기능이다. C처럼 프로그래머가 직접 free를 호출하지 않아도 메모리가 회수된다.","choices":[{"verdict":"오답","why":"Memory Collector는 자바의 메모리 관리 모듈 이름이 아니다."},{"verdict":"정답","why":"참조를 잃은 객체를 힙에서 자동으로 제거하는 모듈은 가비지 컬렉터(Garbage Collector)다."},{"verdict":"오답","why":"Heap Collector는 자바의 메모리 관리 모듈 이름이 아니다."},{"verdict":"오답","why":"Variable Collector는 자바의 메모리 관리 모듈 이름이 아니다."}],"keywords":[{"term":"가비지 컬렉터(Garbage Collector)","desc":"참조되지 않는 객체를 자동으로 회수"},{"term":"힙(Heap)","desc":"new로 생성한 객체가 저장되는 메모리 영역"},{"term":"가비지(Garbage)","desc":"참조를 잃어 더 이상 쓰이지 않는 객체"},{"term":"JVM(Java Virtual Machine)","desc":"자바 바이트코드를 실행하는 가상 머신"}],"memo":"쓰레기(Garbage)를 모아(Collect) 치운다."}},{"id":"written-2022-3-75","no":75,"unit":"프로그래밍 언어 활용","q":"C언어의 malloc() 함수에 관한 설명 중 틀린 것은?","choices":["메모리 할당이 불가능한 경우 NULL을 반환한다.","사용자가 입력한 bit만큼의 메모리를 할당한다.","필요한 시점에 필요한 만큼 메모리를 동적으로 할당한다.","할당된 메모리는 free 명령어로 해제한다."],"ans":2,"exp":{"concept":"malloc()은 프로그램 실행 중에 필요한 만큼 힙 메모리를 동적으로 할당하는 C 함수다. 인수로 할당할 크기를 바이트(byte) 단위로 받고, 할당된 공간의 시작 주소를 반환한다. 할당에 실패하면 NULL을 반환하며, 다 쓴 메모리는 free()로 해제한다.","choices":[{"verdict":"오답","why":"메모리를 할당할 수 없으면 NULL을 반환하므로 옳은 설명이다."},{"verdict":"정답","why":"malloc()은 비트(bit)가 아니라 바이트(byte) 단위로 크기를 받아 메모리를 할당한다."},{"verdict":"오답","why":"필요한 시점에 필요한 크기만큼 동적으로 할당하는 함수이므로 옳은 설명이다."},{"verdict":"오답","why":"할당된 메모리는 free()로 해제하므로 옳은 설명이다."}],"keywords":[{"term":"malloc(크기)","desc":"바이트 단위로 힙 메모리 동적 할당, 실패 시 NULL"},{"term":"free(포인터)","desc":"동적으로 할당한 메모리 해제"},{"term":"sizeof","desc":"자료형의 크기를 바이트로 구하는 연산자"},{"term":"메모리 누수(Memory Leak)","desc":"할당한 메모리를 해제하지 않아 낭비되는 현상"}],"memo":"malloc(sizeof(int) * 10)처럼 쓰듯이, sizeof가 바이트를 돌려주니 malloc도 바이트 단위다."}},{"id":"written-2022-3-76","no":76,"unit":"프로그래밍 언어 활용","q":"주기억장치가 3개의 보관구조를 가지고 있고, 페이지 참조가 다음 순서로 일어날 때 FIFO 페이지 교체 알고리즘을 적용하면 마지막 페이지 값으로 옳은 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>페이지 순서 : 1, 2, 3, 2, 4, 2, 3, 1, 3</p></div>","choices":["4, 2, 3","4, 1, 3","1, 2, 3","1, 4, 2"],"ans":2,"exp":{"concept":"FIFO(First In First Out) 페이지 교체는 주기억장치에 가장 먼저 들어온 페이지를 먼저 내보내는 방식이다. 프레임이 3개일 때 참조 순서대로 따라가며, 이미 있는 페이지는 그대로 두고 없는 페이지가 오면 가장 오래된 페이지 자리에 넣는다.","choices":[{"verdict":"오답","why":"4, 2, 3은 페이지 4가 들어온 직후의 상태다. 이후 페이지 1이 참조될 때 가장 오래된 2가 교체된다."},{"verdict":"정답","why":"1, 2, 3을 차례로 적재한 뒤 2는 적중, 4는 가장 오래된 1을 교체해 4, 2, 3, 다시 2와 3은 적중, 1은 그다음 오래된 2를 교체해 4, 1, 3, 마지막 3은 적중이다. 최종 프레임은 4, 1, 3이다."},{"verdict":"오답","why":"1, 2, 3은 처음 세 페이지를 적재한 직후의 상태다."},{"verdict":"오답","why":"1, 4, 2는 FIFO 교체 과정 어디에서도 나오지 않는 상태다. 마지막 시점에 2는 이미 교체되어 없고 3이 남아 있다."}],"keywords":[{"term":"FIFO(First In First Out)","desc":"가장 먼저 들어온 페이지를 교체"},{"term":"LRU(Least Recently Used)","desc":"가장 오랫동안 사용하지 않은 페이지를 교체"},{"term":"LFU(Least Frequently Used)","desc":"사용 횟수가 가장 적은 페이지를 교체"},{"term":"페이지 부재(Page Fault)","desc":"참조한 페이지가 프레임에 없는 경우"}],"memo":"FIFO는 참조(적중)되어도 순서가 갱신되지 않는다. 적중 때 순서를 바꾸는 것은 LRU다."}},{"id":"written-2022-3-77","no":77,"unit":"프로그래밍 언어 활용","q":"UNIX에서 새로운 프로세스를 생성할 때 사용하는 명령어는?","choices":["ls","cat","chmod","fork"],"ans":4,"exp":{"concept":"유닉스에서 fork는 현재 프로세스를 복제해 새로운 자식 프로세스를 만드는 시스템 호출이다. 부모와 거의 같은 내용의 자식 프로세스가 생성되며, 이후 exec 계열로 다른 프로그램을 실행할 수 있다.","choices":[{"verdict":"오답","why":"ls는 디렉터리 안의 파일 목록을 보여 주는 명령이다."},{"verdict":"오답","why":"cat은 파일 내용을 화면에 출력하거나 파일을 이어 붙이는 명령이다."},{"verdict":"오답","why":"chmod는 파일이나 디렉터리의 접근 권한을 변경하는 명령이다."},{"verdict":"정답","why":"fork는 현재 프로세스를 복제해 새로운 프로세스를 생성한다."}],"keywords":[{"term":"fork","desc":"현재 프로세스를 복제해 자식 프로세스 생성"},{"term":"exec","desc":"현재 프로세스를 다른 프로그램으로 대체해 실행"},{"term":"chmod","desc":"파일 접근 권한 변경"},{"term":"chown","desc":"파일 소유자 변경"},{"term":"kill","desc":"프로세스에 신호를 보내 종료 등"}],"memo":"fork는 포크(갈래), 하나의 프로세스가 두 갈래로 나뉜다."}},{"id":"written-2022-3-78","no":78,"unit":"프로그래밍 언어 활용","q":"프레임워크(Framework)에 관한 설명 중 옳은 것은?","choices":["소프트웨어 아키텍처(Architecture)와 같은 개념이다.","모듈화(Modularity)가 불가능하다.","소프트웨어 구성에 필요한 기본 구조를 제공하여 재사용을 가능하게 해준다","소프트웨어 개발 시 구조가 잡혀 있으므로 확장이 불가능하다."],"ans":3,"exp":{"concept":"프레임워크(Framework)는 소프트웨어를 만들 때 공통으로 필요한 기본 구조와 기능을 미리 만들어 제공하는 반제품이다. 개발자는 정해진 틀 위에 필요한 부분만 채우면 되므로 재사용성이 높고 개발 시간이 줄어든다. 모듈화와 확장도 지원한다.","choices":[{"verdict":"오답","why":"소프트웨어 아키텍처는 시스템 전체 구조에 대한 설계이고, 프레임워크는 그 구조를 실제 코드로 구현해 제공하는 것으로 같은 개념이 아니다."},{"verdict":"오답","why":"프레임워크는 구성 요소를 모듈화해 제공하므로 모듈화가 가능하다."},{"verdict":"정답","why":"프레임워크는 소프트웨어 구성에 필요한 기본 구조를 제공해 재사용을 가능하게 한다."},{"verdict":"오답","why":"프레임워크는 정해진 확장 지점을 통해 기능을 확장할 수 있으므로 확장이 불가능하다는 것은 틀렸다."}],"keywords":[{"term":"프레임워크(Framework)","desc":"기본 구조와 공통 기능을 제공하는 반제품"},{"term":"프레임워크 특성","desc":"모듈화, 재사용성, 확장성, 제어의 역행"},{"term":"제어의 역행(IoC, Inversion of Control)","desc":"프로그램 흐름을 개발자 코드가 아닌 프레임워크가 제어"},{"term":"라이브러리(Library)","desc":"개발자가 필요할 때 호출해 쓰는 함수 모음"}],"memo":"프레임워크 특성 '모재확제'(모듈화-재사용성-확장성-제어의 역행)."}},{"id":"written-2022-3-79","no":79,"unit":"프로그래밍 언어 활용","q":"IEEE 802.3 LAN에서 쓰이는 전송 매체 접속 제어(MAC) 방식은 무엇인가?","choices":["Token Bus","Slotted Ring","CSMA/CD","Token Ring"],"ans":3,"exp":{"concept":"IEEE 802.3은 유선 이더넷(Ethernet) 표준이다. 이더넷은 CSMA/CD 방식으로 매체에 접근한다. 보내기 전에 회선이 비었는지 확인하고, 동시에 보내다 충돌이 나면 이를 감지해 잠시 기다린 뒤 다시 보낸다.","choices":[{"verdict":"오답","why":"토큰 버스(Token Bus)는 버스형 네트워크에서 토큰을 돌려 전송 권한을 주는 방식으로 IEEE 802.4 표준이다."},{"verdict":"오답","why":"슬롯 링(Slotted Ring)은 링형 네트워크에서 일정한 슬롯을 돌려 전송하는 방식으로 IEEE 802.3의 방식이 아니다."},{"verdict":"정답","why":"IEEE 802.3(이더넷)의 매체 접근 제어 방식은 CSMA/CD다."},{"verdict":"오답","why":"토큰 링(Token Ring)은 링형 네트워크에서 토큰을 돌려 전송 권한을 주는 방식으로 IEEE 802.5 표준이다."}],"keywords":[{"term":"IEEE 802.3","desc":"이더넷, CSMA/CD"},{"term":"IEEE 802.4","desc":"토큰 버스"},{"term":"IEEE 802.5","desc":"토큰 링"},{"term":"IEEE 802.11","desc":"무선 LAN, CSMA/CA"},{"term":"CSMA/CD","desc":"반송파 감지 다중 접근 / 충돌 탐지"}],"memo":"유선(802.3)은 충돌 탐지(CD), 무선(802.11)은 충돌 회피(CA)."}},{"id":"written-2022-3-80","no":80,"unit":"프로그래밍 언어 활용","q":"아래 C언어 프로그램을 실행한 뒤 ‘c’를 입력하면 출력되는 결과는?<pre class=\"qcode\"><code class=\"language-c\">#include &lt;stdio.h&gt;\nmain() {\n    char ch;\n    scanf(\"%c\", &amp;ch);\n    switch (ch) {\n    case 'a':\n        printf(\"one \");\n    case 'b':\n        printf(\"two \");\n    case 'c':\n        printf(\"three \");\n        break;\n    case 'd':\n        printf(\"four \");\n        break;\n    }\n}</code></pre>","choices":["one two three four","three","one","one two"],"ans":2,"exp":{"concept":"C의 switch 문은 일치하는 case로 이동한 뒤 break를 만날 때까지 아래 case의 문장들을 계속 실행한다(fall-through). 입력이 'c'이면 case 'c'로 바로 이동하므로 그 위의 case 'a', 'b'는 실행되지 않는다.","choices":[{"verdict":"오답","why":"one two three four는 break가 하나도 없을 때 'a'를 입력한 경우의 결과다. case 'c' 끝에 break가 있어 four는 출력되지 않는다."},{"verdict":"정답","why":"'c'를 입력하면 case 'c'로 이동해 three를 출력하고 바로 break를 만나 switch를 빠져나가므로 three만 출력된다."},{"verdict":"오답","why":"one은 case 'a'에서 출력되는데, 'c'를 입력하면 case 'a'를 건너뛴다."},{"verdict":"오답","why":"one two는 'a'나 'b'를 입력했을 때 실행되는 문장으로, 'c' 입력 시에는 실행되지 않는다."}],"keywords":[{"term":"switch-case","desc":"식의 값과 일치하는 case로 이동해 실행"},{"term":"break","desc":"switch 블록을 빠져나감"},{"term":"fall-through","desc":"break가 없으면 다음 case까지 이어서 실행"},{"term":"default","desc":"일치하는 case가 없을 때 실행"}],"memo":"case는 '어디서 시작할지', break는 '어디서 멈출지'를 정한다. 위쪽 case는 실행되지 않는다."}},{"id":"written-2022-3-81","no":81,"unit":"정보시스템 구축 관리","q":"무선 랜(WLAN)의 인증과 암호화에 관해 Wi-Fi에서 제정한 표준은?","choices":["SHA","SSL","WCDMA","WPA"],"ans":4,"exp":{"concept":"WPA(Wi-Fi Protected Access)는 Wi-Fi Alliance가 무선 랜의 인증과 암호화를 위해 만든 보안 표준이다. 취약했던 WEP를 대체하려고 등장했으며, 이후 WPA2, WPA3로 강화되었다.","choices":[{"verdict":"오답","why":"SHA(Secure Hash Algorithm)는 데이터의 해시 값을 만드는 해시 알고리즘이다."},{"verdict":"오답","why":"SSL(Secure Sockets Layer)은 웹 통신 등 전송 구간을 암호화하는 보안 프로토콜로 무선 랜 전용 표준이 아니다."},{"verdict":"오답","why":"WCDMA(Wideband Code Division Multiple Access)는 3세대(3G) 이동통신 기술이다."},{"verdict":"정답","why":"WPA는 Wi-Fi에서 제정한 무선 랜 인증 및 암호화 표준이다."}],"keywords":[{"term":"WPA(Wi-Fi Protected Access)","desc":"Wi-Fi Alliance의 무선 랜 보안 표준"},{"term":"WEP(Wired Equivalent Privacy)","desc":"초기 무선 랜 암호화 방식, 취약"},{"term":"WPA2","desc":"AES 기반 CCMP를 사용하는 강화된 표준"},{"term":"SSL/TLS","desc":"전송 계층 보안 프로토콜"}],"memo":"W(Wi-Fi) P(Protected) A(Access), 이름에 Wi-Fi가 들어 있다."}},{"id":"written-2022-3-82","no":82,"unit":"정보시스템 구축 관리","q":"네트워크 장비에 관한 설명 중 옳지 않은 것은?","choices":["브라우터는 전송되는 신호가 전송 선로의 특성이나 외부 충격 등의 요인 때문에 원래의 형태와 다르게 왜곡되거나 약해질 때 원래의 신호 형태로 재생하여 다시 전송하는 역할을 한다.","스위치는 LAN과 LAN을 연결하여 훨씬 더 큰 LAN을 구성하는 장치로서, OSI 7계층의 2계층에서 사용된다.","라우터는 LAN과 LAN의 연결 기능에 데이터 전송의 최적 경로를 선택하는 기능이 더해진 것으로, 서로 다른 LAN이나 LAN과 WAN의 연결도 수행하며, OSI 7계층의 네트워크 계층에서 동작한다.","브리지는 LAN과 LAN을 연결하거나 LAN 내부의 컴퓨터 그룹을 연결하는 기능을 하며, 데이터 링크 계층 중 MAC 계층에서 사용된다."],"ans":1,"exp":{"concept":"네트워크 장비는 동작하는 계층에 따라 구분한다. 리피터는 1계층에서 약해진 신호를 재생하고, 브리지와 스위치는 2계층에서 LAN을 연결하며, 라우터는 3계층에서 최적 경로를 선택한다. 브라우터(Brouter)는 브리지와 라우터의 기능을 함께 가진 장비다.","choices":[{"verdict":"정답","why":"약해지거나 왜곡된 신호를 원래 형태로 재생해 다시 전송하는 장비는 리피터(Repeater)다. 브라우터는 브리지와 라우터 기능을 결합한 장비다."},{"verdict":"오답","why":"스위치는 LAN과 LAN을 연결해 더 큰 LAN을 만드는 2계층 장비이므로 옳은 설명이다."},{"verdict":"오답","why":"라우터는 최적 경로 선택 기능을 가지고 서로 다른 LAN이나 LAN과 WAN을 연결하는 3계층 장비이므로 옳은 설명이다."},{"verdict":"오답","why":"브리지는 LAN과 LAN 또는 LAN 내 컴퓨터 그룹을 연결하는 데이터 링크 계층(MAC 부계층) 장비이므로 옳은 설명이다."}],"keywords":[{"term":"리피터(Repeater)","desc":"1계층, 신호 재생·증폭"},{"term":"브리지(Bridge)","desc":"2계층, LAN과 LAN 연결"},{"term":"스위치(Switch)","desc":"2계층, 포트별 전용 대역폭으로 LAN 연결"},{"term":"라우터(Router)","desc":"3계층, 최적 경로 선택"},{"term":"브라우터(Brouter)","desc":"브리지와 라우터 기능을 결합한 장비"}],"memo":"신호 재생은 리피터. 브라우터는 브리지(Bridge)+라우터(Router)의 합성어다."}},{"id":"written-2022-3-83","no":83,"unit":"정보시스템 구축 관리","q":"다음 중 세션 하이재킹의 탐지 방법과 거리가 먼 것은?","choices":["패킷의 유실 및 재전송 증가 탐지","ACK STORM 탐지","비동기화 상태 탐지","FTP SYN SEGMENT 탐지"],"ans":4,"exp":{"concept":"세션 하이재킹(Session Hijacking)은 정상 사용자의 연결(세션)을 가로채는 공격이다. 공격 과정에서 비정상적인 흔적이 생기므로 비동기화 상태 탐지, ACK 스톰(ACK Storm) 탐지, 패킷 유실 및 재전송 증가 탐지, 예상치 못한 접속 리셋 탐지로 알아챌 수 있다.","choices":[{"verdict":"오답","why":"공격 중 패킷 유실과 재전송이 늘어나므로 세션 하이재킹 탐지 방법이다."},{"verdict":"오답","why":"서버와 클라이언트의 순서 번호가 어긋나 ACK 패킷이 폭주하는 ACK 스톰은 세션 하이재킹 탐지 방법이다."},{"verdict":"오답","why":"서버와 클라이언트의 순서 번호가 맞지 않는 비동기화 상태를 확인하는 것은 세션 하이재킹 탐지 방법이다."},{"verdict":"정답","why":"FTP SYN SEGMENT 탐지는 세션 하이재킹 탐지 방법에 해당하지 않는다."}],"keywords":[{"term":"세션 하이재킹(Session Hijacking)","desc":"정상 사용자의 세션을 가로채는 공격"},{"term":"비동기화 상태","desc":"서버와 클라이언트의 순서 번호가 어긋난 상태"},{"term":"ACK 스톰(ACK Storm)","desc":"어긋난 순서 번호를 맞추려 ACK가 폭주하는 현상"},{"term":"탐지 방법 4가지","desc":"비동기화 상태, ACK 스톰, 패킷 유실·재전송 증가, 예상치 못한 접속 리셋"}],"memo":"세션 하이재킹은 순서 번호를 어긋나게 만드는 공격이라 '비동기화'와 그 결과(ACK 스톰, 재전송)를 탐지한다."}},{"id":"written-2022-3-84","no":84,"unit":"정보시스템 구축 관리","q":"클라우드 기반 HSM(Cloud-based Hardware Security Module)에 관한 설명 중 틀린 것은?","choices":["클라우드(데이터센터)를 기반으로 암호화 키의 생성, 처리, 저장 등을 수행하는 보안 기기이다.","인증서를 클라우드에 저장하므로 기존 HSM 기기나 휴대폰에 인증서를 저장해 다닐 필요가 없다.","하드웨어가 아닌 소프트웨어적으로만 구현되므로 소프트웨어식 암호 기술에 내재된 보안 취약점을 해결할 수 없다는 점이 주요 단점이다.","국내에서는 공인인증제 폐지와 전자서명법 개정이 추진되면서 클라우드 HSM이라는 용어가 자주 등장하였다."],"ans":3,"exp":{"concept":"HSM(Hardware Security Module)은 암호화 키를 안전하게 생성하고 저장하는 전용 보안 하드웨어다. 클라우드 HSM은 이 하드웨어를 클라우드(데이터센터)에 두고 서비스 형태로 쓰는 것으로, 하드웨어로 구현되어 소프트웨어 방식 암호 기술의 취약점을 보완할 수 있다.","choices":[{"verdict":"오답","why":"클라우드(데이터센터)에서 암호화 키의 생성, 처리, 저장을 수행하는 보안 기기이므로 옳은 설명이다."},{"verdict":"오답","why":"인증서를 클라우드에 저장하므로 HSM 기기나 휴대폰에 인증서를 따로 들고 다닐 필요가 없다. 옳은 설명이다."},{"verdict":"정답","why":"클라우드 HSM은 이름 그대로 하드웨어로 구현된 보안 모듈이므로, 소프트웨어식 암호 기술에 내재된 보안 취약점을 해결할 수 있다는 것이 장점이다."},{"verdict":"오답","why":"국내에서 공인인증제 폐지와 전자서명법 개정이 추진되면서 클라우드 HSM이라는 용어가 자주 등장했으므로 옳은 설명이다."}],"keywords":[{"term":"HSM(Hardware Security Module)","desc":"암호화 키를 생성·저장·보호하는 전용 보안 하드웨어"},{"term":"클라우드 HSM","desc":"데이터센터의 HSM을 클라우드 서비스로 이용"},{"term":"전자서명법 개정","desc":"공인인증서의 독점적 지위를 폐지한 법 개정"}],"memo":"HSM의 H는 Hardware다. '소프트웨어적으로만 구현'은 이름과 정면으로 모순된다."}},{"id":"written-2022-3-85","no":85,"unit":"정보시스템 구축 관리","q":"다음 중 정보 보안의 3요소에 속하지 않는 것은?","choices":["기밀성","가용성","무결성","휘발성"],"ans":4,"exp":{"concept":"정보 보안의 3요소는 기밀성(Confidentiality), 무결성(Integrity), 가용성(Availability)으로, 영문 첫 글자를 따 CIA라고 부른다. 기밀성은 허가된 사람만 볼 수 있게, 무결성은 허가된 사람만 고칠 수 있게, 가용성은 허가된 사람이 필요할 때 쓸 수 있게 하는 것이다.","choices":[{"verdict":"오답","why":"기밀성은 인가된 사용자만 정보에 접근할 수 있게 하는 보안 3요소다."},{"verdict":"오답","why":"가용성은 인가된 사용자가 필요할 때 언제든 자원을 사용할 수 있게 하는 보안 3요소다."},{"verdict":"오답","why":"무결성은 인가된 사용자만 정보를 수정할 수 있게 하는 보안 3요소다."},{"verdict":"정답","why":"휘발성은 전원이 꺼지면 데이터가 사라지는 메모리의 성질로, 정보 보안 요소가 아니다."}],"keywords":[{"term":"기밀성(Confidentiality)","desc":"인가된 사용자만 접근"},{"term":"무결성(Integrity)","desc":"인가된 사용자만 수정"},{"term":"가용성(Availability)","desc":"인가된 사용자가 언제든 사용"},{"term":"인증(Authentication)","desc":"사용자가 합법적인지 확인"},{"term":"부인 방지(Non-repudiation)","desc":"송수신 사실을 부인하지 못하게 함"}],"memo":"보안 3요소는 CIA, 미국 중앙정보국 이름과 같다."}},{"id":"written-2022-3-86","no":86,"unit":"정보시스템 구축 관리","q":"악성코드의 유형 가운데 다른 컴퓨터의 취약점을 이용해 스스로 전파되거나 메일을 통해 전파되면서 스스로를 증식하는 것은?","choices":["Adware","Rogue Ware","Reflection Attack","Worm"],"ans":4,"exp":{"concept":"웜(Worm)은 다른 프로그램에 붙지 않고 독자적으로 실행되며, 네트워크나 이메일을 통해 스스로를 복제해 퍼뜨리는 악성코드다. 숙주 파일이 있어야 감염되는 바이러스와 달리 혼자서 증식한다는 점이 특징이다.","choices":[{"verdict":"오답","why":"애드웨어(Adware)는 사용자 동의 없이 광고를 띄우는 프로그램이다."},{"verdict":"오답","why":"로그웨어(Rogue Ware)는 백신 프로그램처럼 위장해 가짜 감염 경고를 띄우고 결제나 설치를 유도하는 악성 프로그램이다."},{"verdict":"오답","why":"리플렉션 공격(Reflection Attack)은 공격 기법의 하나로, 스스로 복제해 퍼지는 악성코드 유형이 아니다."},{"verdict":"정답","why":"웜은 시스템 취약점이나 메일을 이용해 스스로 전파·증식하는 악성코드다."}],"keywords":[{"term":"웜(Worm)","desc":"독자적으로 실행되며 스스로 복제·전파"},{"term":"바이러스(Virus)","desc":"다른 파일에 기생해 감염시키는 악성코드"},{"term":"트로이 목마(Trojan Horse)","desc":"정상 프로그램으로 위장, 자기 복제 없음"},{"term":"애드웨어(Adware)","desc":"광고를 띄우는 프로그램"},{"term":"로그웨어(Rogue Ware)","desc":"가짜 백신 프로그램"}],"memo":"스스로 기어다니며 퍼지는 벌레(Worm). 숙주가 필요하면 바이러스, 위장하면 트로이 목마."}},{"id":"written-2022-3-87","no":87,"unit":"정보시스템 구축 관리","q":"LOC 기법으로 예측한 총 라인수가 36,000라인이고, 개발에 참여하는 프로그래머가 6명, 프로그래머들의 평균 생산성이 월간 300라인이라고 할 때 개발에 소요되는 기간은?","choices":["5개월","10개월","15개월","20개월"],"ans":4,"exp":{"concept":"LOC(Line Of Code) 기법은 예상되는 소스 코드 줄 수로 개발 노력과 기간을 추정한다. 노력(인월) = 총 라인 수 ÷ 1인당 월평균 생산성이고, 개발 기간 = 노력 ÷ 투입 인원이다. 한 번에 구하면 기간 = 총 라인 수 ÷ (인원 × 1인당 월 생산성)이다.","choices":[{"verdict":"오답","why":"5개월이면 6명이 매월 1,800라인씩 9,000라인만 만든 것이다."},{"verdict":"오답","why":"10개월이면 18,000라인만 만든 것이다."},{"verdict":"오답","why":"15개월이면 27,000라인만 만든 것이다."},{"verdict":"정답","why":"노력 = 36,000 ÷ 300 = 120인월, 기간 = 120 ÷ 6 = 20개월이다."}],"keywords":[{"term":"LOC(Line Of Code) 기법","desc":"원시 코드 라인 수로 비용·기간을 추정"},{"term":"노력(인월, Man-Month)","desc":"총 라인 수 ÷ 1인당 월평균 생산성"},{"term":"개발 기간","desc":"노력(인월) ÷ 투입 인원"},{"term":"개발 비용","desc":"노력(인월) × 1인당 월평균 인건비"}],"memo":"6명이 한 달에 300라인씩이면 팀 전체는 한 달에 1,800라인. 36,000 ÷ 1,800 = 20."}},{"id":"written-2022-3-88","no":88,"unit":"정보시스템 구축 관리","q":"CPM(Critical Path Method)에 관한 설명 중 옳지 않은 것은?","choices":["경영층의 과학적 의사 결정을 지원한다.","프로젝트 내 각 작업의 수행 시간과 작업 간의 관계를 파악할 수 있다.","작업 일정을 한눈에 볼 수 있게 해주며, 막대 그래프 형태로 표현한다.","프로젝트의 효과적인 통제를 가능하게 해 준다."],"ans":3,"exp":{"concept":"CPM(Critical Path Method, 임계 경로 기법)은 프로젝트의 작업들을 노드와 간선으로 이루어진 네트워크로 그려, 각 작업의 소요 시간과 선후 관계를 파악하고 전체 일정을 결정하는 가장 긴 경로(임계 경로)를 찾는 기법이다. 일정을 막대 그래프로 보여 주는 것은 간트 차트(Gantt Chart)다.","choices":[{"verdict":"오답","why":"CPM은 일정과 자원 배분에 대한 과학적인 의사 결정을 지원하므로 옳은 설명이다."},{"verdict":"오답","why":"CPM은 각 작업의 수행 시간과 작업 사이의 선후 관계를 네트워크로 파악할 수 있으므로 옳은 설명이다."},{"verdict":"정답","why":"작업 일정을 막대 그래프 형태로 표현하는 것은 간트 차트다. CPM은 노드와 간선으로 된 네트워크 형태로 표현한다."},{"verdict":"오답","why":"임계 경로를 알면 지연되면 안 되는 작업을 중점 관리할 수 있어 효과적인 통제가 가능하므로 옳은 설명이다."}],"keywords":[{"term":"CPM(Critical Path Method)","desc":"네트워크로 임계 경로를 찾는 일정 관리 기법"},{"term":"임계 경로(Critical Path)","desc":"시작부터 끝까지 가장 오래 걸리는 경로, 전체 기간을 결정"},{"term":"PERT","desc":"낙관·보통·비관 시간으로 불확실한 일정을 추정"},{"term":"간트 차트(Gantt Chart)","desc":"작업 일정을 막대 그래프로 표시"}],"memo":"막대 그래프 = 간트 차트, 네트워크 그래프 = CPM·PERT."}},{"id":"written-2022-3-89","no":89,"unit":"정보시스템 구축 관리","q":"SQL Injection 공격에 관한 설명으로 옳지 않은 것은?","choices":["로그인처럼 웹에서 사용자의 입력 값을 받아 데이터베이스 SQL문으로 데이터를 요청하는 경우 SQL Injection이 가능하다.","SQL Injection 공격 기법은 DBMS의 종류와 관계없이 모두 동일하다.","SQL Injection 취약점은 주로 웹 애플리케이션과 데이터베이스가 연동되는 부분에서 발생한다.","SQL Injection은 임의로 작성한 SQL 구문을 애플리케이션에 삽입하는 공격 기법이다."],"ans":2,"exp":{"concept":"SQL 삽입(SQL Injection)은 웹 입력란에 SQL 구문을 끼워 넣어, 원래 의도와 다른 SQL이 데이터베이스에서 실행되게 만드는 공격이다. 로그인 우회나 정보 유출에 쓰인다. DBMS마다 SQL 문법, 주석 기호, 오류 메시지, 시스템 테이블이 다르므로 공격 기법도 DBMS에 따라 달라진다.","choices":[{"verdict":"오답","why":"로그인처럼 사용자 입력으로 SQL을 만들어 데이터를 요청하는 곳에서 SQL 삽입이 가능하므로 옳은 설명이다."},{"verdict":"정답","why":"DBMS마다 문법, 주석 처리, 시스템 객체가 달라 공격 구문도 달라진다. DBMS 종류와 관계없이 모두 같다는 것은 틀렸다."},{"verdict":"오답","why":"SQL 삽입 취약점은 웹 애플리케이션이 데이터베이스와 연동되는 부분에서 주로 발생하므로 옳은 설명이다."},{"verdict":"오답","why":"SQL 삽입은 임의로 작성한 SQL 구문을 애플리케이션에 삽입하는 공격이므로 옳은 설명이다."}],"keywords":[{"term":"SQL 삽입(SQL Injection)","desc":"입력값에 SQL을 끼워 넣어 DB를 조작하는 공격"},{"term":"입력값 검증","desc":"특수문자 필터링 등으로 입력을 검사"},{"term":"PreparedStatement","desc":"SQL과 입력값을 분리해 SQL 삽입을 막는 방법"},{"term":"크로스사이트 스크립트(XSS)","desc":"웹 페이지에 악성 스크립트를 삽입하는 공격"}],"memo":"'모두 동일하다', '항상', '반드시'처럼 단정하는 보기는 틀린 경우가 많다."}},{"id":"written-2022-3-90","no":90,"unit":"정보시스템 구축 관리","q":"침입탐지 시스템(IDS : Intrusion Detection System)에 대한 설명 중 틀린 것은?","choices":["NIDS(Network-Based Intrusion Detection System)의 대표적인 예로는 Snort가 있다.","외부 인터넷에 서비스를 제공하는 서버가 위치한 네트워크인 DMZ(Demilitarized Zone)에는 IDS를 설치할 수 있다.","이상 탐지 기법(Anomaly Detection)은 Signature Base 또는 Knowledge Base라고도 불리며, 이미 발견되어 정립된 공격 패턴을 입력해두었다가 탐지 및 차단한다.","HIDS(Host-Based Intrusion Detection)는 운영체제에 설정된 사용자 계정에 따라 어떤 사용자가 어떤 접근을 시도했고 어떤 작업을 했는지 기록을 남겨 추적한다."],"ans":3,"exp":{"concept":"침입 탐지 시스템(IDS)은 시스템이나 네트워크에 대한 비정상 접근을 탐지하는 보안 시스템이다. 탐지 방식은 두 가지다. 오용 탐지(Misuse Detection)는 이미 알려진 공격 패턴(시그니처)과 비교해 탐지하고, 이상 탐지(Anomaly Detection)는 평소의 정상 행동과 다른 비정상 행위를 찾아 탐지한다.","choices":[{"verdict":"오답","why":"Snort는 대표적인 오픈 소스 네트워크 기반 침입 탐지 시스템(NIDS)이므로 옳은 설명이다."},{"verdict":"오답","why":"외부에 서비스를 제공하는 서버가 있는 DMZ에는 IDS를 설치할 수 있으므로 옳은 설명이다."},{"verdict":"정답","why":"Signature Base 또는 Knowledge Base로 불리며 알려진 공격 패턴을 이용하는 것은 오용 탐지(Misuse Detection)다. 이상 탐지는 정상 행동에서 벗어난 행위를 찾는 방식이다."},{"verdict":"오답","why":"HIDS는 호스트(운영체제)에 설치되어 어떤 사용자가 어떤 접근과 작업을 했는지 기록하고 추적하므로 옳은 설명이다."}],"keywords":[{"term":"오용 탐지(Misuse Detection)","desc":"알려진 공격 패턴(시그니처)과 비교, Signature/Knowledge Base"},{"term":"이상 탐지(Anomaly Detection)","desc":"정상 행동 기준에서 벗어난 행위 탐지, Behavior/Statistical"},{"term":"NIDS(Network-Based IDS)","desc":"네트워크 트래픽을 감시, 예: Snort"},{"term":"HIDS(Host-Based IDS)","desc":"호스트의 로그와 사용자 행위를 감시"},{"term":"DMZ(Demilitarized Zone)","desc":"내부망과 외부망 사이의 완충 구역"}],"memo":"알려진 패턴(시그니처)은 오용 탐지, 평소와 다름은 이상 탐지."}},{"id":"written-2022-3-91","no":91,"unit":"정보시스템 구축 관리","q":"다음 설명에 해당하는 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>네트워크상에서 광채널 스위치의 이점인 고속 전송, 장거리 연결 및 멀티 프로토콜 기능을 활용함</li><li>서로 다른 운영체제를 가진 여러 기종이 네트워크상에서 동일 저장장치의 데이터를 공유하도록 하여, 여러 개의 저장장치나 백업 장비를 단일화한 시스템</li></ul></div>","choices":["NIC","NAC","SAN","MBR"],"ans":3,"exp":{"concept":"SAN(Storage Area Network)은 서버와 저장 장치를 광채널(Fibre Channel) 스위치로 연결한 전용 고속 네트워크다. 서로 다른 운영체제의 여러 서버가 같은 저장 장치를 공유할 수 있게 하고, 흩어진 저장 장치와 백업 장비를 하나로 통합해 관리한다.","choices":[{"verdict":"오답","why":"NIC(Network Interface Card)는 컴퓨터를 네트워크에 연결하는 랜 카드다."},{"verdict":"오답","why":"NAC(Network Access Control)는 네트워크에 접속하는 단말의 보안 상태를 확인해 접근을 통제하는 솔루션이다."},{"verdict":"정답","why":"광채널 스위치로 연결하고 여러 기종이 동일 저장 장치의 데이터를 공유하도록 저장 장치를 단일화한 것은 SAN이다."},{"verdict":"오답","why":"MBR(Master Boot Record)은 디스크 첫 섹터에 있는 부팅 정보와 파티션 정보 영역이다."}],"keywords":[{"term":"SAN(Storage Area Network)","desc":"광채널 스위치 기반 전용 저장 네트워크"},{"term":"NAS(Network Attached Storage)","desc":"LAN에 연결해 파일 단위로 공유하는 저장 장치"},{"term":"DAS(Direct Attached Storage)","desc":"서버에 직접 연결한 저장 장치"},{"term":"광채널(Fibre Channel)","desc":"고속 저장 장치 연결용 네트워크 기술"}],"memo":"저장 장치 연결 방식 'DAS-NAS-SAN'. 광채널 스위치가 나오면 SAN이다."}},{"id":"written-2022-3-92","no":92,"unit":"정보시스템 구축 관리","q":"소프트웨어 재공학의 주요 활동 가운데, 기존 소프트웨어를 다른 운영체제나 하드웨어 환경에서도 사용할 수 있게 변환하는 활동은?","choices":["재구성","분석","이식","역공학"],"ans":3,"exp":{"concept":"소프트웨어 재공학(Re-engineering)은 기존 소프트웨어를 버리지 않고 다시 다듬어 품질과 유지보수성을 높이는 활동이다. 주요 활동은 분석, 재구성, 역공학, 이식 네 가지다. 이식(Migration)은 기존 소프트웨어를 다른 운영체제나 하드웨어 환경에서 쓸 수 있도록 변환하는 활동이다.","choices":[{"verdict":"오답","why":"재구성(Restructuring)은 기능은 그대로 두고 같은 수준에서 코드의 형태(구조)를 바꾸는 활동이다."},{"verdict":"오답","why":"분석(Analysis)은 기존 소프트웨어의 명세를 확인하고 재공학 대상을 선정하는 활동이다."},{"verdict":"정답","why":"이식(Migration)은 기존 소프트웨어를 다른 운영체제나 하드웨어 환경에서 사용할 수 있도록 변환하는 활동이다."},{"verdict":"오답","why":"역공학(Reverse Engineering)은 기존 코드나 실행 파일에서 설계 정보나 명세를 거꾸로 뽑아내는 활동이다."}],"keywords":[{"term":"소프트웨어 재공학(Re-engineering)","desc":"기존 소프트웨어를 개선해 재사용하는 활동"},{"term":"분석(Analysis)","desc":"명세 확인, 재공학 대상 선정"},{"term":"재구성(Restructuring)","desc":"같은 추상화 수준에서 코드 형태 변경"},{"term":"역공학(Reverse Engineering)","desc":"코드로부터 설계·명세를 추출"},{"term":"이식(Migration)","desc":"다른 환경에서 동작하도록 변환"}],"memo":"재공학 활동 '분재역이'(분석-재구성-역공학-이식). 환경을 옮기면 이식."}},{"id":"written-2022-3-93","no":93,"unit":"정보시스템 구축 관리","q":"다음의 암호 알고리즘 가운데 성격이 다른 하나는?","choices":["AES","SHA-1","MD4","MD5"],"ans":1,"exp":{"concept":"암호 알고리즘은 복호화가 가능한 양방향 암호(대칭키, 공개키)와 복호화가 불가능한 일방향 해시 함수로 나뉜다. AES는 대칭키 블록 암호이고, SHA-1, MD4, MD5는 임의 길이 입력을 고정 길이 값으로 바꾸는 해시 함수다.","choices":[{"verdict":"정답","why":"AES는 암호화와 복호화가 모두 가능한 대칭키 블록 암호 알고리즘으로, 나머지 해시 함수와 성격이 다르다."},{"verdict":"오답","why":"SHA-1은 160비트 해시 값을 만드는 해시 함수다."},{"verdict":"오답","why":"MD4는 128비트 해시 값을 만드는 해시 함수다."},{"verdict":"오답","why":"MD5는 MD4를 개선한 128비트 해시 함수다."}],"keywords":[{"term":"AES(Advanced Encryption Standard)","desc":"NIST 표준 대칭키 블록 암호"},{"term":"해시 함수(Hash Function)","desc":"임의 길이 입력을 고정 길이 값으로 바꾸는 일방향 함수"},{"term":"SHA(Secure Hash Algorithm)","desc":"NIST/NSA가 만든 해시 함수 계열"},{"term":"MD5(Message Digest 5)","desc":"128비트 해시 값을 만드는 해시 함수"}],"memo":"SHA와 MD는 해시, AES·DES·SEED·ARIA는 대칭키 블록 암호."}},{"id":"written-2022-3-94","no":94,"unit":"정보시스템 구축 관리","q":"COCOMO 모델을 이용한 비용 산정에 관한 설명 중 옳지 않은 것은?","choices":["규모가 같은 소프트웨어라 하더라도 유형에 따라 비용이 다르게 산정된다.","비용 산정 유형에는 Organic Mode, Embedded Mode, Semi-Detached Mode가 있다.","보헴이 제안한 모형으로, 원시 프로그램의 규모에 따라 비용을 예측한다.","UFP(Unadjusted Function Point)를 계산하는 방식이다."],"ans":4,"exp":{"concept":"COCOMO(Constructive Cost Model)는 보헴(Boehm)이 제안한 비용 산정 모형으로, 예상 원시 코드 라인 수(KDSI)를 바탕으로 비용을 계산한다. 소프트웨어 유형을 조직형(Organic), 반분리형(Semi-Detached), 내장형(Embedded)으로 나누어 같은 규모라도 유형에 따라 다른 식을 적용한다.","choices":[{"verdict":"오답","why":"같은 규모라도 조직형, 반분리형, 내장형 중 어느 유형인지에 따라 비용이 다르게 산정되므로 옳은 설명이다."},{"verdict":"오답","why":"비용 산정 유형에는 Organic, Semi-Detached, Embedded Mode가 있으므로 옳은 설명이다."},{"verdict":"오답","why":"COCOMO는 보헴이 제안했으며 원시 프로그램의 규모(LOC)로 비용을 예측하므로 옳은 설명이다."},{"verdict":"정답","why":"UFP(조정 전 기능 점수)를 계산하는 것은 기능 점수(FP, Function Point) 기법이다. COCOMO는 코드 라인 수를 기반으로 한다."}],"keywords":[{"term":"COCOMO","desc":"보헴이 제안, LOC(KDSI) 기반 비용 산정 모형"},{"term":"조직형(Organic)","desc":"5만 라인 이하의 중소 규모 업무용 소프트웨어"},{"term":"반분리형(Semi-Detached)","desc":"30만 라인 이하의 중간 규모, 운영체제·DBMS 등"},{"term":"내장형(Embedded)","desc":"30만 라인 이상, 하드웨어와 밀접한 대형 시스템"},{"term":"기능 점수(Function Point)","desc":"기능의 수와 복잡도로 규모를 측정, UFP 사용"}],"memo":"COCOMO는 라인 수, FP는 기능 수. UFP의 F는 Function이다."}},{"id":"written-2022-3-95","no":95,"unit":"정보시스템 구축 관리","q":"정보 보안 요소 가운데 무결성(Integrity)에 관한 설명으로 옳은 것은?","choices":["시스템 내의 정보는 오직 인가된 사용자만이 수정할 수 있음을 의미한다.","시스템 내의 정보와 자원은 인가된 사용자에게만 접근이 허용됨을 의미한다.","인가받은 사용자는 언제라도 사용할 수 있음을 의미한다.","시스템 내의 정보와 자원을 사용하려는 사용자가 합법적인 사용자인지 확인하는 모든 행위를 말한다."],"ans":1,"exp":{"concept":"무결성(Integrity)은 정보가 허가 없이 바뀌지 않도록, 인가된 사용자만 수정할 수 있게 보장하는 보안 요소다. 기밀성은 접근(열람), 가용성은 사용 가능 시점, 인증은 사용자 확인에 관한 개념이다.","choices":[{"verdict":"정답","why":"시스템 내의 정보를 오직 인가된 사용자만 수정할 수 있다는 것이 무결성이다."},{"verdict":"오답","why":"인가된 사용자에게만 정보와 자원에 대한 접근을 허용하는 것은 기밀성(Confidentiality)이다."},{"verdict":"오답","why":"인가받은 사용자가 언제라도 사용할 수 있다는 것은 가용성(Availability)이다."},{"verdict":"오답","why":"사용자가 합법적인 사용자인지 확인하는 행위는 인증(Authentication)이다."}],"keywords":[{"term":"무결성(Integrity)","desc":"인가된 사용자만 수정 가능"},{"term":"기밀성(Confidentiality)","desc":"인가된 사용자만 접근 가능"},{"term":"가용성(Availability)","desc":"인가된 사용자가 언제든 사용 가능"},{"term":"인증(Authentication)","desc":"합법적인 사용자인지 확인"}],"memo":"무결성은 '고치기', 기밀성은 '보기', 가용성은 '쓰기 가능', 인증은 '누구인지 확인'."}},{"id":"written-2022-3-96","no":96,"unit":"정보시스템 구축 관리","q":"브리지와 구내 정보 통신망(LAN)으로 이루어진 통신망에서 루프(폐회로)가 형성되지 않도록 연결을 설정하는 알고리즘은?","choices":["Spanning Tree Algorithm","Hash Algorithm","Diffie-Hellman Algorithm","Digital Signature Algorithm"],"ans":1,"exp":{"concept":"브리지나 스위치로 LAN을 여러 경로로 연결하면 프레임이 계속 돌고 도는 루프(브로드캐스트 폭풍)가 생길 수 있다. 스패닝 트리 알고리즘(STA, Spanning Tree Algorithm)은 일부 포트를 막아 루프 없는 트리 구조를 만들어 이를 방지한다. 이를 구현한 프로토콜이 STP(IEEE 802.1D)다.","choices":[{"verdict":"정답","why":"스패닝 트리 알고리즘은 브리지와 LAN으로 된 망에서 루프가 생기지 않도록 연결을 설정한다."},{"verdict":"오답","why":"해시 알고리즘은 임의 길이 데이터를 고정 길이 값으로 바꾸는 알고리즘으로 루프 방지와 관련이 없다."},{"verdict":"오답","why":"디피-헬먼(Diffie-Hellman) 알고리즘은 안전하지 않은 통신망에서 두 사람이 비밀 키를 교환하는 키 교환 알고리즘이다."},{"verdict":"오답","why":"디지털 서명 알고리즘(DSA)은 전자 서명을 생성하고 검증하는 알고리즘이다."}],"keywords":[{"term":"스패닝 트리 알고리즘(STA)","desc":"루프 없는 트리 구조로 브리지 망을 구성"},{"term":"STP(Spanning Tree Protocol)","desc":"STA를 구현한 IEEE 802.1D 프로토콜"},{"term":"브로드캐스트 스톰(Broadcast Storm)","desc":"루프로 프레임이 끝없이 증폭되는 현상"},{"term":"디피-헬먼(Diffie-Hellman)","desc":"공개된 망에서 비밀 키를 교환하는 알고리즘"}],"memo":"트리(Tree)에는 순환(루프)이 없다. 루프 방지 = 스패닝 트리."}},{"id":"written-2022-3-97","no":97,"unit":"정보시스템 구축 관리","q":"입력 데이터 검증 및 표현에 관한 설명 중 옳지 않은 것은?","choices":["SQL 삽입 : 웹 응용 프로그램에 SQL을 삽입하여 내부 데이터베이스(DB) 서버의 데이터를 유출·변조하고, 관리자 인증을 우회한다.","자원 삽입 : 악의적인 명령어가 포함된 스크립트 파일을 업로드하여 시스템에 손상을 준다.","운영체제 명령어 삽입 : 외부 입력값을 통해 시스템 명령어의 실행을 유도하여 권한을 탈취하거나 시스템 장애를 일으킨다.","크로스사이트 스크립트 : 웹페이지에 악의적인 스크립트를 삽입해 방문자들의 정보를 탈취한다."],"ans":2,"exp":{"concept":"입력 데이터 검증 및 표현은 시큐어 코딩 점검 항목 중 하나로, 외부 입력을 검증하지 않아 생기는 보안 약점을 다룬다. SQL 삽입, 자원 삽입, 운영체제 명령어 삽입, 크로스사이트 스크립트(XSS), 위험한 형식 파일 업로드 등이 있다. 자원 삽입은 외부 입력값을 검증 없이 파일, 소켓 포트 같은 시스템 자원의 식별자로 사용해 자원을 변경하거나 부당하게 접근하게 되는 약점이다.","choices":[{"verdict":"오답","why":"SQL 삽입은 SQL을 끼워 넣어 DB 데이터를 유출·변조하고 인증을 우회하는 공격이므로 옳은 설명이다."},{"verdict":"정답","why":"악의적인 스크립트 파일을 업로드해 시스템을 손상시키는 것은 위험한 형식 파일 업로드에 대한 설명이다. 자원 삽입은 외부 입력값을 시스템 자원의 식별자로 사용해 자원에 부당하게 접근하게 하는 약점이다."},{"verdict":"오답","why":"운영체제 명령어 삽입은 외부 입력으로 시스템 명령 실행을 유도해 권한을 빼앗거나 장애를 일으키므로 옳은 설명이다."},{"verdict":"오답","why":"크로스사이트 스크립트(XSS)는 웹 페이지에 악성 스크립트를 삽입해 방문자의 정보를 빼내므로 옳은 설명이다."}],"keywords":[{"term":"자원 삽입(Resource Injection)","desc":"외부 입력값을 시스템 자원 식별자로 사용해 생기는 약점"},{"term":"위험한 형식 파일 업로드","desc":"악성 스크립트 파일을 올려 서버에서 실행되게 하는 약점"},{"term":"운영체제 명령어 삽입","desc":"외부 입력으로 OS 명령을 실행하게 하는 약점"},{"term":"크로스사이트 스크립트(XSS)","desc":"웹 페이지에 악성 스크립트를 삽입하는 공격"}],"memo":"파일을 '올려서' 공격하면 위험한 형식 파일 업로드, 자원 '이름(식별자)'을 조작하면 자원 삽입."}},{"id":"written-2022-3-98","no":98,"unit":"정보시스템 구축 관리","q":"기존 무선 랜의 한계를 극복하고자 등장한 것으로, 대규모 디바이스의 네트워크 생성에 최적화되어 차세대 이동통신, 홈네트워킹, 공공 안전 등 특수목적에 활용되는 새로운 방식의 네트워크 기술은 무엇인가?","choices":["Local Area Network","Virtual Private Network","Software Defined Perimeter","Mesh Network"],"ans":4,"exp":{"concept":"메시 네트워크(Mesh Network)는 여러 노드(기기)가 그물처럼 서로 직접 연결되어, 각 노드가 데이터를 중계하며 통신하는 네트워크다. 기존 무선 랜의 한계를 보완해 대규모 디바이스 네트워크 구성에 적합하며, 차세대 이동통신, 홈 네트워킹, 공공 안전 같은 특수 목적에 활용된다.","choices":[{"verdict":"오답","why":"LAN(Local Area Network)은 건물이나 학교처럼 좁은 지역의 기기를 연결하는 근거리 통신망이다."},{"verdict":"오답","why":"VPN(Virtual Private Network)은 공중망 위에 암호화된 터널을 만들어 사설망처럼 쓰는 기술이다."},{"verdict":"오답","why":"SDP(Software Defined Perimeter)는 인증된 사용자와 기기에만 접근을 허용하도록 네트워크 경계를 소프트웨어로 정의하는 보안 기술이다."},{"verdict":"정답","why":"대규모 디바이스 네트워크 생성에 최적화되어 차세대 이동통신, 홈 네트워킹, 공공 안전 등에 쓰이는 것은 메시 네트워크다."}],"keywords":[{"term":"메시 네트워크(Mesh Network)","desc":"노드들이 그물처럼 연결되어 서로 중계하는 네트워크"},{"term":"VPN(Virtual Private Network)","desc":"공중망을 사설망처럼 쓰는 가상 사설망"},{"term":"SDP(Software Defined Perimeter)","desc":"소프트웨어로 정의한 접근 경계 보안"},{"term":"애드혹 네트워크(Ad-hoc Network)","desc":"기지국 없이 노드끼리 구성하는 임시 네트워크"}],"memo":"Mesh는 그물망. 대규모 디바이스가 그물처럼 연결되면 메시 네트워크."}},{"id":"written-2022-3-99","no":99,"unit":"정보시스템 구축 관리","q":"다음 설명에 해당하는 암호화 알고리즘은 무엇인가?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>DES의 보안 문제를 해결하고자 개발되었다.</li><li>NIST가 표준으로 채택한 대칭키 암호화 알고리즘이다.</li></ul></div>","choices":["ARIA","SEED","DSA","AES"],"ans":4,"exp":{"concept":"AES(Advanced Encryption Standard)는 DES의 짧은 키(56비트) 때문에 생긴 보안 문제를 해결하려고 NIST(미국 국립표준기술연구소)가 표준으로 채택한 대칭키 블록 암호다. 블록 크기는 128비트이고 키 길이는 128, 192, 256비트 중 선택한다.","choices":[{"verdict":"오답","why":"ARIA는 국가정보원과 산학연이 개발한 국내 대칭키 블록 암호로, NIST가 채택한 표준이 아니다."},{"verdict":"오답","why":"SEED는 한국인터넷진흥원(KISA)이 개발한 국내 대칭키 블록 암호다."},{"verdict":"오답","why":"DSA(Digital Signature Algorithm)는 NIST의 전자 서명 표준 알고리즘으로, 대칭키 암호가 아니다."},{"verdict":"정답","why":"AES는 DES의 보안 문제를 해결하려고 개발되어 NIST가 표준으로 채택한 대칭키 암호 알고리즘이다."}],"keywords":[{"term":"AES(Advanced Encryption Standard)","desc":"NIST 표준 대칭키 블록 암호, 128비트 블록"},{"term":"DES(Data Encryption Standard)","desc":"56비트 키를 쓰는 옛 미국 표준 대칭키 암호"},{"term":"SEED","desc":"KISA가 개발한 국내 블록 암호"},{"term":"ARIA","desc":"국가정보원과 산학연이 개발한 국내 블록 암호"}],"memo":"DES의 후계자 = AES. 국내 개발 블록 암호는 SEED와 ARIA."}},{"id":"written-2022-3-100","no":100,"unit":"정보시스템 구축 관리","q":"다음 설명에 해당하는 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>블록체인(Blockchain) 개발환경을 클라우드 형태로 서비스하는 개념</li><li>블록체인 네트워크에서 노드의 추가와 제거가 용이</li><li>블록체인의 기본 인프라를 추상화하여 블록체인 응용프로그램을 만들 수 있도록 하는 클라우드 컴퓨팅 플랫폼</li></ul></div>","choices":["SDDC","OTT","Wi-SUN","BaaS"],"ans":4,"exp":{"concept":"BaaS(Blockchain as a Service)는 블록체인 앱을 개발하고 운영하는 데 필요한 환경을 클라우드 서비스로 제공하는 것이다. 블록체인 기반 인프라를 추상화해 제공하므로, 개발자는 복잡한 노드 구축 없이 노드를 쉽게 추가·제거하며 응용 프로그램 개발에 집중할 수 있다.","choices":[{"verdict":"오답","why":"SDDC(Software Defined Data Center)는 컴퓨팅, 네트워크, 스토리지 등 데이터센터의 모든 자원을 가상화해 소프트웨어로 관리하는 데이터센터다."},{"verdict":"오답","why":"OTT(Over The Top)는 인터넷을 통해 영화, 드라마 등 미디어 콘텐츠를 제공하는 서비스다."},{"verdict":"오답","why":"Wi-SUN(Wireless Smart Utility Network)은 스마트 그리드 등 장거리 저전력 무선 통신을 위한 기술이다."},{"verdict":"정답","why":"블록체인 개발 환경을 클라우드로 제공하고 노드 추가·제거가 쉬운 플랫폼은 BaaS다."}],"keywords":[{"term":"BaaS(Blockchain as a Service)","desc":"블록체인 개발 환경을 클라우드로 제공"},{"term":"SDDC(Software Defined Data Center)","desc":"모든 자원을 가상화한 소프트웨어 정의 데이터센터"},{"term":"OTT(Over The Top)","desc":"인터넷 기반 미디어 콘텐츠 서비스"},{"term":"Wi-SUN","desc":"스마트 그리드용 장거리 저전력 무선 통신"}],"memo":"XaaS 형식은 'X를 서비스로'. B가 Blockchain이면 BaaS."}}]};